                                <div className="text-[10px] font-mono">LVL {c.profile.level}</div>
                            </div>
                        </button>
                    ))}
                </div>
            )}
            <div className="mt-2 text-[10px] text-slate-600 text-center font-mono">
                Найдено: {filteredCharacters.length} / {allCharacters.length}
            </div>
        </Modal>

        {/* ... Other modals ... */}
        <Modal
            isOpen={activeModal === 'BATTLE_LIST'}
            onClose={closeModal}
            title="Архив Боев"
            footer={
                <button onClick={handleCreateBattleClick} className="w-full py-2 bg-violet-900/50 border border-violet-500/50 text-white rounded font-bold hover:bg-violet-800 hover:shadow-glow transition-all uppercase font-rune tracking-widest">
