        <Modal isOpen={activeModal === 'CONFIRM_SAVE'} onClose={closeModal} title="Сохранение Данных" footer={<><button onClick={closeModal} className="px-4 py-2 text-slate-400 hover:text-white font-rune uppercase">Отмена</button><button onClick={pendingAction} className="px-4 py-2 bg-emerald-900/50 border border-emerald-500/50 text-white rounded hover:bg-emerald-800 hover:shadow-glow font-bold font-rune uppercase">Записать в БД</button></>}>
