interface DebuffFormState {
    name: string;
    mod: string;
    stat: string;
    tag: string;
    dur: string;
    unit: string;
}

interface Props {
  participants: BattleParticipant[];
  onToggleEquip: (participantId: string, itemId: string) => void;
  onRemoveParticipant: (participantId: string) => void;
  onAddInjury: (participantId: string, templateId: string) => void;
  onRemoveInjury: (participantId: string, index: number) => void;
  onAddDebuff: (participantId: string, name: string, tag: string, val: number, dur: number, unit: string, extraTags?: string) => void;
  onRemoveEffect?: (participantId: string, effectId: string) => void;
  onRemoveCooldown?: (participantId: string, cooldownId: string) => void;
}

const SourcePanel: React.FC<Props> = ({ participants, onToggleEquip, onRemoveParticipant, onAddInjury, onRemoveInjury, onAddDebuff, onRemoveEffect, onRemoveCooldown }) => {
  const [openParticipants, setOpenParticipants] = useState<Record<string, boolean>>({});
  const [selectedTrauma, setSelectedTrauma] = useState<string>(Object.keys(TRAUMA_DEFINITIONS)[0]);

  // Custom Debuff State
  const [debuffState, setDebuffState] = useState<DebuffFormState>({ name: '', mod: '-5', stat: 'phys', tag: '', dur: '2', unit: 'turn' });

  const toggleParticipant = (id: string) => {
      setOpenParticipants(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const isCombatReady = (tags: string[] = []) => {
      return !tags.some(t => t.toLowerCase() === 'no_war');
  };

  const handleCreateDebuff = (participantId: string) => {
      if (!debuffState.name) return;
      const val = parseInt(debuffState.mod) || 0;
      const dur = parseInt(debuffState.dur) || 1;

      const primaryTag = debuffState.stat; 
      onAddDebuff(participantId, debuffState.name, primaryTag, val, dur, debuffState.unit, debuffState.tag);
      setDebuffState({ ...debuffState, name: '' });
  };

  return (
    <div className="flex-1 overflow-y-auto space-y-4 px-1 pb-10">
      {participants.map(p => {
        const isOpen = openParticipants[p.instance_id] ?? true;

        const activeNames = new Set(p.active_effects.map(e => e.name));
        const cooldownMap = new Map<string, Cooldown>();
        p.cooldowns.forEach(cd => cooldownMap.set(cd.name, cd));

        const activeAbilities: { ability: JsonAbility, effect: ActiveEffect }[] = [];
        const cooldownAbilities: { ability: JsonAbility, cooldown: Cooldown }[] = [];
        const isUnavailable = (name: string) => activeNames.has(name) || cooldownMap.has(name);

        p.active_effects.forEach(eff => {
            const original = p.flat_abilities.find(a => a.name === eff.name);
            // Hydrate description from original if possible, active effects need this for tooltip
            const descMech = original?.desc_mech || `Effect: ${eff.name}`;
            const descLore = original?.desc_lore || '';
            const abilityObj = original || { _id: eff.id, name: eff.name, tags: eff.tags || [], bonuses: eff.bonuses, cd: 0, cd_unit: '', dur: 0, dur_unit: '', desc_mech: descMech, desc_lore: descLore };
            activeAbilities.push({ ability: abilityObj, effect: eff });
        });

        p.cooldowns.forEach(cd => {
             const original = p.flat_abilities.find(a => a.name === cd.name);
             const descMech = original?.desc_mech || 'On Cooldown';
             const descLore = original?.desc_lore || '';
             const abilityObj = original || { _id: cd.id, name: cd.name, tags: [], bonuses: [], cd: 0, cd_unit: '', dur: 0, dur_unit: '', desc_mech: descMech, desc_lore: descLore };
             cooldownAbilities.push({ ability: abilityObj, cooldown: cd });
        });

        const cardStyle = getFactionStyle(p.profile.faction);

        return (
          <div key={p.instance_id} className={`rounded border shadow-md overflow-hidden transition-all duration-300 hover:shadow-glow ${cardStyle}`}>
            <div 
                className={`p-2 flex items-center justify-between cursor-pointer hover:bg-white/5 transition-all ${isOpen ? 'bg-black/20' : ''}`}
                onClick={() => toggleParticipant(p.instance_id)}
            >
                <div className="flex items-center gap-2">
                    {isOpen ? <ChevronDown size={14} className="text-violet-400" /> : <ChevronRight size={14} className="text-slate-500" />}
                    <User size={14} className="text-violet-500" />
                    <span className="font-bold text-sm text-slate-200 font-rune tracking-wide">
                      {p.profile.name} <span className="text-xs text-slate-500 font-mono tracking-normal opacity-70">{p.profile.level} ур.</span>
                    </span>
                </div>
                <div className="flex items-center gap-3">
                     <button 
                        type="button"
                        onClick={(e) => { e.stopPropagation(); onRemoveParticipant(p.instance_id); }}
                        className="text-slate-600 hover:text-red-500 transition-colors"
                     >
                         <Trash2 size={12} />
                     </button>
                </div>
            </div>

            {isOpen && (
                <div className="p-2 space-y-1 bg-black/10">

                    <AccordionSection title="Травмы" icon={<HeartCrack size={10}/>} defaultOpen={false} titleColor="text-red-400">
                        <div className="flex flex-col gap-2 bg-input/50 p-2 rounded border border-red-900/20">
                            {p.medcard.injuries.length > 0 ? (
                                <div className="space-y-1">
                                    {p.medcard.injuries.map((inj, idx) => {
                                        const def = TRAUMA_DEFINITIONS[inj.template_id];
                                        return (
                                            <div key={idx} className="flex justify-between items-center bg-red-900/10 px-2 py-1 rounded border border-red-900/30">
                                                <span className="text-[10px] text-red-200 font-mono">
                                                    {def ? def.label : inj.template_id} {inj.count > 1 ? `(x${inj.count})` : ''}
                                                </span>
                                                <button onClick={() => onRemoveInjury(p.instance_id, idx)} className="text-red-500 hover:text-red-300">
                                                    <Trash2 size={10} />
                                                </button>
                                            </div>
                                        );
                                    })}
                                </div>
                            ) : (
                                <div className="text-[10px] text-slate-600 italic font-mono">Нет активных травм</div>
                            )}

                            <div className="flex gap-1 mt-1 border-t border-violet-900/20 pt-2">
                                <select 
                                    className="flex-1 bg-input text-[10px] text-white border border-violet-900/30 rounded px-1 outline-none focus:border-red-500"
                                    value={selectedTrauma}
                                    onChange={(e) => setSelectedTrauma(e.target.value)}
                                >
                                    {Object.entries(TRAUMA_DEFINITIONS).map(([key, def]) => (
                                        <option key={key} value={key}>{def.label} ({def.value})</option>
                                    ))}
                                </select>
                                <button 
                                    onClick={() => onAddInjury(p.instance_id, selectedTrauma)}
                                    className="px-2 py-1 bg-red-900/40 hover:bg-red-800 text-red-100 rounded border border-red-700/50 text-[10px]"
                                >
                                    <PlusCircle size={12} />
                                </button>
                            </div>
                        </div>
                    </AccordionSection>

                    {/* CUSTOM DEBUFFS SECTION */}
                    <AccordionSection title="Ручные Эффекты" icon={<Skull size={10}/>} defaultOpen={false} titleColor="text-fuchsia-400">
                         <div className="bg-input/50 p-2 rounded border border-fuchsia-900/20 space-y-2">
                             <div className="flex flex-col gap-1">
                                 <input 
                                    type="text" 
                                    placeholder="Название эффекта..." 
                                    className="text-[10px] bg-input border border-violet-900/30 rounded px-1 py-1 text-white placeholder-slate-600 focus:border-fuchsia-500 outline-none"
                                    value={debuffState.name}
                                    onChange={(e) => setDebuffState({...debuffState, name: e.target.value})}
                                 />

                                 <input 
                                    type="text" 
                                    placeholder="Доп. тег (напр. огонь)" 
                                    className="text-[10px] bg-input border border-violet-900/30 rounded px-1 py-1 text-white placeholder-slate-600 focus:border-fuchsia-500 outline-none"
                                    value={debuffState.tag}
                                    onChange={(e) => setDebuffState({...debuffState, tag: e.target.value})}
                                 />

                                 <div className="flex gap-1 items-center">
                                     <input 
                                        type="number" 
                                        className="w-12 text-[10px] bg-input border border-violet-900/30 rounded px-1 py-1 text-white text-center"
                                        value={debuffState.mod}
                                        onChange={(e) => setDebuffState({...debuffState, mod: e.target.value})}
                                     />
                                     <select 
                                        className="w-16 text-[10px] bg-input border border-violet-900/30 rounded px-1 py-1 text-white"
                                        value={debuffState.stat}
                                        onChange={(e) => setDebuffState({...debuffState, stat: e.target.value})}
                                     >
                                         <option value="phys">ФИЗ</option>
                                         <option value="mag">МАГ</option>
                                         <option value="uniq">УНИК</option>
                                         <option value="none">ОБЩ</option>
                                     </select>

                                     <input 
                                        type="number"
                                        className="w-10 text-[10px] bg-input border border-violet-900/30 rounded px-1 py-1 text-white text-center"
                                        value={debuffState.dur}
                                        onChange={(e) => setDebuffState({...debuffState, dur: e.target.value})}
                                     />

                                     <select 
                                        className="flex-1 text-[10px] bg-input border border-violet-900/30 rounded px-1 py-1 text-white"
                                        value={debuffState.unit}
                                        onChange={(e) => setDebuffState({...debuffState, unit: e.target.value})}
                                     >
                                         <option value="turn">Ход</option>
                                         <option value="action">Дейст</option>
                                         <option value="scene">Сцена</option>
                                     </select>
                                 </div>
                                 <button 
                                    onClick={() => handleCreateDebuff(p.instance_id)}
                                    className="w-full text-[10px] uppercase font-bold bg-fuchsia-900/20 hover:bg-fuchsia-800/40 text-fuchsia-300 border border-fuchsia-800/30 rounded py-1 transition-colors tracking-wider"
                                 >
                                     Применить
                                 </button>
                             </div>
                         </div>
                    </AccordionSection>

                    <AccordionSection title="Активные Эффекты" icon={<Activity size={10}/>} defaultOpen={true} isEmpty={activeAbilities.length === 0} titleColor="text-emerald-400">
                        <div className="flex flex-wrap">
                            {activeAbilities.map(({ ability, effect }) => (
                                <DraggableAbility 
                                    key={`active-${ability._id}`} 
                                    charId={p.instance_id} 
                                    ability={ability} 
                                    variant="active" 
                                    activeInfo={{ val: effect.duration_left, unit: effect.unit }}
                                    onRemove={onRemoveEffect ? () => onRemoveEffect(p.instance_id, effect.id) : undefined}
                                />
                            ))}
                        </div>
                    </AccordionSection>

                    <AccordionSection title="Перезарядка" icon={<Clock size={10}/>} defaultOpen={true} isEmpty={cooldownAbilities.length === 0} titleColor="text-slate-400">
                        <div className="flex flex-wrap">
                            {cooldownAbilities.map(({ ability, cooldown }) => {
                                return (
                                    <DraggableAbility 
                                        key={`cd-${ability._id}`} 
                                        charId={p.instance_id} 
                                        ability={ability} 
                                        variant="cooldown" 
                                        cooldownInfo={cooldown}
                                        onRemove={onRemoveCooldown ? () => onRemoveCooldown(p.instance_id, cooldown.id) : undefined}
                                    />
                                );
                            })}
                        </div>
                    </AccordionSection>

                    {p.ability_groups.map(group => {
                        const availableAbilities = (group.abilities || []).filter(ab => !isUnavailable(ab.name) && isCombatReady(ab.tags));
                        if (availableAbilities.length === 0) return null;

                        return (
                            <AccordionSection key={group.name} title={group.name} icon={<Layers size={10}/>}>
                                <div className="flex flex-wrap">
                                    {availableAbilities.map(ability => <DraggableAbility key={ability._id} charId={p.instance_id} ability={ability} />)}
                                </div>
                            </AccordionSection>
                        );
                    })}

                    <AccordionSection title="Предметы" icon={<Zap size={10}/>} isEmpty={p.equipment.usable.length === 0}>
                        <div className="flex flex-wrap">
                            {p.equipment.usable.filter(i => isCombatReady(i.tags)).map(item => <DraggableAbility key={item._id} charId={p.instance_id} ability={item as unknown as JsonAbility} />)}
                        </div>
                    </AccordionSection>

                    <AccordionSection title="Экипировка" icon={<Shield size={10}/>} defaultOpen={false} isEmpty={p.equipment.wearable.length === 0}>
                         <div className="flex flex-col gap-1">
                             {p.equipment.wearable.map(item => (
                                 <ItemChip key={item._id} item={item} isEquipped={item.is_equipped} onToggle={() => onToggleEquip(p.instance_id, item._id)} />
                             ))}
                         </div>
                    </AccordionSection>

                </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default SourcePanel;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { DndContext, DragEndEvent, DragOverlay, useSensor, useSensors, PointerSensor, DragStartEvent, pointerWithin } from '@dnd-kit/core';
import { arrayMove } from '@dnd-kit/sortable';
import { BattleParticipant, LogEntry, SequenceNode, BattleStatus, CharacterTemplate, ActiveEffect, Cooldown, JsonInjury } from './types';
import { advanceRound, tickActionTimers } from './engine/timeEngine';
import { calculateSequenceTree } from './engine/calculator';
import { generateSummary, generateStatsText } from './engine/formatters';
import SourcePanel from './components/SourcePanel';
import SequenceCanvas from './components/SequenceCanvas';
import BattleLog from './components/BattleLog';
import { Modal } from './components/Modal';
import { updateBattle, getCharacters, createBattle, getBattles, calculateTraumaPenalty, updateCharacter, deleteBattle, supabase } from './lib/supabase';
import { UserPlus, Save, Play, Square, List, RefreshCw, Trash2, Search, Filter, HardDrive, Cloud } from 'lucide-react';

// UI State Types
type ModalType = 'CREATE_BATTLE' | 'CONFIRM_SAVE' | 'CONFIRM_END' | 'FINALIZE_BATTLE' | 'ALERT' | 'CHAR_SELECT' | 'BATTLE_LIST' | 'CONFIRM_DELETE' | null;

interface BattleModuleProps {
  isAdmin?: boolean;
}

const LOCAL_STORAGE_KEY = 'juul_d_local_battles';

const App: React.FC<BattleModuleProps> = ({ isAdmin = false }) => {
  const [participants, setParticipants] = useState<BattleParticipant[]>([]);
  const [round, setRound] = useState<number>(0); 
  const [status, setStatus] = useState<BattleStatus>('startup');
  const [battleName, setBattleName] = useState('Новый Бой');
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [battleId, setBattleId] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);
  const [allCharacters, setAllCharacters] = useState<CharacterTemplate[]>([]);
  const [savedBattles, setSavedBattles] = useState<any[]>([]);

  const [activeModal, setActiveModal] = useState<ModalType>(null);
  const [modalInput, setModalInput] = useState('');
  const [alertMessage, setAlertMessage] = useState('');
  const [pendingAction, setPendingAction] = useState<() => void>(() => {});

  // Character Selection State
  const [charSearchTerm, setCharSearchTerm] = useState('');
  const [selectedFaction, setSelectedFaction] = useState<string>('All');
  const [selectedVolume, setSelectedVolume] = useState<string>('All');

  // State for Finalize Battle Modal
  const [participantsToSave, setParticipantsToSave] = useState<Set<string>>(new Set());

  // State for Deletion
  const [battleToDelete, setBattleToDelete] = useState<string | null>(null);

  const [tree, setTree] = useState<SequenceNode[]>([]);
  const [activeDragItem, setActiveDragItem] = useState<any>(null);
  const [activeNode, setActiveNode] = useState<SequenceNode | null>(null);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }));

  const initRef = useRef(false);

  // --- INIT ---
  useEffect(() => {
    if (initRef.current) return;
    initRef.current = true;

    async function loadResources() {
        // Load Characters
        const { data: chars } = await getCharacters();
        if (chars && chars.length > 0) {
             setAllCharacters(chars);
        }

        // Load Battles based on role
        if (isAdmin) {
            const { data: battles } = await getBattles();
            if (battles) setSavedBattles(battles);
        } else {
            const localData = localStorage.getItem(LOCAL_STORAGE_KEY);
            if (localData) {
                try {
                    setSavedBattles(JSON.parse(localData));
                } catch (e) {
                    console.error("Failed to parse local battles", e);
                    setSavedBattles([]);
                }
            }
        }
    }
    loadResources();
  }, [isAdmin]);

  // --- DERIVED LISTS FOR FILTERS ---
  const uniqueFactions = useMemo(() => {
      const factions = new Set<string>();
      allCharacters.forEach(c => {
          if (c.profile.faction && c.profile.faction !== 'Могильник') {
              factions.add(c.profile.faction);
          }
      });
      return Array.from(factions).sort();
  }, [allCharacters]);

  const uniqueVolumes = useMemo(() => {
      const isNpcLike = ['NPC', 'НПС', 'Бестиарий'].includes(selectedFaction);
      if (!isNpcLike) return [];

      const volumes = new Set<string>();
      allCharacters.forEach(c => {
          if (c.profile.faction === selectedFaction && c.profile.npc_volume) {
              volumes.add(c.profile.npc_volume);
          }
      });
      return Array.from(volumes).sort();
  }, [allCharacters, selectedFaction]);


  // --- MEMOIZED FILTERING ---
  const filteredCharacters = useMemo(() => {
    let result = [...allCharacters];
    result = result.filter(c => c.profile.faction !== 'Могильник');

    if (charSearchTerm) {
        const lower = charSearchTerm.toLowerCase();
        result = result.filter(c => c.profile.name.toLowerCase().includes(lower));
    }

    if (selectedFaction !== 'All') {
        result = result.filter(c => c.profile.faction === selectedFaction);
    }

    const isNpcLike = ['NPC', 'НПС', 'Бестиарий'].includes(selectedFaction);
    if (isNpcLike && selectedVolume !== 'All') {
         result = result.filter(c => c.profile.npc_volume === selectedVolume);
    }

    result.sort((a, b) => a.profile.name.localeCompare(b.profile.name));
    return result;
  }, [allCharacters, charSearchTerm, selectedFaction, selectedVolume]);

  // --- UI HELPERS ---
  const showAlert = (msg: string) => {
      setAlertMessage(msg);
      setActiveModal('ALERT');
  };

  const closeModal = () => {
      setActiveModal(null);
      setModalInput('');
      setAlertMessage('');
      setCharSearchTerm('');
      setSelectedFaction('All');
      setSelectedVolume('All');
  };

  const getStatusLabel = (s: string) => {
       if (s === 'active') return 'АКТИВЕН';
       if (s === 'finished') return 'ЗАВЕРШЕН';
       if (s === 'startup') return 'ПОДГОТОВКА';
       return s;
  };

  const getCharacterStyle = (faction: string) => {
      const f = (faction || '').toLowerCase();
      if (['светлые', 'light', 'свет'].includes(f)) return 'bg-amber-900/10 border-amber-600/50 hover:bg-amber-900/20 text-amber-100';
      if (['тёмные', 'dark', 'темные', 'тьма'].includes(f)) return 'bg-indigo-950/30 border-indigo-500/50 hover:bg-indigo-900/20 text-indigo-100';
      if (['npc', 'нпс', 'бестиарий'].includes(f)) return 'bg-red-950/20 border-red-800/50 hover:bg-red-900/20 text-red-100';
      return 'bg-panel border-violet-900/30 hover:border-violet-500/50 text-slate-200';
  };

  const handleUpdateParticipant = (id: string, updates: any) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== id) return p;
          return { ...p, ...updates };
      }));
  };

  const handleToggleEquip = (participantId: string, itemId: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const newWearable = p.equipment.wearable.map(item => {
              if (item._id === itemId) return { ...item, is_equipped: !item.is_equipped };
              return item;
          });
          return { ...p, equipment: { ...p.equipment, wearable: newWearable } };
      }));
  };

  const handleRemoveParticipant = (participantId: string) => {
      setParticipants(prev => prev.filter(p => p.instance_id !== participantId));
  };

  const handleRemoveEffect = (participantId: string, effectId: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const effectToRemove = p.active_effects.find(e => e.id === effectId);
          const nextEffects = p.active_effects.filter(e => e.id !== effectId);

          let nextCooldowns = [...p.cooldowns];
          if (effectToRemove?.original_ability_id) {
               const sourceAbility = p.flat_abilities.find(a => a._id === effectToRemove.original_ability_id);
               if (sourceAbility && sourceAbility.cd > 0) {
                   if (!nextCooldowns.some(cd => cd.name === sourceAbility.name)) {
                       nextCooldowns.push({
                          id: `cd_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                          name: sourceAbility.name,
                          val: sourceAbility.cd,
                          max: sourceAbility.cd,
                          unit: sourceAbility.cd_unit || 'turn'
                       });
                   }
               }
          }
          return { ...p, active_effects: nextEffects, cooldowns: nextCooldowns };
      }));
  };

  const handleRemoveCooldown = (participantId: string, cdId: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          return { ...p, cooldowns: p.cooldowns.filter(cd => cd.id !== cdId) };
      }));
  };

  const handleAddInjury = (participantId: string, templateId: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const newInjuries = [...p.medcard.injuries, { count: 1, template_id: templateId, custom_name: '' }];
          const trauma = calculateTraumaPenalty(newInjuries);
          return {
              ...p,
              medcard: { ...p.medcard, injuries: newInjuries },
              battle_stats: { ...p.battle_stats, hp_penalty_current: trauma.total, trauma_phys: trauma.phys, trauma_mag: trauma.mag, trauma_uniq: trauma.uniq }
          };
      }));
  };

  const handleRemoveInjury = (participantId: string, index: number) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const newInjuries = [...p.medcard.injuries];
          newInjuries.splice(index, 1);
          const trauma = calculateTraumaPenalty(newInjuries);
          return {
              ...p,
              medcard: { ...p.medcard, injuries: newInjuries },
              battle_stats: { ...p.battle_stats, hp_penalty_current: trauma.total, trauma_phys: trauma.phys, trauma_mag: trauma.mag, trauma_uniq: trauma.uniq }
          };
      }));
  };

  const handleAddDebuff = (participantId: string, name: string, tag: string, val: number, dur: number, unit: string, extraTags?: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const finalTags = [];
          if (tag && tag !== 'none') finalTags.push(tag);
          if (extraTags) finalTags.push(extraTags.toLowerCase().trim());

          const newEffect: ActiveEffect = {
              id: `custom_${Date.now()}`,
              name: name,
              tags: finalTags,
              bonuses: [{ val: val, stat: tag }],
              duration_left: dur,
              unit: unit || 'turn'
          };
          return { ...p, active_effects: [...p.active_effects, newEffect] };
      }));
  };

  // --- BATTLE LOGIC ---

  const loadBattle = async (id: string) => {
      setLoading(true);

      let foundBattle = null;

      if (isAdmin) {
          const { data: b } = await supabase.from('battles').select('*').eq('id', id).single();
          foundBattle = b;
      } else {
          // Local storage lookup
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
          foundBattle = localData.find((b: any) => b.id === id);
      }

      if (foundBattle) {
          setBattleId(foundBattle.id);
          setBattleName(foundBattle.name || 'Бой без названия');
          setRound(foundBattle.round);
          setStatus(foundBattle.status || 'startup');
          setLogs(foundBattle.sequence_log || []);
          setParticipants(foundBattle.participants_snapshot || []);
      }
      setLoading(false);
      setActiveModal(null);
  };

  const handleDeleteBattle = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      setBattleToDelete(id);
      setActiveModal('CONFIRM_DELETE');
  };

  const confirmDeleteBattle = async () => {
      if (!battleToDelete) {
          setActiveModal('BATTLE_LIST');
          return;
      }

      if (isAdmin) {
          // Admin Delete from DB
          const { error } = await deleteBattle(battleToDelete);
          if (error) {
              showAlert(`Ошибка удаления: ${error.message}`);
              return;
          }
      } else {
          // Local Delete
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
          const newData = localData.filter((b: any) => b.id !== battleToDelete);
          localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(newData));
          setSavedBattles(newData);
      }

      setSavedBattles(prev => prev.filter(b => b.id !== battleToDelete));

      if (battleId === battleToDelete) {
          setBattleId(null);
          setBattleName('Новый Бой');
          setRound(1);
          setStatus('startup');
          setLogs([]);
          setParticipants([]);
          setTree([]);
          setBattleToDelete(null);
          showAlert(isAdmin ? "Бой удален из базы." : "Бой удален из локального хранилища.");
      } else {
          setBattleToDelete(null);
          setActiveModal('BATTLE_LIST');
      }
  };

  const cancelDelete = () => {
      setBattleToDelete(null);
      setActiveModal('BATTLE_LIST');
  };

  const handleCreateBattleClick = () => {
      setModalInput('');
      setActiveModal('CREATE_BATTLE');
  };

  const confirmCreateBattle = async () => {
      const name = modalInput || "Стычка у ворот";
      setLoading(true);

      const newBattle = {
          id: `battle_${Date.now()}_${Math.random().toString(36).substr(2,5)}`,
          name,
          participants_snapshot: [],
          sequence_log: [],
          casualties: [],
          round: 0,
          status: 'startup'
      };

      if (isAdmin) {
          const { data, error } = await createBattle(name);
          if (error) {
              showAlert(`Failed to create battle in DB. Error: ${error.message}`);
              setLoading(false);
              return;
          }
          if (data) {
              setBattleId(data.id);
              setBattleName(data.name);
          }
      } else {
          // Local Create
          setBattleId(newBattle.id);
          setBattleName(newBattle.name);

          // Save initial state to local
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
          localData.push(newBattle);
          localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
          setSavedBattles(localData);
      }

      setRound(0);
      setStatus('startup');
      setParticipants([]);
      setLogs([]);
      setLoading(false);
      closeModal();
  };

  const handleSaveBattle = async () => {
      if (!battleId) {
          // This path should ideally be covered by "Create Battle", but as a fallback:
          setPendingAction(() => async () => {
               // Similar logic to confirmCreateBattle but saving current state
               // For now just alert to use Create
               showAlert("Пожалуйста, создайте бой через меню 'Архив' -> 'Создать'.");
               closeModal();
          });
          setActiveModal('CONFIRM_SAVE');
          return;
      }

      const battleState = {
          name: battleName,
          participants_snapshot: participants,
          sequence_log: logs,
          round: round,
          status: status,
          casualties: []
      };

      if (isAdmin) {
          const { error } = await updateBattle(battleId, battleState);
          if (error) {
              showAlert(`Ошибка сохранения: ${error.message}`);
          } else {
              showAlert("Бой успешно сохранен в базе данных.");
          }
      } else {
          // Local Save Update
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
          const index = localData.findIndex((b: any) => b.id === battleId);
          if (index !== -1) {
              localData[index] = { ...localData[index], ...battleState };
          } else {
              localData.push({ id: battleId, ...battleState });
          }
          localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
          setSavedBattles(localData);
          showAlert("Бой сохранен локально.");
      }
  };

  const updateBattleName = async (newName: string) => {
      setBattleName(newName);
  };

  const addParticipant = (template: CharacterTemplate) => {
      const flatAbilities = (template.ability_groups || []).flatMap(g => g.abilities || []);

      // Fallback: If flat_passives didn't populate for some reason, build it from groups
      let passivesToScan = template.flat_passives || [];
      if (passivesToScan.length === 0 && template.passives) {
          passivesToScan = template.passives.flatMap(g => g.items);
      }

      // COMBAT_START TRIGGER CHECK - MORE ROBUST
      const startupEffects: ActiveEffect[] = [];
      let logText = "";

      passivesToScan.forEach(pas => {
          if (!pas.trigger) return;
          const trig = pas.trigger.toUpperCase();
          // Check for keywords rather than exact matches to handle potential data variations
          if (trig.includes('START') || trig.includes('НАЧАЛО') || trig.includes('COMBAT') || trig.includes('БОЯ')) {
              logText += `> (${template.profile.name}: [AUTO] ${pas.name}${pas.is_flaw ? ' (Дебафф)' : ''})\n`;

              const hasDuration = pas.dur && pas.dur > 0;
              startupEffects.push({
                  id: `start_passive_${pas._id || Math.random()}_${Date.now()}`,
                  name: pas.name,
                  tags: [...(pas.tags || []), pas.is_flaw ? 'debuff' : 'buff'],
                  bonuses: pas.bonuses || [],
                  duration_left: hasDuration ? pas.dur! : 999,
                  unit: hasDuration ? (pas.dur_unit || 'turn') : 'battle',
                  original_ability_id: pas._id
              });
          }
      });

      const newP: BattleParticipant = {
          ...template,
          instance_id: `char_${template.id}_${Date.now()}`,
          is_player: false,

          battle_stats: (template as any).battle_stats || {
              hp_penalty_current: 0,
              trauma_phys: 0,
              trauma_mag: 0,
              trauma_uniq: 0,
              actions_max: 4,
              actions_left: 4
          },
          active_effects: startupEffects,
          cooldowns: [],
          usage_counts: {}, 
          flat_abilities: flatAbilities,
          flat_passives: passivesToScan
      };

      setParticipants(prev => [...prev, newP]);

      if (logText) {
          setLogs(prev => [...prev, {
              id: `trigger_add_${newP.instance_id}_${Date.now()}`,
              round: round,
              timestamp: new Date().toISOString(),
              type: 'system', 
              text_formatted: logText.trim()
          }]);
      }

      setActiveModal(null);
  };

  const handleNextRound = async () => {
    // 1. Snapshot State of current round (Before advancement)
    const summary = generateSummary(participants, round);
    const statsSnapshot = generateStatsText(participants);

    // We deep clone participants to ensure snapshot isn't mutated later
    const participantsSnapshot = JSON.parse(JSON.stringify(participants));

    const endRoundLog: LogEntry = {
      id: `end_rnd_${round}_${Date.now()}`,
      round: round,
      timestamp: new Date().toISOString(),
      type: 'system',
      text_formatted: round === 0 ? `ЗАВЕРШЕНИЕ ПОДГОТОВКИ` : `ЗАВЕРШЕНИЕ РАУНДА ${round}`,
      summary: summary,
      details: {
          stats_snapshot: statsSnapshot,
          participants_snapshot: participantsSnapshot
      }
    };

    // 2. Prepare Next Round
    const nextR = round + 1;
    let newStatus = status;
    if (status === 'startup') {
        newStatus = 'active';
        setStatus('active');
    }

    // 3. Advance logic
    let advancedParticipants = [...participants];

    if (round === 0) {
        // SPECIAL CASE: Round 0 -> 1 (Start Battle)
    } else {
        // Normal Round Transition: Tick timers
        advancedParticipants = advanceRound(participants);
    }

    const startRoundLog: LogEntry = {
        id: `start_rnd_${nextR}_${Date.now()}`,
        round: nextR,
        timestamp: new Date().toISOString(),
        text_formatted: `НАЧАЛО РАУНДА ${nextR}`,
        type: 'round_change'
    };

    const logsToAdd = [endRoundLog, startRoundLog];

    // 4. Update State
    const updatedLogs = [...logs, ...logsToAdd];

    setRound(nextR);
    setParticipants(advancedParticipants);
    setLogs(updatedLogs);
    setStatus(newStatus);

    if (battleId) {
        if (isAdmin) {
            await updateBattle(battleId, { 
                sequence_log: updatedLogs, 
                round: nextR, 
                status: newStatus,
                participants_snapshot: advancedParticipants 
            });
        } else {
            // Auto-save local on round change
            const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
            const index = localData.findIndex((b: any) => b.id === battleId);
            const battleState = {
                name: battleName,
                participants_snapshot: advancedParticipants,
                sequence_log: updatedLogs,
                round: nextR,
                status: newStatus
            };
            if (index !== -1) {
                localData[index] = { ...localData[index], ...battleState };
            }
            localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
        }
    }
  };

  const handleRollback = async (targetRound: number) => {
      const snapshotLog = logs.find(l => l.round === targetRound && l.details?.participants_snapshot);

      if (!snapshotLog) {
          showAlert("Невозможно откатить: нет сохраненного состояния для этого раунда.");
          return;
      }

      setParticipants(snapshotLog.details.participants_snapshot);
      setRound(snapshotLog.round);

      const newLogs = logs.filter(l => l.round <= targetRound && l.id !== snapshotLog.id);

      setLogs(newLogs);

      if (battleId) {
          const updatePayload = {
              round: snapshotLog.round,
              participants_snapshot: snapshotLog.details.participants_snapshot,
              sequence_log: newLogs,
              status: 'active'
          };

          if (isAdmin) {
              await updateBattle(battleId, updatePayload);
          } else {
              const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
              const index = localData.findIndex((b: any) => b.id === battleId);
              if (index !== -1) {
                  localData[index] = { ...localData[index], ...updatePayload };
                  localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
              }
          }
      }

      showAlert(`Откат выполнен. Вы вернулись в Раунд ${targetRound}.`);
  };

  // ... (rest of modals logic: handleEndBattleClick, finalizeBattle, etc. same as before) ...
  const handleEndBattleClick = () => {
      const injuredIds = new Set<string>();
      participants.forEach(p => {
          if (p.medcard.injuries.length > 0) {
              injuredIds.add(p.instance_id);
          }
      });
      setParticipantsToSave(injuredIds);
      setActiveModal('FINALIZE_BATTLE');
  };

  const handleToggleSaveParticipant = (id: string) => {
      const next = new Set(participantsToSave);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setParticipantsToSave(next);
  };

  const finalizeBattle = async () => {
      if (!isAdmin) {
          // Non-admins cannot write back to DB
          setStatus('finished');
          showAlert("Бой завершен локально. Не-админы не могут обновлять травмы в базе персонажей.");
          closeModal();
          return;
      }

      setLoading(true);
      for (const p of participants) {
          if (participantsToSave.has(p.instance_id)) {
              await updateCharacter(p.id, {
                  medcard: p.medcard
              });
          }
      }
      setStatus('finished');
      if (battleId) {
          const { error } = await updateBattle(battleId, { status: 'finished' });
          if (error) console.error("Failed to update battle status", error);
      }
      setLoading(false);
      closeModal();
      showAlert("Бой финализирован. Травмы для выбранных персонажей обновлены в базе данных.");
  };

  const confirmEndBattle = async () => {
      setStatus('finished');
      if (battleId) {
          if (isAdmin) {
              const { error } = await updateBattle(battleId, { status: 'finished' });
              if (error) showAlert(`Failed to update status in DB: ${error.message}`);
          } else {
              const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
              const index = localData.findIndex((b: any) => b.id === battleId);
              if (index !== -1) {
                  localData[index].status = 'finished';
                  localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
              }
          }
      }
      closeModal();
  };

  const extractActionsFromTree = (nodes: SequenceNode[]): SequenceNode[] => {
      let actions: SequenceNode[] = [];
      for (const node of nodes) {
          if (node.type === 'action') actions.push(node);
          if (node.children) actions = actions.concat(extractActionsFromTree(node.children));
      }
      return actions;
  };

  const handleCommit = async () => {
    if (tree.length === 0) {
        showAlert("Холст пуст. Добавьте действия или комбо.");
        return;
    }

    const result = calculateSequenceTree(tree, participants);

    const newLog: LogEntry = {
        id: Date.now().toString(),
        round: round,
        timestamp: new Date().toISOString(),
        text_formatted: result.formattedString || 'Пустое действие',
        type: 'action'
    };

    let updatedParticipants = [...participants];

    const actionNodes = extractActionsFromTree(tree);
    const actionsPerActor: Record<string, number> = {};
    const abilitiesUsed: { charId: string, abilityId: string }[] = [];

    actionNodes.forEach(node => {
        const charId = node.data?.charId;
        const abilityId = node.data?.abilityId;
        if (charId) {
            actionsPerActor[charId] = (actionsPerActor[charId] || 0) + 1;
        }
        if (charId && abilityId) {
            abilitiesUsed.push({ charId, abilityId });
        }
    });

    const effectsToApply: { charId: string, effect: ActiveEffect }[] = [];
    const cooldownsToApply: { charId: string, cooldown: Cooldown }[] = [];

    actionNodes.forEach(node => {
        const charId = node.data?.charId;
        const abilityId = node.data?.abilityId;
        if (!charId || !abilityId) return;

        const actor = participants.find(p => p.instance_id === charId);
        if (!actor) return;

        let ability = actor.flat_abilities.find(a => a._id === abilityId);
        if (!ability) {
             actor.ability_groups.forEach(g => {
                 const found = g.abilities.find(a => a._id === abilityId);
                 if (found) ability = found;
             });
        }

        if (ability) {
            if (ability.dur > 0) {
                effectsToApply.push({
                    charId,
                    effect: {
                        id: `eff_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                        name: ability.name,
                        tags: ability.tags,
                        bonuses: ability.bonuses,
                        duration_left: ability.dur,
                        unit: ability.dur_unit || 'turn',
                        original_ability_id: ability._id
                    }
                });
            }
            if (ability.cd > 0 && ability.dur === 0) {
                if (!ability.limit || ability.limit <= 0) {
                    cooldownsToApply.push({
                        charId,
                        cooldown: {
                            id: `cd_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                            name: ability.name,
                            val: ability.cd,
                            max: ability.cd,
                            unit: ability.cd_unit || 'turn'
                        }
                    });
                }
            }
        }
    });

    updatedParticipants = updatedParticipants.map(p => {
        let processedP = p;
        if (actionsPerActor[p.instance_id]) {
            processedP = tickActionTimers(p, actionsPerActor[p.instance_id]);
        }

        const myUsages = abilitiesUsed.filter(u => u.charId === p.instance_id);
        const nextUsageCounts = { ...processedP.usage_counts };
        const limitBasedCooldowns: Cooldown[] = [];

        myUsages.forEach(usage => {
             const ability = processedP.flat_abilities.find(a => a._id === usage.abilityId);
             if (ability) {
                 const current = nextUsageCounts[ability._id] || 0;
                 const next = current + 1;
                 nextUsageCounts[ability._id] = next;

                 if (ability.limit && ability.limit > 0) {
                     if (next >= ability.limit) {
                          if (ability.cd > 0) {
                              limitBasedCooldowns.push({
                                  id: `cd_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                                  name: ability.name,
                                  val: ability.cd,
                                  max: ability.cd,
                                  unit: ability.cd_unit || 'turn'
                              });
                          }
                     }
                 }
             }
        });

        processedP = { ...processedP, usage_counts: nextUsageCounts };

        const myNewEffects = effectsToApply
            .filter(item => item.charId === p.instance_id)
            .map(item => item.effect);

        const myNewCooldowns = cooldownsToApply
            .filter(item => item.charId === p.instance_id)
            .map(item => item.cooldown);

        const allNewCooldowns = [...myNewCooldowns, ...limitBasedCooldowns];

        const finalCooldowns = [...processedP.cooldowns];
        allNewCooldowns.forEach(newCD => {
             if (!finalCooldowns.some(existing => existing.name === newCD.name)) {
                 finalCooldowns.push(newCD);
             }
        });

        return {
            ...processedP,
            active_effects: [...processedP.active_effects, ...myNewEffects],
            cooldowns: finalCooldowns
        };
    });

    setParticipants(updatedParticipants);
    const updatedLogs = [...logs, newLog];
    setLogs(updatedLogs);
    setTree([]); 

    if (battleId) {
        if (isAdmin) {
            await updateBattle(battleId, { 
                sequence_log: updatedLogs,
                participants_snapshot: updatedParticipants
            });
        } else {
            const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
            const index = localData.findIndex((b: any) => b.id === battleId);
            if (index !== -1) {
                localData[index] = { 
                    ...localData[index], 
                    sequence_log: updatedLogs, 
                    participants_snapshot: updatedParticipants 
                };
                localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
            }
        }
    }
  };

  // ... (rest of Drag and Drop helpers same as before) ...
  const getParentId = (nodes: SequenceNode[], nodeId: string, parentId: string = 'root'): string | null => {
      for (const node of nodes) {
          if (node.id === nodeId) return parentId;
          if (node.children && node.children.length > 0) {
              const found = getParentId(node.children, nodeId, node.id);
              if (found) return found;
          }
      }
      return null;
  };

  const findNode = (nodes: SequenceNode[], id: string): SequenceNode | null => {
    for (const node of nodes) {
        if (node.id === id) return node;
        const found = findNode(node.children, id);
        if (found) return found;
    }
    return null;
  }

  const handleDragStart = (event: DragStartEvent) => {
    const { active } = event;
    const type = active.data.current?.type;
    if (type === 'SOURCE_ABILITY') setActiveDragItem(active.data.current);
    else if (type === 'NODE') setActiveNode(active.data.current?.node);
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveDragItem(null);
    setActiveNode(null);

    if (!over) return;

    if (active.data.current?.type === 'SOURCE_ABILITY') {
        const { charId, abilityId } = active.data.current;
        const newNode: SequenceNode = {
            id: `node-${Date.now()}`,
            type: 'action',
            data: { charId, abilityId, weaponId: '' },
            children: []
        };

        let targetParentId = 'root';
        const overData = over.data.current || {};

        if (over.id === 'root-canvas') {
            targetParentId = 'root';
        } else if (overData.type === 'CONTAINER') {
            targetParentId = overData.nodeId;
        } else if (overData.type === 'NODE') {
             targetParentId = getParentId(tree, over.id as string) || 'root';
        }

        if (targetParentId !== 'root') {
            const container = findNode(tree, targetParentId);
            if (container && container.type === 'combo' && container.children.length >= 2) {
                return; 
            }
        }

        setTree(prev => {
             if (targetParentId === 'root') return [...prev, newNode];
             return addNodeToContainer(prev, targetParentId, newNode);
        });
        return;
    }

    if (active.data.current?.type === 'NODE') {
        const activeId = active.id as string;
        const activeParentId = getParentId(tree, activeId) || 'root';

        if (!activeId) return;

        let targetParentId = 'root';
        const overId = over.id as string;
        const overData = over.data.current || {};

        if (over.id === 'root-canvas') {
            targetParentId = 'root';
        } else if (overData.type === 'CONTAINER') {
            targetParentId = overData.nodeId;
        } else if (overData.type === 'NODE') {
             targetParentId = getParentId(tree, overId) || 'root';
        }

        if (activeId === overId) return;

        if (targetParentId !== activeParentId && targetParentId !== 'root') {
             const container = findNode(tree, targetParentId);
             if (container && container.type === 'combo' && container.children.length >= 2) {
                 return;
             }
        }

        setTree(items => {
             if (activeParentId === targetParentId) {
                  if (activeParentId === 'root') {
                      const oldIdx = items.findIndex(n => n.id === activeId);
                      const newIdx = items.findIndex(n => n.id === overId);
                      if (oldIdx !== -1 && newIdx !== -1) {
                        return arrayMove(items, oldIdx, newIdx);
                      }
                      return items;
                  } else {
                      return recursiveSort(items, activeId, overId); 
                  }
             }
             return moveNodeBetweenParents(items, activeId, activeParentId, targetParentId, overId);
        });
    }
  };

  const moveNodeBetweenParents = (nodes: SequenceNode[], nodeId: string, sourceParentId: string, targetParentId: string, overId: string): SequenceNode[] => {
      let nodeToMove: SequenceNode | null = null;
      const removeNode = (list: SequenceNode[]): SequenceNode[] => {
          const newList = [];
          for (const item of list) {
              if (item.id === nodeId) {
                  nodeToMove = item;
                  continue;
              }
              if (item.children.length > 0) {
                  const newChildren = removeNode(item.children);
                  if (newChildren !== item.children) {
                      newList.push({ ...item, children: newChildren });
                      continue;
                  }
              }
              newList.push(item);
          }
          return newList;
      };
      const treeWithoutNode = removeNode(nodes);
      if (!nodeToMove) return nodes; 
      const insertNode = (list: SequenceNode[], isRoot: boolean): SequenceNode[] => {
          if (targetParentId === 'root' && isRoot) {
              const newRoot = [...list];
              const overIndex = newRoot.findIndex(n => n.id === overId);
              if (overIndex !== -1) {
                  newRoot.splice(overIndex, 0, nodeToMove!);
              } else {
                  newRoot.push(nodeToMove!);
              }
              return newRoot;
          }
          return list.map(item => {
               if (item.id === targetParentId) {
                   const newChildren = [...item.children];
                   const overIndex = newChildren.findIndex(n => n.id === overId);
                   if (overIndex !== -1) {
                        newChildren.splice(overIndex, 0, nodeToMove!);
                   } else {
                        newChildren.push(nodeToMove!);
                   }
                   return { ...item, children: newChildren };
               }
               if (item.children.length > 0) {
                   return { ...item, children: insertNode(item.children, false) };
               }
               return item;
          });
      };
      return insertNode(treeWithoutNode, true);
  };

  const addNodeToContainer = (nodes: SequenceNode[], targetId: string, newNode: SequenceNode): SequenceNode[] => {
      return nodes.map(node => {
          if (node.id === targetId) return { ...node, children: [...node.children, newNode] };
          if (node.children.length > 0) return { ...node, children: addNodeToContainer(node.children, targetId, newNode) };
          return node;
      });
  };

  const recursiveSort = (nodes: SequenceNode[], activeId: string, overId: string): SequenceNode[] => {
     return nodes.map(node => {
         const activeIndex = node.children.findIndex(c => c.id === activeId);
         const overIndex = node.children.findIndex(c => c.id === overId);
         if (activeIndex !== -1 && overIndex !== -1) return { ...node, children: arrayMove(node.children, activeIndex, overIndex) };
         if (node.children.length > 0) return { ...node, children: recursiveSort(node.children, activeId, overId) };
         return node;
     });
  };

  const removeNode = (id: string) => {
      const recursiveFilter = (nodes: SequenceNode[]): SequenceNode[] => {
          return nodes.filter(n => n.id !== id).map(n => ({ ...n, children: recursiveFilter(n.children) }));
      };
      setTree(prev => recursiveFilter(prev));
  };

  const updateNodeData = (id: string, data: any) => {
      const recursiveUpdate = (nodes: SequenceNode[]): SequenceNode[] => {
          return nodes.map(n => {
              if (n.id === id) return { ...n, data: { ...n.data, ...data } };
              return { ...n, children: recursiveUpdate(n.children) };
          });
      };
      setTree(prev => recursiveUpdate(prev));
  };

  const addBlock = (type: 'combo' | 'condition' | 'divider') => {
      if (type === 'condition') {
          const initialCondition: SequenceNode = {
            id: `cond-${Date.now()}`,
            type: 'condition',
            data: {},
            children: []
          };
          const chainNode: SequenceNode = {
              id: `chain-${Date.now()}`,
              type: 'logic_chain',
              children: [initialCondition]
          };
          setTree(prev => [...prev, chainNode]);
      } else {
          const newNode: SequenceNode = {
              id: `block-${Date.now()}`,
              type,
              data: {},
              children: []
          };
          setTree(prev => [...prev, newNode]);
      }
  };

  const handleAddLogicSibling = (nodeId: string) => {
      const newSibling: SequenceNode = {
          id: `cond-${Date.now()}`,
          type: 'condition',
          data: {},
          children: []
      };
      const recursiveAdd = (nodes: SequenceNode[]): SequenceNode[] => {
          return nodes.map(node => {
              if (node.type === 'logic_chain') {
                  const childExists = node.children.some(c => c.id === nodeId);
                  if (childExists) {
                      return { ...node, children: [...node.children, newSibling] };
                  }
              }
              if (node.children.length > 0) {
                  return { ...node, children: recursiveAdd(node.children) };
              }
              return node;
          });
      };
      setTree(prev => recursiveAdd(prev));
  };

  const updateLog = (newLogs: LogEntry[]) => {
      setLogs(newLogs);
  };

  return (
    <DndContext 
        sensors={sensors}
        collisionDetection={pointerWithin}
        onDragStart={handleDragStart} 
        onDragEnd={handleDragEnd}
    >
        <Modal 
            isOpen={activeModal === 'CHAR_SELECT'} 
            onClose={closeModal} 
            title="Добавить участника"
        >
            <div className="flex flex-col gap-3 mb-4">
                <div className="relative group">
                    <input 
                        type="text" 
                        placeholder="ПОИСК ПО ИМЕНИ..." 
                        value={charSearchTerm}
                        onChange={(e) => setCharSearchTerm(e.target.value)}
                        className="w-full bg-input border border-violet-900/40 rounded pl-9 pr-2 py-2 text-sm text-white focus:border-violet-500 focus:shadow-glow outline-none transition-all placeholder-slate-600 font-sans"
                    />
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-violet-400" />
                </div>
                <div className="flex gap-2">
                    <div className="flex-1 relative group">
                        <Filter size={14} className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none group-focus-within:text-violet-400"/>
                        <select
                            value={selectedFaction}
                            onChange={(e) => {
                                setSelectedFaction(e.target.value);
                                setSelectedVolume('All');
                            }}
                            className="w-full bg-input border border-violet-900/40 rounded pl-8 pr-2 py-1.5 text-xs text-white appearance-none outline-none focus:border-violet-500 focus:shadow-glow transition-all"
                        >
                            <option value="All">ВСЕ ФРАКЦИИ</option>
                            {uniqueFactions.map(f => (
                                <option key={f} value={f}>{f.toUpperCase()}</option>
                            ))}
                        </select>
                    </div>
                    {['NPC', 'НПС', 'Бестиарий'].includes(selectedFaction) && (
                         <div className="flex-1 relative animate-in fade-in slide-in-from-left-2 duration-300 group">
                             <Filter size={14} className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none group-focus-within:text-violet-400"/>
                             <select
                                 value={selectedVolume}
                                 onChange={(e) => setSelectedVolume(e.target.value)}
                                 className="w-full bg-input border border-violet-900/40 rounded pl-8 pr-2 py-1.5 text-xs text-white appearance-none outline-none focus:border-violet-500 focus:shadow-glow transition-all"
                             >
                                 <option value="All">ВСЕ ТОМА</option>
                                 {uniqueVolumes.map(v => (
                                     <option key={v} value={v}>{v.toUpperCase()}</option>
                                 ))}
                             </select>
                         </div>
                    )}
                </div>
            </div>
            {filteredCharacters.length === 0 ? (
