export const useLocations = () => {
  const [locations, setLocations] = useState<Location[]>([]);
  const [loading, setLoading] = useState(true);
  const loaded = useRef(false);

  const fetchLocations = useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('locations')
        .select('*')
        .order('name');
      if (error) throw error;
      setLocations(data || []);
    } catch (error) {
      console.error('Error fetching locations:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (loaded.current) return;
    loaded.current = true;
    fetchLocations();
  }, [fetchLocations]);

  const addLocation = async (loc: Omit<Location, 'id'>) => {
    try {
        const { data, error } = await supabase.from('locations').insert([loc]).select().single();
        if (error) throw error;
        if (data) setLocations(prev => [...prev, data]);
    } catch (error) {
        console.error('Error adding location:', error);
    }
  };

  const updateLocation = async (id: string, updates: Partial<Location>) => {
    // Optimistic UI update
    setLocations(prev => prev.map(l => l.id === id ? { ...l, ...updates } : l));

    try {
        const { error } = await supabase.from('locations').update(updates).eq('id', id);
        if (error) throw error;
    } catch (error) {
        console.error('Error updating location:', error);
        fetchLocations(); // Revert on error
    }
  };

  const deleteLocation = async (id: string) => {
    const prevLocs = [...locations];
    setLocations(prev => prev.filter(l => l.id !== id));
    try {
        const { error } = await supabase.from('locations').delete().eq('id', id);
        if (error) throw error;
    } catch (error) {
        console.error('Error deleting location:', error);
        setLocations(prevLocs);
    }
  };

  return { locations, loading, addLocation, updateLocation, deleteLocation };
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { LoreCategory } from '../types';

export const useLoreCategories = () => {
  const [categories, setCategories] = useState<LoreCategory[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const loaded = useRef(false);

  const fetchCategories = useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('lore_categories')
        .select('*')
        .order('name');

      if (error) throw error;
      setCategories(data || []);
    } catch (err: any) {
      console.error("Error fetching lore categories:", err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (loaded.current) return;
    loaded.current = true;
    fetchCategories();
  }, [fetchCategories]);

  const addCategory = async (category: Omit<LoreCategory, 'id' | 'created_at'>) => {
    try {
      const { data, error } = await supabase
        .from('lore_categories')
        .insert([category])
        .select()
        .single();

      if (error) throw error;
      if (data) {
          setCategories(prev => [...prev, data].sort((a, b) => a.name.localeCompare(b.name)));
      }
      return data;
    } catch (err: any) {
      console.error("Error adding lore category:", err);
      setError(err.message);
    }
  };

  const updateCategory = async (id: string, updates: Partial<LoreCategory>) => {
      setCategories(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
      try {
          const { error } = await supabase.from('lore_categories').update(updates).eq('id', id);
          if (error) throw error;
      } catch (err: any) {
          console.error("Error updating lore category:", err);
          fetchCategories();
      }
  };

  const deleteCategory = async (id: string) => {
      const prev = [...categories];
      setCategories(list => list.filter(c => c.id !== id));
      try {
          const { error } = await supabase.from('lore_categories').delete().eq('id', id);
          if (error) throw error;
      } catch (err: any) {
          console.error("Error deleting lore category:", err);
          setCategories(prev);
      }
  };

  return { categories, loading, error, addCategory, updateCategory, deleteCategory, refresh: fetchCategories };
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { GameMap, MapPin } from '../types';

export const useMaps = () => {
  const [maps, setMaps] = useState<GameMap[]>([]);
  const [loading, setLoading] = useState(true);
  const loaded = useRef(false);

  const fetchMaps = useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('maps')
        .select('*')
        .order('name');

      if (error) throw error;

      // Ensure markers is an array
      const sanitized = (data || []).map((m: any) => ({
          ...m,
          markers: Array.isArray(m.markers) ? m.markers : []
      }));

      setMaps(sanitized);
    } catch (error) {
      console.error('Error fetching maps:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (loaded.current) return;
    loaded.current = true;
    fetchMaps();
  }, [fetchMaps]);

  const addMap = async (map: Omit<GameMap, 'id' | 'markers'>) => {
      try {
          const payload = {
              ...map,
              markers: [] // Start empty
          };

          const { data, error } = await supabase
            .from('maps')
            .insert([payload])
            .select()
            .single();

          if (error) throw error;

          if (data) {
              setMaps(prev => [...prev, { ...data, markers: [] }]);
          }
      } catch (err) {
          console.error("Error adding map:", err);
      }
  };

  const updateMap = async (id: string, updates: Partial<GameMap>) => {
      // Optimistic
      setMaps(prev => prev.map(m => m.id === id ? { ...m, ...updates } : m));

      try {
          // Remove markers from update payload if it's not intended (usually markers are updated separately)
          // But if passed, allow it.
          const { error } = await supabase
            .from('maps')
            .update(updates)
            .eq('id', id);

          if (error) throw error;
      } catch (err) {
          console.error("Error updating map:", err);
          fetchMaps(); // Revert
      }
  };

  const updateMapMarkers = async (mapId: string, markers: MapPin[]) => {
      // Optimistic
      setMaps(prev => prev.map(m => m.id === mapId ? { ...m, markers } : m));

      try {
          const { error } = await supabase
            .from('maps')
            .update({ markers: markers })
            .eq('id', mapId);

          if (error) throw error;
      } catch (err) {
          console.error("Error updating markers:", err);
          fetchMaps(); // Revert
      }
  };

  return { maps, loading, addMap, updateMap, updateMapMarkers, refresh: fetchMaps };
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Quest, QuestStatus } from '../types';

export const useQuests = () => {
  const [quests, setQuests] = useState<Quest[]>([]);
  const [loading, setLoading] = useState(true);
  const loaded = useRef(false);

  const fetchQuests = useCallback(async () => {
    setLoading(true);
    try {
      // 'created_at' column is missing in the user's table, so we remove the sort
      const { data, error } = await supabase
        .from('quests')
        .select('*');

      if (error) throw error;

      const mappedQuests: Quest[] = (data || []).map((row: any) => ({
          id: row.id,
          title: row.title,
          description: row.description,
          reward: row.reward,
          type: row.type,
          status: row.status,
          // Extract alignment from details if missing in column (fallback for schema compatibility)
          alignment: row.details?.alignment || row.alignment || 'Neutral',
          details: {
              givenBy: row.details?.givenBy || 'Unknown',
              acceptedBy: row.details?.acceptedBy || []
          },
          created_at: row.created_at // Will be undefined if column missing
      }));

      setQuests(mappedQuests);
    } catch (e) {
      console.error("Error loading quests:", e);
      setQuests([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (loaded.current) return;
    loaded.current = true;
    fetchQuests();
  }, [fetchQuests]);

  const addQuest = async (quest: Omit<Quest, 'id'>) => {
    try {
        // Persist alignment in details since the column might not exist in the user's table
        const dbPayload = {
            title: quest.title,
            description: quest.description,
            reward: quest.reward,
            type: quest.type,
            status: quest.status,
            details: {
                ...quest.details,
                alignment: quest.alignment 
            }
        };

        const { data, error } = await supabase
            .from('quests')
            .insert([dbPayload])
            .select()
            .single();

        if (error) throw error;

        if (data) {
            const newQuest: Quest = {
                id: data.id,
                title: data.title,
                description: data.description,
                reward: data.reward,
                type: data.type,
                status: data.status,
                alignment: data.details?.alignment || quest.alignment || 'Neutral',
                details: {
                    givenBy: data.details?.givenBy || quest.details.givenBy,
                    acceptedBy: data.details?.acceptedBy || quest.details.acceptedBy
                },
                created_at: data.created_at
            };
            setQuests(prev => [newQuest, ...prev]);
        }
    } catch (err) {
        console.error("Error adding quest:", err);
    }
  };

  const editQuest = async (id: string, updates: Partial<Quest>) => {
      try {
          const current = quests.find(q => q.id === id);
          if (!current) return;

          // Prepare payload. alignment must go into details, NOT root.
          const dbPayload: any = {
              title: updates.title,
              description: updates.description,
              reward: updates.reward,
              type: updates.type,
              status: updates.status,
              details: {
                  ...(current.details || {}),
                  ...(updates.details || {}),
                  alignment: updates.alignment || current.alignment
              }
          };

          // Optimistic update
          setQuests(prev => prev.map(q => q.id === id ? { 
              ...q, 
              ...updates, 
              details: dbPayload.details,
              alignment: dbPayload.details.alignment 
          } : q));

          const { error } = await supabase
            .from('quests')
            .update(dbPayload)
            .eq('id', id);

          if (error) throw error;
      } catch (err) {
          console.error("Error editing quest:", err);
          fetchQuests(); // Revert
      }
  };

  const updateStatus = async (id: string, status: QuestStatus) => {
    // Optimistic Update
    setQuests(prev => prev.map(q => q.id === id ? { ...q, status } : q));

    try {
        await supabase.from('quests').update({ status }).eq('id', id);
    } catch (err) {
        console.error("Error updating status:", err);
        fetchQuests(); // Revert on error
    }
  };

  const acceptQuest = async (id: string, acceptedBy: string[]) => {
      const current = quests.find(q => q.id === id);
      if (!current) return;

      const newDetails = {
          ...current.details,
          acceptedBy,
          alignment: current.alignment // Preserve alignment in DB stash
      };

      // Optimistic
      setQuests(prev => prev.map(q => q.id === id ? { 
          ...q, 
          status: QuestStatus.IN_PROGRESS, 
          details: { ...q.details, acceptedBy } 
      } : q));

      try {
          await supabase.from('quests').update({
              status: QuestStatus.IN_PROGRESS,
              details: newDetails
          }).eq('id', id);
      } catch (err) {
          console.error("Error accepting quest:", err);
          fetchQuests();
      }
  };

  return { quests, loading, addQuest, editQuest, updateStatus, acceptQuest, refresh: fetchQuests };
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '../supabaseClient';
