// Log Line Renderer Component
const LogLineRenderer: React.FC<{ line: string }> = ({ line }) => {
    if (!line.trim()) return <div className="h-2"></div>;

    // Detect Line Type
    const isBuff = line.trim().startsWith('> (') && line.trim().endsWith(')');
    const isCombo = line.trim().startsWith('> [') && line.trim().endsWith(']');
    const isRoundHeader = line.includes('НАЧАЛО РАУНДА') || line.includes('ЗАВЕРШЕНИЕ');

    // 1. Buff Line: > (Actor: Ability (Mech))
    if (isBuff) {
        // Remove > and outer parens
        const content = line.replace(/^>\s*\((.*)\)$/, '$1'); 
        // Split Name: Rest
        const parts = content.split(/:(.+)/);
        if (parts.length < 2) return <div className="text-emerald-300 pl-2 border-l-2 border-emerald-500/30">{line}</div>;

        return (
            <div className="flex items-start gap-1 pl-2 border-l-2 border-emerald-500/50 bg-emerald-900/10 py-0.5 rounded-r">
                <span className="text-emerald-400 font-bold whitespace-nowrap">{parts[0]}:</span>
                <span className="text-emerald-200">{parts[1]}</span>
            </div>
        );
    }

    // 2. Combo Line: > [Actor: Abil + Actor: Abil (Dice)]
    if (isCombo) {
        const content = line.replace(/^>\s*\[(.*)\]$/, '$1');
        // Extract dice part (usually at end in parens)
        const diceMatch = content.match(/\(([^)]+)\)$/);
        const mainPart = diceMatch ? content.replace(diceMatch[0], '') : content;

        return (
            <div className="flex flex-wrap items-center gap-1 pl-2 border-l-2 border-blue-500/50 bg-blue-900/10 py-0.5 rounded-r text-blue-100">
                <span className="font-bold text-blue-300">КОМБО:</span>
                <span className="font-serif">{mainPart}</span>
                {diceMatch && <span className="text-cyan-300 font-mono font-bold bg-black/40 px-1 rounded">{diceMatch[0]}</span>}
            </div>
        );
    }

    // 3. Round Headers
    if (isRoundHeader) {
        return <div className="text-center font-rune font-bold text-violet-400 py-4 opacity-80 border-b border-violet-900/30 mb-2">{line}</div>;
    }

    // 4. Standard Action: > Name: Ability(Dice)
    // We try to highlight Name, Ability and Dice
    const standardMatch = line.match(/^>\s*([^:]+):\s*([^(]+)(\(.*\))?$/);

    if (standardMatch) {
        const [_, name, ability, dice] = standardMatch;
        return (
            <div className="flex flex-wrap items-baseline gap-1 pl-2 hover:bg-white/5 rounded py-0.5">
                <span className="text-amber-400 font-bold whitespace-nowrap">{name}:</span>
                <span className="text-slate-200">{ability}</span>
                {dice && <span className="text-cyan-400 font-mono font-bold bg-black/30 px-1 rounded text-xs">{dice}</span>}
            </div>
        );
    }

    // Fallback
    return <div className="text-slate-400 pl-2">{line}</div>;
};


// Tabs
type Tab = 'stats' | 'log' | 'summary';

const BattleLog: React.FC<Props> = ({ logs, currentRound, participants, onUpdateLogs, onUpdateParticipant, onRollback }) => {
  const [activeTab, setActiveTab] = useState<Tab>('log'); 
  const [viewRound, setViewRound] = useState(currentRound);

  // Text Areas State
  const [summaryText, setSummaryText] = useState("");
  const [localLogText, setLocalLogText] = useState("");
  const [localStatsText, setLocalStatsText] = useState("");

  const [isDirty, setIsDirty] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false); // Toggle between Rich View and Textarea

  useEffect(() => {
      setViewRound(currentRound);
  }, [currentRound]);

  // Sync Data on Round Change or Mount
  useEffect(() => {
      // 1. LOG TEXT
      const roundEntries = logs.filter(l => l.round === viewRound && l.type !== 'system');
      // For rich view, we need entries. For text area, we need string.
      const joinedText = roundEntries.map(l => l.text_formatted).join('\n');
      setLocalLogText(joinedText);

      // 2. FIND SNAPSHOT
      const snapshotLog = logs.find(l => l.round === viewRound && l.details?.participants_snapshot);

      // 3. SUMMARY
      const allEntriesForRound = logs.filter(l => l.round === viewRound);
      const entryWithSummary = allEntriesForRound.reverse().find(l => l.summary !== undefined && l.summary !== null && l.type !== 'system');

      if (entryWithSummary) {
          setSummaryText(entryWithSummary.summary || "");
      } else if (snapshotLog && snapshotLog.summary) {
          setSummaryText(snapshotLog.summary);
      } else {
          if (viewRound === currentRound) {
              setSummaryText(generateSummary(participants, currentRound));
          } else {
              setSummaryText("(Нет сохраненного итога)"); 
          }
      }

      // 4. STATS
      if (!isDirty) {
          if (viewRound === currentRound) {
              setLocalStatsText(generateStatsText(participants));
          } else if (snapshotLog && snapshotLog.details?.stats_snapshot) {
              setLocalStatsText(snapshotLog.details.stats_snapshot);
          } else {
              setLocalStatsText("(Нет сохраненных характеристик)");
          }
      }

      setIsDirty(false);
  }, [viewRound, logs, participants, currentRound]); 

  const handleTextChange = (setter: React.Dispatch<React.SetStateAction<string>>) => (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      setter(e.target.value);
      setIsDirty(true);
  };

  const parseAndSaveStats = () => {
      if (!onUpdateParticipant) return;

      const blocks = localStatsText.split(/\n\s*\n/);

      blocks.forEach(block => {
          const lines = block.split('\n').map(l => l.trim()).filter(l => l);
          if (lines.length === 0) return;

          const headerMatch = lines[0].match(/^(.+)\s\(\d+\s*ур\.\)$/i);
          const name = headerMatch ? headerMatch[1].trim() : lines[0].trim();

          const participant = participants.find(p => p.profile.name === name);
          if (participant) {
              const newStats = { ...participant.stats };

              lines.forEach(line => {
                  const lower = line.toLowerCase();
                  const matchVal = line.match(/:\s*(-?\d+)/);

                  if (matchVal) {
                      const val = parseInt(matchVal[1]);
