            onClick={() => setActiveTab('summary')}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-all ${activeTab === 'summary' ? 'bg-violet-900/20 text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-white'}`}
          >
              <ListEnd size={14} /> Итог
          </button>
      </div>

      {/* 2. ROUND CONTROLS */}
      <div className="bg-[#050b14] border-b border-violet-900/20 p-2 flex items-center justify-between text-xs">
          <div className="flex items-center gap-2">
              <button 
                onClick={() => setViewRound(Math.max(0, viewRound - 1))}
                disabled={viewRound <= 0}
                className="p-1 hover:bg-slate-800 rounded disabled:opacity-30 text-slate-400 hover:text-white"
              >
                  <ChevronLeft size={16} />
              </button>
              <span className="font-bold text-violet-400 uppercase font-rune tracking-widest">{viewRound === 0 ? "Подготовка" : `Раунд ${viewRound}`}</span>
              <button 
                onClick={() => setViewRound(Math.min(currentRound, viewRound + 1))}
                disabled={viewRound >= currentRound}
                className="p-1 hover:bg-slate-800 rounded disabled:opacity-30 text-slate-400 hover:text-white"
              >
                  <ChevronRight size={16} />
              </button>
          </div>
          <div className="flex items-center gap-2">
              {canRollback && onRollback && (
                  <button 
                    onClick={() => onRollback(viewRound)}
                    className="flex items-center gap-1 bg-red-900/20 hover:bg-red-900/40 text-red-400 border border-red-900/50 rounded px-2 py-1 text-[10px] uppercase font-bold transition-all mr-2"
                    title="Вернуться к состоянию на конец этого раунда"
                  >
                      <RotateCcw size={10} /> Переиграть сл.
                  </button>
              )}

              {isDirty && (
                  <button 
                    onClick={saveChanges}
                    className="flex items-center gap-1 text-emerald-400 hover:text-emerald-300 font-bold animate-pulse uppercase text-[10px] tracking-wider"
                  >
                      <Save size={12} /> Сохранить
                  </button>
              )}
          </div>
      </div>

      {/* 3. CONTENT AREA */}
      <div className="flex-1 bg-[#020408] relative overflow-hidden flex flex-col">

         {activeTab === 'stats' && (
             <div className="h-full flex flex-col">
                 <textarea 
                    className="flex-1 bg-[#020408] text-slate-300 p-4 outline-none resize-none font-mono text-xs leading-relaxed selection:bg-violet-900/50"
                    value={localStatsText}
                    onChange={handleTextChange(setLocalStatsText)}
                    spellCheck={false}
                    placeholder="Данные участников..."
                 />
             </div>
         )}

         {activeTab === 'log' && (
             <div className="h-full flex flex-col relative group">
                 {/* Gutter / Line Indicators */}
                 <div 
                    ref={gutterRef}
                    className="absolute top-0 left-0 bottom-0 w-7 bg-[#050b14] border-r border-violet-900/30 overflow-hidden select-none z-0 flex flex-col items-center pt-4"
                 >
                    {localLogText.split('\n').map((line, i) => {
                        let colorClass = 'bg-transparent opacity-0';
                        const trim = line.trim();

                        if (trim.includes('НАЧАЛО РАУНДА') || trim.includes('ЗАВЕРШЕНИЕ')) {
                            colorClass = 'bg-violet-500 shadow-[0_0_8px_#8b5cf6] opacity-100 h-1.5 w-4 rounded-sm';
                        } else if (trim.startsWith('> (')) {
                            // Buff
                            colorClass = 'bg-emerald-500 shadow-[0_0_5px_#10b981] opacity-100 h-3 w-1 rounded-full';
                        } else if (trim.startsWith('> [')) {
                            // Combo
                            colorClass = 'bg-blue-500 shadow-[0_0_5px_#3b82f6] opacity-100 h-3 w-1 rounded-full';
                        } else if (trim.startsWith('>')) {
                            // Attack
                            colorClass = 'bg-amber-600 shadow-[0_0_5px_#d97706] opacity-100 h-3 w-1 rounded-full';
                        }

                        return (
                            <div key={i} className="h-6 w-full flex items-center justify-center shrink-0">
                                <div className={`${colorClass} transition-all duration-300`} />
                            </div>
                        );
                    })}
                 </div>

                 {/* Editable Area - Perfectly synced with Gutter via line-height */}
                 <textarea 
                    ref={textareaRef}
                    className="absolute inset-0 w-full h-full bg-transparent text-slate-300 p-4 pl-10 resize-none font-mono text-xs outline-none border-none whitespace-pre selection:bg-violet-900/50"
                    style={{ lineHeight: '24px' }}
                    value={localLogText}
                    onChange={handleTextChange(setLocalLogText)}
                    onScroll={handleScroll}
                    spellCheck={false}
                    placeholder="Лог раунда пуст..."
                 />
             </div>
         )}

         {activeTab === 'summary' && (
             <div className="h-full flex flex-col">
                 <div className="p-2 bg-violet-900/10 text-[10px] text-slate-500 uppercase tracking-widest border-b border-violet-900/20 flex justify-between items-center">
                     <span>Сводка (Раунд {viewRound})</span>
                     <button onClick={() => navigator.clipboard.writeText(summaryText)} title="Копировать" className="hover:text-white"><Clipboard size={12}/></button>
                 </div>
                 <textarea 
                    className="flex-1 bg-[#020408] text-slate-300 p-4 text-xs font-mono outline-none resize-none selection:bg-emerald-900/50"
                    value={summaryText}
                    onChange={handleTextChange(setSummaryText)}
                    placeholder={viewRound < currentRound && !summaryText ? "(Нет сохраненного итога)" : "Здесь будет сводка раунда..."}
                    spellCheck={false}
                 />
             </div>
         )}
      </div>
    </div>
  );
};

export default BattleLog;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { DndContext, DragEndEvent, DragOverlay, useSensor, useSensors, PointerSensor, DragStartEvent, pointerWithin } from '@dnd-kit/core';
import { arrayMove } from '@dnd-kit/sortable';
import { BattleParticipant, LogEntry, SequenceNode, BattleStatus, CharacterTemplate, ActiveEffect, Cooldown, JsonInjury } from './types';
import { advanceRound, tickActionTimers } from './engine/timeEngine';
import { calculateSequenceTree } from './engine/calculator';
import { generateSummary, generateStatsText } from './engine/formatters';
import SourcePanel from './components/SourcePanel';
import SequenceCanvas from './components/SequenceCanvas';
import BattleLog from './components/BattleLog';
import { Modal } from './components/Modal';
import { updateBattle, getCharacters, createBattle, getBattles, calculateTraumaPenalty, updateCharacter, deleteBattle, supabase } from './lib/supabase';
import { UserPlus, Save, Play, Square, List, RefreshCw, Trash2, Search, Filter, HardDrive, Cloud } from 'lucide-react';

// UI State Types
type ModalType = 'CREATE_BATTLE' | 'CONFIRM_SAVE' | 'CONFIRM_END' | 'FINALIZE_BATTLE' | 'ALERT' | 'CHAR_SELECT' | 'BATTLE_LIST' | 'CONFIRM_DELETE' | null;

interface BattleModuleProps {
  isAdmin?: boolean;
}

const LOCAL_STORAGE_KEY = 'juul_d_local_battles';

const App: React.FC<BattleModuleProps> = ({ isAdmin = false }) => {
  const [participants, setParticipants] = useState<BattleParticipant[]>([]);
  const [round, setRound] = useState<number>(0); 
  const [status, setStatus] = useState<BattleStatus>('startup');
  const [battleName, setBattleName] = useState('Новый Бой');
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [battleId, setBattleId] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);
  const [allCharacters, setAllCharacters] = useState<CharacterTemplate[]>([]);
  const [savedBattles, setSavedBattles] = useState<any[]>([]);

  const [activeModal, setActiveModal] = useState<ModalType>(null);
  const [modalInput, setModalInput] = useState('');
  const [alertMessage, setAlertMessage] = useState('');
  const [pendingAction, setPendingAction] = useState<() => void>(() => {});

  // Character Selection State
  const [charSearchTerm, setCharSearchTerm] = useState('');
  const [selectedFaction, setSelectedFaction] = useState<string>('All');
  const [selectedVolume, setSelectedVolume] = useState<string>('All');

  // State for Finalize Battle Modal
  const [participantsToSave, setParticipantsToSave] = useState<Set<string>>(new Set());

  // State for Deletion
  const [battleToDelete, setBattleToDelete] = useState<string | null>(null);

  const [tree, setTree] = useState<SequenceNode[]>([]);
  const [activeDragItem, setActiveDragItem] = useState<any>(null);
  const [activeNode, setActiveNode] = useState<SequenceNode | null>(null);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }));

  const initRef = useRef(false);

  // --- INIT ---
  useEffect(() => {
    if (initRef.current) return;
    initRef.current = true;

    async function loadResources() {
        // Load Characters
        const { data: chars } = await getCharacters();
        if (chars && chars.length > 0) {
             setAllCharacters(chars);
        }

        // Load Battles based on role
        if (isAdmin) {
            const { data: battles } = await getBattles();
            if (battles) setSavedBattles(battles);
        } else {
            const localData = localStorage.getItem(LOCAL_STORAGE_KEY);
            if (localData) {
                try {
                    setSavedBattles(JSON.parse(localData));
                } catch (e) {
                    console.error("Failed to parse local battles", e);
                    setSavedBattles([]);
                }
            }
        }
    }
    loadResources();
  }, [isAdmin]);

  // --- DERIVED LISTS FOR FILTERS ---
  const uniqueFactions = useMemo(() => {
      const factions = new Set<string>();
      allCharacters.forEach(c => {
          if (c.profile.faction && c.profile.faction !== 'Могильник') {
              factions.add(c.profile.faction);
          }
      });
      return Array.from(factions).sort();
  }, [allCharacters]);

  const uniqueVolumes = useMemo(() => {
      const isNpcLike = ['NPC', 'НПС', 'Бестиарий'].includes(selectedFaction);
      if (!isNpcLike) return [];

      const volumes = new Set<string>();
      allCharacters.forEach(c => {
          if (c.profile.faction === selectedFaction && c.profile.npc_volume) {
              volumes.add(c.profile.npc_volume);
          }
      });
      return Array.from(volumes).sort();
  }, [allCharacters, selectedFaction]);


  // --- MEMOIZED FILTERING ---
  const filteredCharacters = useMemo(() => {
    let result = [...allCharacters];
    result = result.filter(c => c.profile.faction !== 'Могильник');

    if (charSearchTerm) {
        const lower = charSearchTerm.toLowerCase();
        result = result.filter(c => c.profile.name.toLowerCase().includes(lower));
    }

    if (selectedFaction !== 'All') {
        result = result.filter(c => c.profile.faction === selectedFaction);
    }

    const isNpcLike = ['NPC', 'НПС', 'Бестиарий'].includes(selectedFaction);
    if (isNpcLike && selectedVolume !== 'All') {
         result = result.filter(c => c.profile.npc_volume === selectedVolume);
    }

    result.sort((a, b) => a.profile.name.localeCompare(b.profile.name));
    return result;
  }, [allCharacters, charSearchTerm, selectedFaction, selectedVolume]);

  // --- UI HELPERS ---
  const showAlert = (msg: string) => {
      setAlertMessage(msg);
      setActiveModal('ALERT');
  };

  const closeModal = () => {
      setActiveModal(null);
      setModalInput('');
      setAlertMessage('');
      setCharSearchTerm('');
      setSelectedFaction('All');
      setSelectedVolume('All');
  };

  const getStatusLabel = (s: string) => {
       if (s === 'active') return 'АКТИВЕН';
       if (s === 'finished') return 'ЗАВЕРШЕН';
       if (s === 'startup') return 'ПОДГОТОВКА';
       return s;
  };

  const getCharacterStyle = (faction: string) => {
      const f = (faction || '').toLowerCase();
      if (['светлые', 'light', 'свет'].includes(f)) return 'bg-amber-900/10 border-amber-600/50 hover:bg-amber-900/20 text-amber-100';
      if (['тёмные', 'dark', 'темные', 'тьма'].includes(f)) return 'bg-indigo-950/30 border-indigo-500/50 hover:bg-indigo-900/20 text-indigo-100';
      if (['npc', 'нпс', 'бестиарий'].includes(f)) return 'bg-red-950/20 border-red-800/50 hover:bg-red-900/20 text-red-100';
      return 'bg-panel border-violet-900/30 hover:border-violet-500/50 text-slate-200';
  };

  const handleUpdateParticipant = (id: string, updates: any) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== id) return p;
          return { ...p, ...updates };
      }));
  };

  const handleToggleEquip = (participantId: string, itemId: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const newWearable = p.equipment.wearable.map(item => {
              if (item._id === itemId) return { ...item, is_equipped: !item.is_equipped };
              return item;
          });
          return { ...p, equipment: { ...p.equipment, wearable: newWearable } };
      }));
  };

  const handleRemoveParticipant = (participantId: string) => {
      setParticipants(prev => prev.filter(p => p.instance_id !== participantId));
  };

  const handleRemoveEffect = (participantId: string, effectId: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const effectToRemove = p.active_effects.find(e => e.id === effectId);
          const nextEffects = p.active_effects.filter(e => e.id !== effectId);

          let nextCooldowns = [...p.cooldowns];
          if (effectToRemove?.original_ability_id) {
               const sourceAbility = p.flat_abilities.find(a => a._id === effectToRemove.original_ability_id);
               if (sourceAbility && sourceAbility.cd > 0) {
                   if (!nextCooldowns.some(cd => cd.name === sourceAbility.name)) {
                       nextCooldowns.push({
                          id: `cd_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                          name: sourceAbility.name,
                          val: sourceAbility.cd,
                          max: sourceAbility.cd,
                          unit: sourceAbility.cd_unit || 'turn'
                       });
                   }
               }
          }
          return { ...p, active_effects: nextEffects, cooldowns: nextCooldowns };
      }));
  };

  const handleRemoveCooldown = (participantId: string, cdId: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          return { ...p, cooldowns: p.cooldowns.filter(cd => cd.id !== cdId) };
      }));
  };

  const handleAddInjury = (participantId: string, templateId: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const newInjuries = [...p.medcard.injuries, { count: 1, template_id: templateId, custom_name: '' }];
          const trauma = calculateTraumaPenalty(newInjuries);
          return {
              ...p,
              medcard: { ...p.medcard, injuries: newInjuries },
              battle_stats: { ...p.battle_stats, hp_penalty_current: trauma.total, trauma_phys: trauma.phys, trauma_mag: trauma.mag, trauma_uniq: trauma.uniq }
          };
      }));
  };

  const handleRemoveInjury = (participantId: string, index: number) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const newInjuries = [...p.medcard.injuries];
          newInjuries.splice(index, 1);
          const trauma = calculateTraumaPenalty(newInjuries);
          return {
              ...p,
              medcard: { ...p.medcard, injuries: newInjuries },
              battle_stats: { ...p.battle_stats, hp_penalty_current: trauma.total, trauma_phys: trauma.phys, trauma_mag: trauma.mag, trauma_uniq: trauma.uniq }
          };
      }));
  };

  const handleAddDebuff = (participantId: string, name: string, tag: string, val: number, dur: number, unit: string, extraTags?: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const finalTags = [];
          if (tag && tag !== 'none') finalTags.push(tag);
          if (extraTags) finalTags.push(extraTags.toLowerCase().trim());

          const newEffect: ActiveEffect = {
              id: `custom_${Date.now()}`,
              name: name,
              tags: finalTags,
              bonuses: [{ val: val, stat: tag }],
              duration_left: dur,
              unit: unit || 'turn'
          };
          return { ...p, active_effects: [...p.active_effects, newEffect] };
      }));
  };

  // --- BATTLE LOGIC ---

  const loadBattle = async (id: string) => {
      setLoading(true);

      let foundBattle = null;

      if (isAdmin) {
          const { data: b } = await supabase.from('battles').select('*').eq('id', id).single();
          foundBattle = b;
      } else {
          // Local storage lookup
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
          foundBattle = localData.find((b: any) => b.id === id);
      }

      if (foundBattle) {
          setBattleId(foundBattle.id);
          setBattleName(foundBattle.name || 'Бой без названия');
          setRound(foundBattle.round);
          setStatus(foundBattle.status || 'startup');
          setLogs(foundBattle.sequence_log || []);
          setParticipants(foundBattle.participants_snapshot || []);
      }
      setLoading(false);
      setActiveModal(null);
  };

  const handleDeleteBattle = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      setBattleToDelete(id);
      setActiveModal('CONFIRM_DELETE');
  };

  const confirmDeleteBattle = async () => {
      if (!battleToDelete) {
          setActiveModal('BATTLE_LIST');
          return;
      }

      if (isAdmin) {
          // Admin Delete from DB
          const { error } = await deleteBattle(battleToDelete);
          if (error) {
              showAlert(`Ошибка удаления: ${error.message}`);
              return;
          }
      } else {
          // Local Delete
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
          const newData = localData.filter((b: any) => b.id !== battleToDelete);
          localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(newData));
          setSavedBattles(newData);
      }

      setSavedBattles(prev => prev.filter(b => b.id !== battleToDelete));

      if (battleId === battleToDelete) {
          setBattleId(null);
          setBattleName('Новый Бой');
          setRound(1);
          setStatus('startup');
          setLogs([]);
          setParticipants([]);
          setTree([]);
          setBattleToDelete(null);
          showAlert(isAdmin ? "Бой удален из базы." : "Бой удален из локального хранилища.");
      } else {
          setBattleToDelete(null);
          setActiveModal('BATTLE_LIST');
      }
  };

  const cancelDelete = () => {
      setBattleToDelete(null);
      setActiveModal('BATTLE_LIST');
  };

  const handleCreateBattleClick = () => {
      setModalInput('');
      setActiveModal('CREATE_BATTLE');
  };

  const confirmCreateBattle = async () => {
      const name = modalInput || "Стычка у ворот";
      setLoading(true);

      const newBattle = {
          id: `battle_${Date.now()}_${Math.random().toString(36).substr(2,5)}`,
          name,
          participants_snapshot: [],
          sequence_log: [],
          casualties: [],
          round: 0,
          status: 'startup'
      };

      if (isAdmin) {
          const { data, error } = await createBattle(name);
          if (error) {
              showAlert(`Failed to create battle in DB. Error: ${error.message}`);
              setLoading(false);
              return;
          }
          if (data) {
              setBattleId(data.id);
              setBattleName(data.name);
          }
      } else {
          // Local Create
          setBattleId(newBattle.id);
          setBattleName(newBattle.name);

          // Save initial state to local
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
          localData.push(newBattle);
          localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
          setSavedBattles(localData);
      }

      setRound(0);
      setStatus('startup');
      setParticipants([]);
      setLogs([]);
      setLoading(false);
      closeModal();
  };

  const handleSaveBattle = async () => {
      if (!battleId) {
          // This path should ideally be covered by "Create Battle", but as a fallback:
          setPendingAction(() => async () => {
               // Similar logic to confirmCreateBattle but saving current state
               // For now just alert to use Create
               showAlert("Пожалуйста, создайте бой через меню 'Архив' -> 'Создать'.");
               closeModal();
          });
          setActiveModal('CONFIRM_SAVE');
          return;
      }

      const battleState = {
          name: battleName,
          participants_snapshot: participants,
          sequence_log: logs,
          round: round,
          status: status,
          casualties: []
      };

      if (isAdmin) {
          const { error } = await updateBattle(battleId, battleState);
          if (error) {
              showAlert(`Ошибка сохранения: ${error.message}`);
          } else {
              showAlert("Бой успешно сохранен в базе данных.");
          }
      } else {
          // Local Save Update
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
          const index = localData.findIndex((b: any) => b.id === battleId);
          if (index !== -1) {
              localData[index] = { ...localData[index], ...battleState };
          } else {
              localData.push({ id: battleId, ...battleState });
          }
          localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
          setSavedBattles(localData);
          showAlert("Бой сохранен локально.");
      }
  };

  const updateBattleName = async (newName: string) => {
      setBattleName(newName);
  };

  const addParticipant = (template: CharacterTemplate) => {
      const flatAbilities = (template.ability_groups || []).flatMap(g => g.abilities || []);

      // Fallback: If flat_passives didn't populate for some reason, build it from groups
      let passivesToScan = template.flat_passives || [];
      if (passivesToScan.length === 0 && template.passives) {
          passivesToScan = template.passives.flatMap(g => g.items);
      }

      // COMBAT_START TRIGGER CHECK - MORE ROBUST
      const startupEffects: ActiveEffect[] = [];
      let logText = "";

      passivesToScan.forEach(pas => {
          if (!pas.trigger) return;
          const trig = pas.trigger.toUpperCase();
          // Check for keywords rather than exact matches to handle potential data variations
          if (trig.includes('START') || trig.includes('НАЧАЛО') || trig.includes('COMBAT') || trig.includes('БОЯ')) {
              // Format: (Name: Ability (Mechanics)) - Wrapped in () to trigger Emerald color logic in Log
              const mechInfo = pas.desc_mech ? ` (${pas.desc_mech})` : '';
              logText += `> (${template.profile.name}: ${pas.name}${mechInfo})\n`;

              const hasDuration = pas.dur && pas.dur > 0;
              startupEffects.push({
                  id: `start_passive_${pas._id || Math.random()}_${Date.now()}`,
                  name: pas.name,
                  tags: [...(pas.tags || []), pas.is_flaw ? 'debuff' : 'buff'],
                  bonuses: pas.bonuses || [],
                  duration_left: hasDuration ? pas.dur! : 999,
                  unit: hasDuration ? (pas.dur_unit || 'turn') : 'battle',
                  original_ability_id: pas._id
              });
          }
      });

      const newP: BattleParticipant = {
          ...template,
          instance_id: `char_${template.id}_${Date.now()}`,
          is_player: false,

          battle_stats: (template as any).battle_stats || {
              hp_penalty_current: 0,
              trauma_phys: 0,
              trauma_mag: 0,
              trauma_uniq: 0,
              actions_max: 4,
              actions_left: 4
          },
          active_effects: startupEffects,
          cooldowns: [],
          usage_counts: {}, 
          flat_abilities: flatAbilities,
          flat_passives: passivesToScan
      };

      setParticipants(prev => [...prev, newP]);

      if (logText) {
          setLogs(prev => [...prev, {
              id: `trigger_add_${newP.instance_id}_${Date.now()}`,
              round: round,
              timestamp: new Date().toISOString(),
              type: 'action', 
              text_formatted: logText.trim()
          }]);
      }

      setActiveModal(null);
  };

  const handleNextRound = async () => {
    // 1. Snapshot State of current round (Before advancement)
    const summary = generateSummary(participants, round);
    const statsSnapshot = generateStatsText(participants);

    // We deep clone participants to ensure snapshot isn't mutated later
    const participantsSnapshot = JSON.parse(JSON.stringify(participants));

    const endRoundLog: LogEntry = {
      id: `end_rnd_${round}_${Date.now()}`,
      round: round,
      timestamp: new Date().toISOString(),
      type: 'system',
      text_formatted: round === 0 ? `ЗАВЕРШЕНИЕ ПОДГОТОВКИ` : `ЗАВЕРШЕНИЕ РАУНДА ${round}`,
      summary: summary,
      details: {
          stats_snapshot: statsSnapshot,
          participants_snapshot: participantsSnapshot
      }
    };

    // 2. Prepare Next Round
    const nextR = round + 1;
    let newStatus = status;
    if (status === 'startup') {
        newStatus = 'active';
        setStatus('active');
    }

    // 3. Advance logic
    let advancedParticipants = [...participants];

    if (round === 0) {
        // SPECIAL CASE: Round 0 -> 1 (Start Battle)
    } else {
        // Normal Round Transition: Tick timers
        advancedParticipants = advanceRound(participants);
    }

    const startRoundLog: LogEntry = {
        id: `start_rnd_${nextR}_${Date.now()}`,
        round: nextR,
        timestamp: new Date().toISOString(),
        text_formatted: `НАЧАЛО РАУНДА ${nextR}`,
        type: 'round_change'
    };

    const logsToAdd = [endRoundLog, startRoundLog];

    // 4. Update State
    const updatedLogs = [...logs, ...logsToAdd];

    setRound(nextR);
    setParticipants(advancedParticipants);
    setLogs(updatedLogs);
    setStatus(newStatus);

    if (battleId) {
        if (isAdmin) {
            await updateBattle(battleId, { 
                sequence_log: updatedLogs, 
                round: nextR, 
                status: newStatus,
                participants_snapshot: advancedParticipants 
            });
        } else {
            // Auto-save local on round change
            const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
            const index = localData.findIndex((b: any) => b.id === battleId);
            const battleState = {
                name: battleName,
                participants_snapshot: advancedParticipants,
                sequence_log: updatedLogs,
                round: nextR,
                status: newStatus
            };
            if (index !== -1) {
                localData[index] = { ...localData[index], ...battleState };
            }
            localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
        }
    }
  };

  const handleRollback = async (targetRound: number) => {
      const snapshotLog = logs.find(l => l.round === targetRound && l.details?.participants_snapshot);

      if (!snapshotLog) {
          showAlert("Невозможно откатить: нет сохраненного состояния для этого раунда.");
          return;
      }

      setParticipants(snapshotLog.details.participants_snapshot);
      setRound(snapshotLog.round);

      const newLogs = logs.filter(l => l.round <= targetRound && l.id !== snapshotLog.id);

      setLogs(newLogs);

      if (battleId) {
          const updatePayload = {
              round: snapshotLog.round,
              participants_snapshot: snapshotLog.details.participants_snapshot,
              sequence_log: newLogs,
              status: 'active'
          };

          if (isAdmin) {
              await updateBattle(battleId, updatePayload);
          } else {
              const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
              const index = localData.findIndex((b: any) => b.id === battleId);
              if (index !== -1) {
                  localData[index] = { ...localData[index], ...updatePayload };
                  localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
              }
          }
      }

      showAlert(`Откат выполнен. Вы вернулись в Раунд ${targetRound}.`);
  };

  // ... (rest of modals logic: handleEndBattleClick, finalizeBattle, etc. same as before) ...
  const handleEndBattleClick = () => {
      const injuredIds = new Set<string>();
      participants.forEach(p => {
          if (p.medcard.injuries.length > 0) {
              injuredIds.add(p.instance_id);
          }
      });
      setParticipantsToSave(injuredIds);
      setActiveModal('FINALIZE_BATTLE');
  };

  const handleToggleSaveParticipant = (id: string) => {
      const next = new Set(participantsToSave);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setParticipantsToSave(next);
  };

  const finalizeBattle = async () => {
      if (!isAdmin) {
          // Non-admins cannot write back to DB
          setStatus('finished');
          showAlert("Бой завершен локально. Не-админы не могут обновлять травмы в базе персонажей.");
          closeModal();
          return;
      }

      setLoading(true);
      for (const p of participants) {
          if (participantsToSave.has(p.instance_id)) {
              await updateCharacter(p.id, {
                  medcard: p.medcard
              });
          }
      }
      setStatus('finished');
      if (battleId) {
          const { error } = await updateBattle(battleId, { status: 'finished' });
          if (error) console.error("Failed to update battle status", error);
      }
      setLoading(false);
      closeModal();
      showAlert("Бой финализирован. Травмы для выбранных персонажей обновлены в базе данных.");
  };

  const confirmEndBattle = async () => {
      setStatus('finished');
      if (battleId) {
          if (isAdmin) {
              const { error } = await updateBattle(battleId, { status: 'finished' });
              if (error) showAlert(`Failed to update status in DB: ${error.message}`);
          } else {
              const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
              const index = localData.findIndex((b: any) => b.id === battleId);
              if (index !== -1) {
                  localData[index].status = 'finished';
                  localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
              }
          }
      }
      closeModal();
  };

  const extractActionsFromTree = (nodes: SequenceNode[]): SequenceNode[] => {
      let actions: SequenceNode[] = [];
      for (const node of nodes) {
          if (node.type === 'action') actions.push(node);
          if (node.children) actions = actions.concat(extractActionsFromTree(node.children));
      }
      return actions;
  };

  const handleCommit = async () => {
    if (tree.length === 0) {
        showAlert("Холст пуст. Добавьте действия или комбо.");
        return;
    }

    const result = calculateSequenceTree(tree, participants);

    const newLog: LogEntry = {
        id: Date.now().toString(),
        round: round,
        timestamp: new Date().toISOString(),
        text_formatted: result.formattedString || 'Пустое действие',
        type: 'action'
    };

    let updatedParticipants = [...participants];

    const actionNodes = extractActionsFromTree(tree);
    const actionsPerActor: Record<string, number> = {};
    const abilitiesUsed: { charId: string, abilityId: string }[] = [];

    actionNodes.forEach(node => {
        const charId = node.data?.charId;
        const abilityId = node.data?.abilityId;
        if (charId) {
            actionsPerActor[charId] = (actionsPerActor[charId] || 0) + 1;
        }
        if (charId && abilityId) {
            abilitiesUsed.push({ charId, abilityId });
        }
    });

    const effectsToApply: { charId: string, effect: ActiveEffect }[] = [];
    const cooldownsToApply: { charId: string, cooldown: Cooldown }[] = [];

    actionNodes.forEach(node => {
        const charId = node.data?.charId;
        const abilityId = node.data?.abilityId;
        if (!charId || !abilityId) return;

        const actor = participants.find(p => p.instance_id === charId);
        if (!actor) return;

        let ability = actor.flat_abilities.find(a => a._id === abilityId);
        if (!ability) {
             actor.ability_groups.forEach(g => {
                 const found = g.abilities.find(a => a._id === abilityId);
                 if (found) ability = found;
             });
        }

        if (ability) {
            if (ability.dur > 0) {
                effectsToApply.push({
                    charId,
                    effect: {
                        id: `eff_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                        name: ability.name,
                        tags: ability.tags,
                        bonuses: ability.bonuses,
                        duration_left: ability.dur,
                        unit: ability.dur_unit || 'turn',
                        original_ability_id: ability._id
                    }
                });
            }
            if (ability.cd > 0 && ability.dur === 0) {
                if (!ability.limit || ability.limit <= 0) {
                    cooldownsToApply.push({
                        charId,
                        cooldown: {
                            id: `cd_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                            name: ability.name,
                            val: ability.cd,
                            max: ability.cd,
                            unit: ability.cd_unit || 'turn'
                        }
                    });
                }
            }
        }
    });

    updatedParticipants = updatedParticipants.map(p => {
        let processedP = p;
        if (actionsPerActor[p.instance_id]) {
            processedP = tickActionTimers(p, actionsPerActor[p.instance_id]);
        }

        const myUsages = abilitiesUsed.filter(u => u.charId === p.instance_id);
        const nextUsageCounts = { ...processedP.usage_counts };
        const limitBasedCooldowns: Cooldown[] = [];

        myUsages.forEach(usage => {
             const ability = processedP.flat_abilities.find(a => a._id === usage.abilityId);
             if (ability) {
                 const current = nextUsageCounts[ability._id] || 0;
                 const next = current + 1;
                 nextUsageCounts[ability._id] = next;

                 if (ability.limit && ability.limit > 0) {
                     if (next >= ability.limit) {
                          if (ability.cd > 0) {
                              limitBasedCooldowns.push({
                                  id: `cd_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                                  name: ability.name,
                                  val: ability.cd,
                                  max: ability.cd,
                                  unit: ability.cd_unit || 'turn'
                              });
                          }
                     }
                 }
             }
        });

        processedP = { ...processedP, usage_counts: nextUsageCounts };

        const myNewEffects = effectsToApply
            .filter(item => item.charId === p.instance_id)
            .map(item => item.effect);

        const myNewCooldowns = cooldownsToApply
            .filter(item => item.charId === p.instance_id)
            .map(item => item.cooldown);

        const allNewCooldowns = [...myNewCooldowns, ...limitBasedCooldowns];

        const finalCooldowns = [...processedP.cooldowns];
        allNewCooldowns.forEach(newCD => {
             if (!finalCooldowns.some(existing => existing.name === newCD.name)) {
                 finalCooldowns.push(newCD);
             }
        });

        return {
            ...processedP,
            active_effects: [...processedP.active_effects, ...myNewEffects],
            cooldowns: finalCooldowns
        };
    });

    setParticipants(updatedParticipants);
    const updatedLogs = [...logs, newLog];
    setLogs(updatedLogs);
    setTree([]); 

    if (battleId) {
        if (isAdmin) {
            await updateBattle(battleId, { 
                sequence_log: updatedLogs, 
                participants_snapshot: updatedParticipants
            });
        } else {
            const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
            const index = localData.findIndex((b: any) => b.id === battleId);
            if (index !== -1) {
                localData[index] = { 
                    ...localData[index], 
                    sequence_log: updatedLogs, 
                    participants_snapshot: updatedParticipants 
                };
                localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
            }
        }
    }
  };

  // ... (rest of Drag and Drop helpers same as before) ...
  const getParentId = (nodes: SequenceNode[], nodeId: string, parentId: string = 'root'): string | null => {
      for (const node of nodes) {
          if (node.id === nodeId) return parentId;
          if (node.children && node.children.length > 0) {
              const found = getParentId(node.children, nodeId, node.id);
              if (found) return found;
          }
      }
      return null;
  };

  const findNode = (nodes: SequenceNode[], id: string): SequenceNode | null => {
    for (const node of nodes) {
        if (node.id === id) return node;
        const found = findNode(node.children, id);
        if (found) return found;
    }
    return null;
  }

  const handleDragStart = (event: DragStartEvent) => {
    const { active } = event;
    const type = active.data.current?.type;
    if (type === 'SOURCE_ABILITY') setActiveDragItem(active.data.current);
    else if (type === 'NODE') setActiveNode(active.data.current?.node);
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveDragItem(null);
    setActiveNode(null);

    if (!over) return;

    if (active.data.current?.type === 'SOURCE_ABILITY') {
        const { charId, abilityId } = active.data.current;
        const newNode: SequenceNode = {
            id: `node-${Date.now()}`,
            type: 'action',
            data: { charId, abilityId, weaponId: '' },
            children: []
        };

        let targetParentId = 'root';
        const overData = over.data.current || {};

        if (over.id === 'root-canvas') {
            targetParentId = 'root';
        } else if (overData.type === 'CONTAINER') {
            targetParentId = overData.nodeId;
        } else if (overData.type === 'NODE') {
             targetParentId = getParentId(tree, over.id as string) || 'root';
        }

        if (targetParentId !== 'root') {
            const container = findNode(tree, targetParentId);
            if (container && container.type === 'combo' && container.children.length >= 2) {
                return; 
            }
        }

        setTree(prev => {
             if (targetParentId === 'root') return [...prev, newNode];
             return addNodeToContainer(prev, targetParentId, newNode);
        });
        return;
    }

    if (active.data.current?.type === 'NODE') {
        const activeId = active.id as string;
        const activeParentId = getParentId(tree, activeId) || 'root';

        if (!activeId) return;

        let targetParentId = 'root';
        const overId = over.id as string;
        const overData = over.data.current || {};

        if (over.id === 'root-canvas') {
            targetParentId = 'root';
        } else if (overData.type === 'CONTAINER') {
            targetParentId = overData.nodeId;
        } else if (overData.type === 'NODE') {
             targetParentId = getParentId(tree, overId) || 'root';
        }

        if (activeId === overId) return;

        if (targetParentId !== activeParentId && targetParentId !== 'root') {
             const container = findNode(tree, targetParentId);
             if (container && container.type === 'combo' && container.children.length >= 2) {
                 return;
             }
        }

        setTree(items => {
             if (activeParentId === targetParentId) {
                  if (activeParentId === 'root') {
                      const oldIdx = items.findIndex(n => n.id === activeId);
                      const newIdx = items.findIndex(n => n.id === overId);
                      if (oldIdx !== -1 && newIdx !== -1) {
                        return arrayMove(items, oldIdx, newIdx);
                      }
                      return items;
                  } else {
                      return recursiveSort(items, activeId, overId); 
                  }
             }
             return moveNodeBetweenParents(items, activeId, activeParentId, targetParentId, overId);
        });
    }
  };

  const moveNodeBetweenParents = (nodes: SequenceNode[], nodeId: string, sourceParentId: string, targetParentId: string, overId: string): SequenceNode[] => {
      let nodeToMove: SequenceNode | null = null;
      const removeNode = (list: SequenceNode[]): SequenceNode[] => {
          const newList = [];
          for (const item of list) {
              if (item.id === nodeId) {
                  nodeToMove = item;
                  continue;
              }
              if (item.children.length > 0) {
                  const newChildren = removeNode(item.children);
                  if (newChildren !== item.children) {
                      newList.push({ ...item, children: newChildren });
                      continue;
                  }
              }
              newList.push(item);
          }
          return newList;
      };
      const treeWithoutNode = removeNode(nodes);
      if (!nodeToMove) return nodes; 
      const insertNode = (list: SequenceNode[], isRoot: boolean): SequenceNode[] => {
          if (targetParentId === 'root' && isRoot) {
              const newRoot = [...list];
              const overIndex = newRoot.findIndex(n => n.id === overId);
              if (overIndex !== -1) {
                  newRoot.splice(overIndex, 0, nodeToMove!);
              } else {
                  newRoot.push(nodeToMove!);
              }
              return newRoot;
          }
          return list.map(item => {
               if (item.id === targetParentId) {
                   const newChildren = [...item.children];
                   const overIndex = newChildren.findIndex(n => n.id === overId);
                   if (overIndex !== -1) {
                        newChildren.splice(overIndex, 0, nodeToMove!);
                   } else {
                        newChildren.push(nodeToMove!);
                   }
                   return { ...item, children: newChildren };
               }
               if (item.children.length > 0) {
                   return { ...item, children: insertNode(item.children, false) };
               }
               return item;
          });
      };
      return insertNode(treeWithoutNode, true);
  };

  const addNodeToContainer = (nodes: SequenceNode[], targetId: string, newNode: SequenceNode): SequenceNode[] => {
      return nodes.map(node => {
          if (node.id === targetId) return { ...node, children: [...node.children, newNode] };
          if (node.children.length > 0) return { ...node, children: addNodeToContainer(node.children, targetId, newNode) };
          return node;
      });
  };

  const recursiveSort = (nodes: SequenceNode[], activeId: string, overId: string): SequenceNode[] => {
     return nodes.map(node => {
         const activeIndex = node.children.findIndex(c => c.id === activeId);
         const overIndex = node.children.findIndex(c => c.id === overId);
         if (activeIndex !== -1 && overIndex !== -1) return { ...node, children: arrayMove(node.children, activeIndex, overIndex) };
         if (node.children.length > 0) return { ...node, children: recursiveSort(node.children, activeId, overId) };
         return node;
     });
  };

  const removeNode = (id: string) => {
      const recursiveFilter = (nodes: SequenceNode[]): SequenceNode[] => {
          return nodes.filter(n => n.id !== id).map(n => ({ ...n, children: recursiveFilter(n.children) }));
      };
      setTree(prev => recursiveFilter(prev));
  };

  const updateNodeData = (id: string, data: any) => {
      const recursiveUpdate = (nodes: SequenceNode[]): SequenceNode[] => {
          return nodes.map(n => {
              if (n.id === id) return { ...n, data: { ...n.data, ...data } };
              return { ...n, children: recursiveUpdate(n.children) };
          });
      };
      setTree(prev => recursiveUpdate(prev));
  };

  const addBlock = (type: 'combo' | 'condition' | 'divider') => {
      if (type === 'condition') {
          const initialCondition: SequenceNode = {
            id: `cond-${Date.now()}`,
            type: 'condition',
            data: {},
            children: []
          };
          const chainNode: SequenceNode = {
              id: `chain-${Date.now()}`,
              type: 'logic_chain',
              children: [initialCondition]
          };
          setTree(prev => [...prev, chainNode]);
      } else {
          const newNode: SequenceNode = {
              id: `block-${Date.now()}`,
              type,
              data: {},
              children: []
          };
          setTree(prev => [...prev, newNode]);
      }
  };

  const handleAddLogicSibling = (nodeId: string) => {
      const newSibling: SequenceNode = {
          id: `cond-${Date.now()}`,
          type: 'condition',
          data: {},
          children: []
      };
      const recursiveAdd = (nodes: SequenceNode[]): SequenceNode[] => {
          return nodes.map(node => {
              if (node.type === 'logic_chain') {
                  const childExists = node.children.some(c => c.id === nodeId);
                  if (childExists) {
                      return { ...node, children: [...node.children, newSibling] };
                  }
              }
              if (node.children.length > 0) {
                  return { ...node, children: recursiveAdd(node.children) };
              }
              return node;
          });
      };
      setTree(prev => recursiveAdd(prev));
  };

  const updateLog = (newLogs: LogEntry[]) => {
      setLogs(newLogs);
  };

  return (
    <DndContext 
        sensors={sensors}
        collisionDetection={pointerWithin}
        onDragStart={handleDragStart} 
        onDragEnd={handleDragEnd}
    >
        <Modal 
            isOpen={activeModal === 'CHAR_SELECT'} 
            onClose={closeModal} 
            title="Добавить участника"
        >
            <div className="flex flex-col gap-3 mb-4">
                <div className="relative group">
                    <input 
                        type="text" 
                        placeholder="ПОИСК ПО ИМЕНИ..." 
                        value={charSearchTerm}
                        onChange={(e) => setCharSearchTerm(e.target.value)}
                        className="w-full bg-input border border-violet-900/40 rounded pl-9 pr-2 py-2 text-sm text-white focus:border-violet-500 focus:shadow-glow outline-none transition-all placeholder-slate-600 font-sans"
                    />
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-violet-400" />
                </div>
                <div className="flex gap-2">
                    <div className="flex-1 relative group">
                        <Filter size={14} className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none group-focus-within:text-violet-400"/>
                        <select
                            value={selectedFaction}
                            onChange={(e) => {
                                setSelectedFaction(e.target.value);
                                setSelectedVolume('All');
                            }}
                            className="w-full bg-input border border-violet-900/40 rounded pl-8 pr-2 py-1.5 text-xs text-white appearance-none outline-none focus:border-violet-500 focus:shadow-glow transition-all"
                        >
                            <option value="All">ВСЕ ФРАКЦИИ</option>
                            {uniqueFactions.map(f => (
                                <option key={f} value={f}>{f.toUpperCase()}</option>
                            ))}
                        </select>
                    </div>
                    {['NPC', 'НПС', 'Бестиарий'].includes(selectedFaction) && (
                         <div className="flex-1 relative animate-in fade-in slide-in-from-left-2 duration-300 group">
                             <Filter size={14} className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none group-focus-within:text-violet-400"/>
                             <select
                                 value={selectedVolume}
                                 onChange={(e) => setSelectedVolume(e.target.value)}
                                 className="w-full bg-input border border-violet-900/40 rounded pl-8 pr-2 py-1.5 text-xs text-white appearance-none outline-none focus:border-violet-500 focus:shadow-glow transition-all"
                             >
                                 <option value="All">ВСЕ ТОМА</option>
                                 {uniqueVolumes.map(v => (
                                     <option key={v} value={v}>{v.toUpperCase()}</option>
                                 ))}
                             </select>
                         </div>
                    )}
                </div>
            </div>
            {filteredCharacters.length === 0 ? (
                <div className="text-slate-500 italic text-center py-8 font-rune">Персонажи не найдены</div>
            ) : (
                <div className="space-y-2 max-h-64 overflow-y-auto pr-1">
                    {filteredCharacters.map(c => (
                        <button 
                            key={c.id} 
                            onClick={() => addParticipant(c)} 
                            className={`w-full text-left p-3 rounded border flex justify-between items-center transition-all duration-300 hover:shadow-glow ${getCharacterStyle(c.profile.faction)}`}
                        >
                            <div>
                                <div className="font-bold font-rune">{c.profile.name}</div>
                                <div className="text-[10px] flex gap-2 mt-0.5">
                                   <span className="font-bold tracking-wide uppercase opacity-90">{c.profile.faction}</span>
                                   {['NPC', 'НПС', 'Бестиарий'].includes(c.profile.faction) && c.profile.npc_volume && (
                                       <span className="font-bold text-yellow-100 opacity-90 border-l border-white/20 pl-2">
                                           {c.profile.npc_volume}
                                       </span>
                                   )}
                                </div>
                            </div>
                            <div className="text-right opacity-80">
                                <div className="text-xs font-mono">STR: {c.stats.phys}</div>
                                <div className="text-[10px] font-mono">LVL {c.profile.level}</div>
                            </div>
                        </button>
                    ))}
                </div>
            )}
            <div className="mt-2 text-[10px] text-slate-600 text-center font-mono">
                Найдено: {filteredCharacters.length} / {allCharacters.length}
            </div>
        </Modal>

        {/* ... Other modals ... */}
        <Modal
            isOpen={activeModal === 'BATTLE_LIST'}
            onClose={closeModal}
            title={isAdmin ? "Архив Боев (БД)" : "Локальные Сохранения"}
            footer={
                <button onClick={handleCreateBattleClick} className="w-full py-2 bg-violet-900/50 border border-violet-500/50 text-white rounded font-bold hover:bg-violet-800 hover:shadow-glow transition-all uppercase font-rune tracking-widest">
                    Создать новую симуляцию
                </button>
            }
        >
            <div className="space-y-2 max-h-64 overflow-y-auto">
                {savedBattles.length === 0 && <div className="text-center text-slate-500 py-4 italic">Нет сохраненных боев</div>}
                {savedBattles.map(b => (
                    <div key={b.id} className="w-full flex items-center justify-between p-3 bg-panel hover:bg-slate-900 border border-violet-900/30 hover:border-violet-500/50 rounded group mb-2 transition-all">
                        <button onClick={() => loadBattle(b.id)} className="flex-1 text-left flex justify-between items-center">
                            <div className="text-violet-100 font-bold font-rune flex items-center gap-2">
                                {b.name || 'Бой без названия'}
                                {!isAdmin && <span title="Локально"><HardDrive size={12} className="text-slate-500" /></span>}
                                {isAdmin && <span title="В облаке"><Cloud size={12} className="text-emerald-500" /></span>}
                            </div>
                            <span className={`text-[10px] px-2 py-0.5 rounded uppercase font-bold mr-2 tracking-wider ${b.status === 'active' ? 'bg-emerald-900/40 text-emerald-400 border border-emerald-800' : b.status === 'finished' ? 'bg-red-900/40 text-red-400 border border-red-800' : 'bg-slate-800 text-slate-400 border border-slate-700'}`}>{getStatusLabel(b.status)}</span>
                        </button>
                        <button onClick={(e) => handleDeleteBattle(b.id, e)} className="p-2 text-slate-500 hover:text-red-400 hover:bg-red-900/10 rounded transition-colors" title="Удалить бой">
                            <Trash2 size={16} />
                        </button>
                    </div>
                ))}
            </div>
        </Modal>

        <Modal isOpen={activeModal === 'CONFIRM_DELETE'} onClose={cancelDelete} title="Подтверждение Удаления" footer={<><button onClick={cancelDelete} className="px-4 py-2 text-slate-400 hover:text-white font-rune uppercase">Отмена</button><button onClick={confirmDeleteBattle} className="px-4 py-2 bg-red-900/50 border border-red-500/50 text-white rounded hover:bg-red-800 hover:shadow-glow-red font-bold font-rune uppercase">Уничтожить данные</button></>}>
            <p className="text-red-300 font-sans">
                {isAdmin ? "Вы инициировали протокол удаления. Данные боевой симуляции будут утрачены из БД безвозвратно. Подтвердить?" : "Удалить локальное сохранение этого боя? Восстановить будет невозможно."}
            </p>
        </Modal>

        <Modal isOpen={activeModal === 'CREATE_BATTLE'} onClose={closeModal} title="Новая Симуляция" footer={<button onClick={confirmCreateBattle} className="px-4 py-2 bg-violet-900/50 border border-violet-500/50 text-white rounded hover:bg-violet-800 hover:shadow-glow font-bold font-rune uppercase">Инициализация</button>}>
            <div className="flex flex-col gap-2">
                <label className="text-sm text-slate-400 font-rune uppercase tracking-wider">Кодовое название</label>
                <input type="text" value={modalInput} onChange={(e) => setModalInput(e.target.value)} placeholder="Напр. Инцидент Омега-7" className="bg-input border border-violet-900/40 p-2 rounded text-white focus:border-violet-500 focus:shadow-glow outline-none transition-all font-sans" autoFocus />
            </div>
        </Modal>

        <Modal isOpen={activeModal === 'CONFIRM_SAVE'} onClose={closeModal} title="Сохранение Данных" footer={<><button onClick={closeModal} className="px-4 py-2 text-slate-400 hover:text-white font-rune uppercase">Отмена</button><button onClick={pendingAction} className="px-4 py-2 bg-emerald-900/50 border border-emerald-500/50 text-white rounded hover:bg-emerald-800 hover:shadow-glow font-bold font-rune uppercase">Понятно</button></>}>
            <p className="font-sans">Текущая симуляция не сохранена. Пожалуйста, используйте кнопку создания для инициализации.</p>
        </Modal>

        <Modal isOpen={activeModal === 'CONFIRM_END'} onClose={closeModal} title="Завершение Протокола" footer={<><button onClick={closeModal} className="px-4 py-2 text-slate-400 hover:text-white font-rune uppercase">Отмена</button><button onClick={confirmEndBattle} className="px-4 py-2 bg-red-900/50 border border-red-500/50 text-white rounded hover:bg-red-800 hover:shadow-glow-red font-bold font-rune uppercase">Завершить Симуляцию</button></>}>
            <p className="text-red-400 font-sans">Внимание: Статус боя будет изменен на ЗАВЕРШЕН. Редактирование будет ограничено.</p>
        </Modal>

        <Modal isOpen={activeModal === 'FINALIZE_BATTLE'} onClose={closeModal} title="Финализация и Травмы" footer={<><button onClick={closeModal} className="px-4 py-2 text-slate-400 hover:text-white font-rune uppercase">Отмена</button><button onClick={finalizeBattle} className="px-4 py-2 bg-red-900/50 border border-red-500/50 text-white rounded hover:bg-red-800 hover:shadow-glow-red font-bold font-rune uppercase">{loading ? 'Обработка...' : 'Применить Последствия'}</button></>}>
            <div className="space-y-4 font-sans">
                <p className="text-sm text-slate-300">
                    {isAdmin 
                     ? "Симуляция завершена. Отметьте субъектов, чьи повреждения должны быть перманентно сохранены в БД." 
                     : "Симуляция завершена. Внимание: Вы не администратор, травмы НЕ будут записаны в базу данных персонажей."}
                </p>
                {isAdmin && (
                    <div className="bg-input border border-violet-900/30 rounded p-2 max-h-60 overflow-y-auto">
                        {participants.filter(p => p.medcard.injuries.length > 0).length === 0 ? (<div className="text-slate-500 italic text-center p-2">Нет критических повреждений для регистрации.</div>) : (participants.filter(p => p.medcard.injuries.length > 0).map(p => (<div key={p.instance_id} className={`flex items-center justify-between p-2 rounded mb-1 cursor-pointer border transition-all ${participantsToSave.has(p.instance_id) ? 'bg-red-900/20 border-red-500/50 shadow-glow-red' : 'bg-panel border-violet-900/20 opacity-60'}`} onClick={() => handleToggleSaveParticipant(p.instance_id)}><div className="flex items-center gap-2"><div className={`w-4 h-4 rounded border flex items-center justify-center ${participantsToSave.has(p.instance_id) ? 'bg-red-600 border-red-400' : 'border-slate-600'}`}>{participantsToSave.has(p.instance_id) && <span className="text-white text-xs font-bold">✓</span>}</div><span className="font-bold text-sm font-rune">{p.profile.name}</span></div><div className="text-xs text-red-300 font-mono">{p.medcard.injuries.length} РАН</div></div>)))}
                    </div>
                )}
            </div>
        </Modal>

        <Modal isOpen={activeModal === 'ALERT'} onClose={closeModal} title="Системное Сообщение" footer={<button onClick={closeModal} className="px-4 py-2 bg-slate-800 text-white rounded hover:bg-slate-700 font-rune uppercase">Принято</button>}>
            <p className="font-sans">{alertMessage}</p>
        </Modal>

        <div className="min-h-screen bg-slate-950 text-slate-300 font-sans p-4 flex flex-col">
            {/* Header / Top Bar */}
            <header className="mb-4 flex items-center justify-between bg-panel p-4 rounded-lg border border-violet-900/30 shadow-lg relative overflow-hidden group shrink-0">
                <div className="absolute inset-0 bg-gradient-to-r from-violet-900/10 to-transparent opacity-50 pointer-events-none"></div>

                <div className="flex items-center gap-4 relative z-10">
                     <button onClick={() => setActiveModal('BATTLE_LIST')} className="p-2 bg-slate-900 hover:bg-violet-900/40 rounded border border-violet-900/50 text-violet-300 hover:text-white transition-all hover:shadow-glow" title="Архив">
                         <List size={18} />
                     </button>
                     <button onClick={handleSaveBattle} className="p-2 bg-slate-900 hover:bg-emerald-900/40 rounded border border-violet-900/50 text-violet-300 hover:text-emerald-300 hover:border-emerald-500/50 transition-all hover:shadow-glow" title="Сохранить">
                         <Save size={18} />
                     </button>
                     <div>
                         <input 
                            value={battleName} 
                            onChange={(e) => updateBattleName(e.target.value)}
                            className="bg-transparent text-xl font-bold font-rune text-transparent bg-clip-text bg-gradient-to-r from-violet-200 to-fuchsia-200 outline-none border-b border-transparent hover:border-violet-500/50 focus:border-violet-500 transition-all w-64 uppercase tracking-widest placeholder-violet-900"
                         />
                         <div className="text-xs text-slate-500 flex items-center gap-2 font-mono mt-1">
                            <span>СТАТУС:</span>
                            <span className={`uppercase font-bold tracking-wider ${status === 'active' ? 'text-emerald-400 shadow-emerald-500/20 drop-shadow-sm' : status === 'finished' ? 'text-red-500' : 'text-amber-400'}`}>
                                {getStatusLabel(status)}
                            </span>
                            {!isAdmin && <span className="ml-2 text-[10px] bg-slate-800 px-2 py-0.5 rounded text-slate-400 border border-slate-700">Локальный режим</span>}
                         </div>
                     </div>
                </div>

                <div className="flex items-center gap-6 relative z-10">
                     <div className="text-right mr-4">
                        <div className="text-[10px] text-violet-400 uppercase tracking-[0.2em] font-bold">Раунд</div>
                        <div className="font-bold text-3xl font-rune text-white drop-shadow-md">{round}</div>
                     </div>

                     {status !== 'finished' && (
                         <>
                            <button 
                                onClick={handleNextRound}
                                className="flex items-center gap-2 bg-slate-900 hover:bg-emerald-900/30 text-emerald-400 border border-emerald-900/50 hover:border-emerald-500/50 px-5 py-2 rounded-sm font-bold font-rune uppercase text-xs tracking-widest transition-all hover:shadow-glow"
                            >
                                <Play size={14} fill="currentColor" /> {round === 0 ? "НАЧАТЬ БОЙ" : "След. Раунд"}
                            </button>
                            <button 
                                onClick={handleEndBattleClick}
                                className="flex items-center gap-2 bg-slate-900 hover:bg-red-900/30 text-red-400 border border-red-900/50 hover:border-red-500/50 px-5 py-2 rounded-sm font-bold font-rune uppercase text-xs tracking-widest transition-all hover:shadow-glow-red"
                            >
                                <Square size={14} fill="currentColor" /> Завершить
                            </button>
                         </>
                     )}
                </div>
            </header>

            <main className="flex-1 grid grid-cols-1 md:grid-cols-12 gap-4">
                {/* LEFT PANEL: Participants */}
                <div className="col-span-12 md:col-span-3 overflow-y-auto pr-1 flex flex-col max-h-[80vh]">
                     <div className="flex items-center justify-between mb-3 px-1 border-b border-violet-900/30 pb-2 shrink-0">
                        <h2 className="text-xs font-bold text-violet-400 uppercase tracking-widest font-rune">Участники</h2>
                        <button onClick={() => setActiveModal('CHAR_SELECT')} className="text-violet-400 hover:text-white transition-all">
                            <UserPlus size={18} />
                        </button>
                     </div>
                     <SourcePanel 
                        participants={participants} 
                        onToggleEquip={handleToggleEquip}
                        onRemoveParticipant={handleRemoveParticipant}
                        onAddInjury={handleAddInjury}
                        onRemoveInjury={handleRemoveInjury}
                        onAddDebuff={handleAddDebuff}
                        onRemoveEffect={handleRemoveEffect}
                        onRemoveCooldown={handleRemoveCooldown}
                     />
                </div>

                {/* CENTER PANEL: Canvas */}
                <div className="col-span-12 md:col-span-6 flex flex-col gap-3 min-h-[600px]">
                     <div className="flex-1 relative border border-violet-900/20 rounded bg-black/20">
                         {/* Canvas Decoration */}
                         <div className="absolute top-0 left-0 w-4 h-4 border-t border-l border-violet-800/30 pointer-events-none"></div>
                         <div className="absolute top-0 right-0 w-4 h-4 border-t border-r border-violet-800/30 pointer-events-none"></div>

                         <SequenceCanvas 
                            tree={tree}
                            participants={participants}
                            onRemove={removeNode}
                            onUpdateData={updateNodeData}
                            onAddCombo={() => addBlock('combo')}
                            onAddCondition={() => addBlock('condition')}
                            onAddDivider={() => addBlock('divider')}
                            onClear={() => setTree([])}
                            onAddLogicSibling={handleAddLogicSibling}
                         />
                    </div>
                    <button 
                        onClick={handleCommit}
                        className={`
                            w-full font-bold py-3 rounded shadow-lg uppercase tracking-[0.2em] font-rune transition-all flex items-center justify-center gap-2 border shrink-0
                            ${tree.length === 0 
                                ? 'bg-slate-900 border-slate-800 text-slate-600 hover:bg-slate-800' 
                                : 'bg-violet-900/60 border-violet-500/50 hover:bg-violet-800 text-white hover:shadow-glow'
                            }
                        `}
                    >
                        <RefreshCw size={18} className={tree.length > 0 ? "animate-spin-slow" : ""} /> Выполнить
                    </button>
                </div>

                {/* RIGHT PANEL: Logs */}
                <div className="col-span-12 md:col-span-3 min-h-[600px]">
                     <BattleLog 
                        logs={logs} 
                        currentRound={round} 
                        participants={participants}
                        onUpdateLogs={updateLog}
                        onUpdateParticipant={handleUpdateParticipant}
                        onRollback={handleRollback}
                     />
                </div>
            </main>
        </div>

        <DragOverlay>
            {activeDragItem && activeDragItem.type === 'SOURCE_ABILITY' ? (
                <div className="bg-violet-900/90 border border-violet-400 text-white px-3 py-1.5 rounded shadow-glow opacity-90 cursor-grabbing font-bold text-sm font-rune tracking-wide backdrop-blur-sm">
                   + Бросить способность
                </div>
            ) : null}
            {activeNode ? (
                 <div className="bg-panel border border-violet-500 rounded p-2 shadow-2xl opacity-80 rotate-2 w-48 backdrop-blur-md">
                    <div className="h-4 bg-violet-900/50 rounded w-3/4 mb-2 animate-pulse"></div>
                 </div>
            ) : null}
        </DragOverlay>
    </DndContext>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { LogEntry, BattleParticipant } from '../types';
import { ChevronLeft, ChevronRight, Clipboard, Save, BarChart3, ScrollText, ListEnd, RotateCcw } from 'lucide-react';
import { generateSummary, generateStatsText } from '../engine/formatters';

interface Props {
  logs: LogEntry[];
  currentRound: number;
  participants: BattleParticipant[];
  onUpdateLogs: (logs: LogEntry[]) => void;
  onUpdateParticipant?: (id: string, updates: any) => void;
  onRollback?: (round: number) => void;
}

// Tabs
type Tab = 'stats' | 'log' | 'summary';

const BattleLog: React.FC<Props> = ({ logs, currentRound, participants, onUpdateLogs, onUpdateParticipant, onRollback }) => {
  const [activeTab, setActiveTab] = useState<Tab>('log'); 
  const [viewRound, setViewRound] = useState(currentRound);

  // Text Areas State
  const [summaryText, setSummaryText] = useState("");
  const [localLogText, setLocalLogText] = useState("");
  const [localStatsText, setLocalStatsText] = useState("");

  const [isDirty, setIsDirty] = useState(false);

  useEffect(() => {
      setViewRound(currentRound);
  }, [currentRound]);

  // Sync Data on Round Change or Mount
  useEffect(() => {
      // 1. LOG TEXT
      const roundEntries = logs.filter(l => l.round === viewRound && l.type !== 'system');
      const joinedText = roundEntries.map(l => l.text_formatted).join('\n');
      setLocalLogText(joinedText);

      // 2. FIND SNAPSHOT
      const snapshotLog = logs.find(l => l.round === viewRound && l.details?.participants_snapshot);

      // 3. SUMMARY
      const allEntriesForRound = logs.filter(l => l.round === viewRound);
      const entryWithSummary = allEntriesForRound.reverse().find(l => l.summary !== undefined && l.summary !== null && l.type !== 'system');

      if (entryWithSummary) {
          setSummaryText(entryWithSummary.summary || "");
      } else if (snapshotLog && snapshotLog.summary) {
          setSummaryText(snapshotLog.summary);
      } else {
          if (viewRound === currentRound) {
              setSummaryText(generateSummary(participants, currentRound));
          } else {
              setSummaryText("(Нет сохраненного итога)"); 
          }
      }

      // 4. STATS
      if (!isDirty) {
          if (viewRound === currentRound) {
              setLocalStatsText(generateStatsText(participants));
          } else if (snapshotLog && snapshotLog.details?.stats_snapshot) {
              setLocalStatsText(snapshotLog.details.stats_snapshot);
          } else {
              setLocalStatsText("(Нет сохраненных характеристик)");
          }
      }

      setIsDirty(false);
  }, [viewRound, logs, participants, currentRound]); 

  const handleTextChange = (setter: React.Dispatch<React.SetStateAction<string>>) => (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      setter(e.target.value);
      setIsDirty(true);
  };

  const parseAndSaveStats = () => {
      if (!onUpdateParticipant) return;

      const blocks = localStatsText.split(/\n\s*\n/);

      blocks.forEach(block => {
          const lines = block.split('\n').map(l => l.trim()).filter(l => l);
          if (lines.length === 0) return;

          const headerMatch = lines[0].match(/^(.+)\s\(\d+\s*ур\.\)$/i);
          const name = headerMatch ? headerMatch[1].trim() : lines[0].trim();

          const participant = participants.find(p => p.profile.name === name);
          if (participant) {
              const newStats = { ...participant.stats };

              lines.forEach(line => {
                  const lower = line.toLowerCase();
                  const matchVal = line.match(/:\s*(-?\d+)/);

                  if (matchVal) {
                      const val = parseInt(matchVal[1]);
                      if (!isNaN(val)) {
                          if (lower.startsWith('физ')) newStats.phys = val;
                          else if (lower.startsWith('маг')) newStats.magic = val;
                          else if (lower.startsWith('уник')) newStats.unique = val;
                      }
                  }
              });

              onUpdateParticipant(participant.instance_id, { stats: newStats });
          }
      });
  };

  const saveChanges = () => {
      const otherRoundLogs = logs.filter(l => l.round !== viewRound);
      const systemLogs = logs.filter(l => l.round === viewRound && l.type === 'system'); 

      const newEntry: LogEntry = {
          id: `edited-${viewRound}-${Date.now()}`,
          round: viewRound,
          timestamp: new Date().toISOString(),
          type: 'action',
          text_formatted: localLogText,
          summary: summaryText 
      };

      const newLogs = [...otherRoundLogs, ...systemLogs];
      if (localLogText.trim()) {
          newLogs.push(newEntry);
      }

      newLogs.sort((a, b) => {
           if (a.round !== b.round) return a.round - b.round;
           return 0; 
      });

      onUpdateLogs(newLogs);

      if (activeTab === 'stats') {
          parseAndSaveStats();
      }

      setIsDirty(false);
  };

  const canRollback = viewRound < currentRound && logs.some(l => l.round === viewRound && l.details?.participants_snapshot);

  const getLineColor = (line: string) => {
      const trim = line.trim();
      if (trim.includes('НАЧАЛО РАУНДА') || trim.includes('ЗАВЕРШЕНИЕ')) {
          return 'bg-violet-500 shadow-[0_0_8px_#8b5cf6] h-1.5 w-4 rounded-sm';
      } else if (trim.startsWith('> (') || (trim.startsWith('>') && trim.includes(')'))) {
          // Buff / Passive (Using new format with parens)
          return 'bg-emerald-500 shadow-[0_0_5px_#10b981] h-3 w-1 rounded-full';
      } else if (trim.startsWith('> [')) {
          // Combo
          return 'bg-blue-500 shadow-[0_0_5px_#3b82f6] h-3 w-1 rounded-full';
      } else if (trim.startsWith('>')) {
          // Attack (Standard)
          return 'bg-amber-600 shadow-[0_0_5px_#d97706] h-3 w-1 rounded-full';
      }
      return 'bg-transparent';
  };

  return (
    <div className="h-full flex flex-col bg-panel rounded-lg shadow-xl border border-violet-900/30 overflow-hidden">

      {/* 1. TABS HEADER */}
      <div className="flex border-b border-violet-900/30 bg-[#020408]">
          <button 
            onClick={() => setActiveTab('stats')}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-all ${activeTab === 'stats' ? 'bg-violet-900/20 text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-white'}`}
          >
              <BarChart3 size={14} /> Характеристики
          </button>
          <button 
            onClick={() => setActiveTab('log')}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-all ${activeTab === 'log' ? 'bg-violet-900/20 text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-white'}`}
          >
              <ScrollText size={14} /> Лог
          </button>
          <button 
            onClick={() => setActiveTab('summary')}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-all ${activeTab === 'summary' ? 'bg-violet-900/20 text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-white'}`}
          >
              <ListEnd size={14} /> Итог
          </button>
      </div>

      {/* 2. ROUND CONTROLS */}
      <div className="bg-[#050b14] border-b border-violet-900/20 p-2 flex items-center justify-between text-xs">
          <div className="flex items-center gap-2">
              <button 
                onClick={() => setViewRound(Math.max(0, viewRound - 1))}
                disabled={viewRound <= 0}
                className="p-1 hover:bg-slate-800 rounded disabled:opacity-30 text-slate-400 hover:text-white"
              >
                  <ChevronLeft size={16} />
              </button>
              <span className="font-bold text-violet-400 uppercase font-rune tracking-widest">{viewRound === 0 ? "Подготовка" : `Раунд ${viewRound}`}</span>
              <button 
                onClick={() => setViewRound(Math.min(currentRound, viewRound + 1))}
                disabled={viewRound >= currentRound}
                className="p-1 hover:bg-slate-800 rounded disabled:opacity-30 text-slate-400 hover:text-white"
              >
                  <ChevronRight size={16} />
              </button>
          </div>
          <div className="flex items-center gap-2">
              {canRollback && onRollback && (
                  <button 
                    onClick={() => onRollback(viewRound)}
                    className="flex items-center gap-1 bg-red-900/20 hover:bg-red-900/40 text-red-400 border border-red-900/50 rounded px-2 py-1 text-[10px] uppercase font-bold transition-all mr-2"
                    title="Вернуться к состоянию на конец этого раунда"
                  >
                      <RotateCcw size={10} /> Переиграть сл.
                  </button>
              )}

              {isDirty && (
                  <button 
                    onClick={saveChanges}
                    className="flex items-center gap-1 text-emerald-400 hover:text-emerald-300 font-bold animate-pulse uppercase text-[10px] tracking-wider"
                  >
                      <Save size={12} /> Сохранить
                  </button>
              )}
          </div>
      </div>

      {/* 3. CONTENT AREA */}
      <div className="flex-1 bg-[#020408] relative overflow-hidden flex flex-col">

         {activeTab === 'stats' && (
             <div className="h-full flex flex-col">
                 <textarea 
                    className="flex-1 bg-[#020408] text-slate-300 p-4 outline-none resize-none font-mono text-xs leading-relaxed selection:bg-violet-900/50"
                    value={localStatsText}
                    onChange={handleTextChange(setLocalStatsText)}
                    spellCheck={false}
                    placeholder="Данные участников..."
                 />
             </div>
         )}

         {activeTab === 'log' && (
             <div className="h-full flex flex-col overflow-auto custom-scrollbar relative pl-2">
                 <div className="relative w-full min-h-full">
                     {/* Backdrop for Markers (Transparent Text) */}
                     <div 
                        className="absolute inset-0 p-4 font-mono text-xs leading-6 whitespace-pre-wrap break-words pointer-events-none text-transparent"
                        aria-hidden="true"
                     >
                        {localLogText.split('\n').map((line, i) => (
                            <div key={i} className="relative">
                                {/* The Marker - Positioned absolutely relative to the line */}
                                <div className={`absolute -left-3 top-1.5 transition-all duration-300 ${getLineColor(line)}`}></div>
                                {line || ' '} 
                            </div>
                        ))}
                     </div>

                     {/* Actual Editable Textarea */}
                     <textarea 
                        className="relative z-10 w-full h-full bg-transparent text-slate-300 p-4 font-mono text-xs leading-6 whitespace-pre-wrap break-words outline-none resize-none selection:bg-violet-900/50 placeholder-slate-700 overflow-hidden"
                        value={localLogText}
                        onChange={handleTextChange(setLocalLogText)}
                        spellCheck={false}
                        placeholder="Лог раунда пуст..."
                        // We set height auto to allow the container to scroll, assuming minimal height is satisfied by content
                        style={{ minHeight: '100%' }}
                     />
                 </div>
             </div>
         )}

         {activeTab === 'summary' && (
             <div className="h-full flex flex-col">
                 <div className="p-2 bg-violet-900/10 text-[10px] text-slate-500 uppercase tracking-widest border-b border-violet-900/20 flex justify-between items-center">
                     <span>Сводка (Раунд {viewRound})</span>
                     <button onClick={() => navigator.clipboard.writeText(summaryText)} title="Копировать" className="hover:text-white"><Clipboard size={12}/></button>
                 </div>
                 <textarea 
                    className="flex-1 bg-[#020408] text-slate-300 p-4 text-xs font-mono outline-none resize-none selection:bg-emerald-900/50"
                    value={summaryText}
                    onChange={handleTextChange(setSummaryText)}
                    placeholder={viewRound < currentRound && !summaryText ? "(Нет сохраненного итога)" : "Здесь будет сводка раунда..."}
                    spellCheck={false}
                 />
             </div>
         )}
      </div>
    </div>
  );
};

export default BattleLog;

import { BattleParticipant, SequenceNode, JsonAbility, JsonItem, JsonBonus, InjuryRule } from '../types';
import { TRAUMA_DEFINITIONS } from '../constants';

interface CalculationResult {
  formattedString: string;
}

// --- CONFIGURATION ---

const DEFAULT_INJURY_RULES: InjuryRule[] = Object.entries(TRAUMA_DEFINITIONS).map(([tag, def]) => ({
    tag,
    label: def.label,
    value: def.value,
    stack: def.stack
}));

const normalizeTags = (tags: string[] = []) => tags.map(t => t.toLowerCase().trim());

const hasTagOverlap = (sourceTags: string[], targetTags: string[]): boolean => {
    if (!sourceTags || sourceTags.length === 0) return true; 
    return sourceTags.some(t => targetTags.includes(t));
};

const sumBonuses = (bonuses: JsonBonus[] = []): number => {
    return bonuses.reduce((acc, b) => acc + (Number(b.val) || 0), 0);
};

const calculateLiveStatPenalty = (
    participant: BattleParticipant, 
    statType: 'phys' | 'magic' | 'unique',
    rules: InjuryRule[]
): number => {
    if (!participant.medcard || !participant.medcard.injuries) return 0;

    let totalPenalty = 0;
    const suffix = `_${statType === 'unique' ? 'uniq' : statType}`; 

    const injuryCounts: Record<string, number> = {};
    participant.medcard.injuries.forEach(inj => {
        const tag = inj.template_id;
        if (tag.endsWith(suffix)) {
            injuryCounts[tag] = (injuryCounts[tag] || 0) + (inj.count || 1);
        }
    });

    Object.entries(injuryCounts).forEach(([tag, count]) => {
        const rule = rules.find(r => r.tag === tag);
        if (rule) {
            const penaltyValue = Number(rule.value);
            const stackSize = Number(rule.stack);

            if (stackSize > 0) {
                const stacksApplied = Math.floor(count / stackSize);
                totalPenalty += (stacksApplied * penaltyValue);
            } else {
                totalPenalty += (count * penaltyValue);
            }
        }
    });

    return totalPenalty;
};

export const getMatchingFactors = (
    participant: BattleParticipant,
    abilityTags: string[]
) => {
    const factors: { name: string, bonus: number, type: 'passive' | 'effect' | 'item', tags?: string[], desc?: string, mech?: string }[] = [];
    const normalizedAbilityTags = normalizeTags(abilityTags);

    // 1. Passives (Use FLAT list which already has inherited tags from Supabase load)
    if (participant.flat_passives) {
        participant.flat_passives.forEach(pas => {
            const isAlways = !pas.trigger || pas.trigger.toLowerCase() === 'always' || pas.trigger === 'Пассивно / Всегда';
            // We use pas.tags which now includes group tags
            if (isAlways && hasTagOverlap(normalizeTags(pas.tags), normalizedAbilityTags)) {
                factors.push({ 
                    name: pas.name, 
                    bonus: sumBonuses(pas.bonuses), 
                    type: 'passive', 
                    tags: pas.tags,
                    mech: pas.desc_mech 
                });
            }
        });
    }

    // 2. Active Effects
    if (participant.active_effects) {
        participant.active_effects.forEach(eff => {
            if (hasTagOverlap(normalizeTags(eff.tags), normalizedAbilityTags)) {
                // Try to find source ability for better description
                let mechanics = '';
                if (eff.original_ability_id) {
                    const source = participant.flat_abilities.find(a => a._id === eff.original_ability_id);
                    if (source) mechanics = source.desc_mech || '';
                }

                factors.push({ 
                    name: eff.name, 
                    bonus: sumBonuses(eff.bonuses), 
                    type: 'effect', 
                    tags: eff.tags,
                    desc: `Active effect. Duration: ${eff.duration_left} ${eff.unit}`,
                    mech: mechanics
                });
            }
        });
    }

    // 3. Wearables
    if (participant.equipment && participant.equipment.wearable) {
        participant.equipment.wearable.forEach(item => {
            if (item.is_equipped && hasTagOverlap(normalizeTags(item.tags), normalizedAbilityTags)) {
                factors.push({ 
                    name: item.name, 
                    bonus: sumBonuses(item.bonuses), 
                    type: 'item', 
                    tags: item.tags,
                    mech: item.desc_mech,
                    desc: item.desc_lore
                });
            }
        });
    }

    return factors;
};

const calculateTotalBonus = (
    participant: BattleParticipant, 
    ability: JsonAbility, 
    weapon: JsonItem | undefined,
    injuryRules: InjuryRule[],
    excludedModifiers: string[] = []
): number => {
    let total = 0;

    const usedStats = new Set<string>();
    if (ability.bonuses) {
        ability.bonuses.forEach(b => {
            const bonusVal = Number(b.val) || 0;
            if (b.stat) {
                const statKey = b.stat.toLowerCase();
                if (statKey.includes('phys') || statKey.includes('физ')) {
                    if (!usedStats.has('phys')) {
                        const base = Number(participant.stats.phys) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'phys', injuryRules));
                        usedStats.add('phys');
                    }
                } 
                if (statKey.includes('mag') || statKey.includes('маг')) {
                    if (!usedStats.has('magic')) {
                        const base = Number(participant.stats.magic) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'magic', injuryRules));
                        usedStats.add('magic');
                    }
                } 
                if (statKey.includes('uniq') || statKey.includes('уник')) {
                    if (!usedStats.has('unique')) {
                        const base = Number(participant.stats.unique) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'unique', injuryRules));
                        usedStats.add('unique');
                    }
                }
            }
            total += bonusVal;
        });
    }

    if (weapon) total += sumBonuses(weapon.bonuses);

    const externalFactors = getMatchingFactors(participant, ability.tags);
    externalFactors.forEach(f => {
        if (!excludedModifiers.includes(f.name)) {
            total += f.bonus;
        }
    });

    return total;
};


// --- TREE WALKER ---

const getDiceString = (level: number = 1): string => {
    if (level >= 5) return '3d100';
    if (level >= 3) return '2d100';
    return '1d100';
};

export const calculateSequenceTree = (
  nodes: SequenceNode[],
  participants: BattleParticipant[],
  injuryRules: InjuryRule[] = DEFAULT_INJURY_RULES 
): CalculationResult => {

  const getActionData = (charId: string, abilityId: string, weaponId?: string, excludedModifiers: string[] = []) => {
        const actor = participants.find(p => p.instance_id === charId || p.id === charId);
        if (!actor) return null;

        // Use flat_abilities which has inherited tags
        let ability = actor.flat_abilities?.find(a => a._id === abilityId);

        // Fallback search if id mismatch (rare now)
        if (!ability && actor.ability_groups) {
            for (const group of actor.ability_groups) {
                const found = group.abilities.find(a => a._id === abilityId || (a.id && a.id === abilityId) || a.name === abilityId);
                if (found) { ability = found; break; }
            }
        }

        if (!ability) return null;

        const weapon = actor.equipment.usable.find(w => w._id === weaponId || (w.id && w.id === weaponId) || w.name === weaponId);

        const bonusVal = calculateTotalBonus(actor, ability, weapon, injuryRules, excludedModifiers);
        const sign = bonusVal >= 0 ? '+' : '';
        const weaponStr = weapon && weapon.name ? ` [${weapon.name}]` : ''; // FIX: Ensure weapon.name exists
        const nameStr = `${ability.name}${weaponStr}`;
        const diceStr = getDiceString(actor.profile.level);

        const isForm = ability.tags.some(t => ['form', 'форма'].includes(t.toLowerCase()));
        const isBuff = ability.tags.some(t => ['buff', 'бафф'].includes(t.toLowerCase()));

        return { 
            name: nameStr, 
            actorName: actor.profile.name,
            bonus: `${sign}${bonusVal}`, 
            dice: diceStr, 
            isForm,
            isBuff,
            mechanics: ability.desc_mech
        };
  };

  const processNode = (node: SequenceNode): string => {
    if (node.type === 'divider') return '\n';

    // Handle Logic Chain Container
    if (node.type === 'logic_chain') {
        const childrenStr = node.children.map(c => processNode(c)).join(' | ');
        return `\n{ ${childrenStr} }`;
    }

    if (node.type === 'condition') {
      const conditionText = node.data?.conditionText || '...';
      const childStrings = node.children.map(c => processNode(c)).filter(s => s && s.trim() !== '');
      let innerContent = childStrings.join(' - ');
      return `${conditionText}: ${innerContent}`;
    }

    if (node.type === 'combo') {
      const validChildren = node.children.filter(c => c.type === 'action');
      if (validChildren.length === 0) return '';

      const dataList = validChildren.map(c => 
          getActionData(c.data?.charId || '', c.data?.abilityId || '', c.data?.weaponId, c.data?.excludedModifiers)
      ).filter(Boolean) as any[];

      if (dataList.length === 0) return '';

      // If ANY action in combo is a normal attack, show bonuses. 
      // If all are utility (Buff/Form), behave like utility but in combo block?
      // Standard format: [Name: Ability + Name2: Ability2(Dice1/Dice2)]

      const namesPart = dataList.map(d => `${d.actorName}: ${d.name}`).join(' + ');

      // Calculate bonuses part, filtering out utility actions that don't need dice roll usually
      // But for combo, we might just list all. Let's list all for now to be safe.
      const bonusesPart = dataList.map(d => (d.isForm || d.isBuff) ? '-' : `${d.dice}${d.bonus}`).join('/');

      return `[${namesPart}(${bonusesPart})]`;
    }

    if (node.type === 'action') {
        const data = getActionData(node.data?.charId || '', node.data?.abilityId || '', node.data?.weaponId, node.data?.excludedModifiers);
        if (!data) return '[Unknown Action]';

        if (data.isForm) {
            // Form format: <Character: Name (Mechanics)>
            return `<${data.actorName}: ${data.name} (${data.mechanics || ''})>`;
        }

        if (data.isBuff) {
            // Buff format: (Character: Name (Mechanics))
            return `(${data.actorName}: ${data.name} (${data.mechanics || ''}))`;
        }

        // Attack format: Character: Name(Dice+Bonus)
        return `${data.actorName}: ${data.name}(${data.dice}${data.bonus})`;
    }

    return '';
  };

  const parts = nodes.map(n => processNode(n)).filter(Boolean);

  let finalString = '';

  parts.forEach((part, index) => {
      const cleanPart = part.trimEnd();

      if (index === 0) {
          if (cleanPart.startsWith('\n')) {
              finalString += '> ' + cleanPart.trimStart(); 
          } else {
              finalString += '> ' + cleanPart;
          }
      } else {
          if (finalString.endsWith('\n') || cleanPart.startsWith('\n')) {
              if (cleanPart.startsWith('\n')) {
                  finalString += '\n> ' + cleanPart.trimStart();
              } else {
                  finalString += '> ' + cleanPart; 
              }
          } else {
               finalString += ' - ' + cleanPart;
          }
      }
  });

  return { formattedString: finalString };
};

import React, { useState, useEffect } from 'react';
import { LogEntry, BattleParticipant } from '../types';
import { ChevronLeft, ChevronRight, Clipboard, Save, BarChart3, ScrollText, ListEnd, RotateCcw } from 'lucide-react';
import { generateSummary, generateStatsText } from '../engine/formatters';

interface Props {
  logs: LogEntry[];
  currentRound: number;
  participants: BattleParticipant[];
  onUpdateLogs: (logs: LogEntry[]) => void;
  onUpdateParticipant?: (id: string, updates: any) => void;
  onRollback?: (round: number) => void;
}

// Tabs
type Tab = 'stats' | 'log' | 'summary';

const BattleLog: React.FC<Props> = ({ logs, currentRound, participants, onUpdateLogs, onUpdateParticipant, onRollback }) => {
  const [activeTab, setActiveTab] = useState<Tab>('log'); 
  const [viewRound, setViewRound] = useState(currentRound);

  // Text Areas State
  const [summaryText, setSummaryText] = useState("");
  const [localLogText, setLocalLogText] = useState("");
  const [localStatsText, setLocalStatsText] = useState("");

  const [isDirty, setIsDirty] = useState(false);

  useEffect(() => {
      setViewRound(currentRound);
  }, [currentRound]);

  // Sync Data on Round Change or Mount
  useEffect(() => {
      // 1. LOG TEXT
      const roundEntries = logs.filter(l => l.round === viewRound && l.type !== 'system');
      const joinedText = roundEntries.map(l => l.text_formatted).join('\n');
      setLocalLogText(joinedText);

      // 2. FIND SNAPSHOT
      const snapshotLog = logs.find(l => l.round === viewRound && l.details?.participants_snapshot);

      // 3. SUMMARY
      const allEntriesForRound = logs.filter(l => l.round === viewRound);
      const entryWithSummary = allEntriesForRound.reverse().find(l => l.summary !== undefined && l.summary !== null && l.type !== 'system');

      if (entryWithSummary) {
          setSummaryText(entryWithSummary.summary || "");
      } else if (snapshotLog && snapshotLog.summary) {
          setSummaryText(snapshotLog.summary);
      } else {
          if (viewRound === currentRound) {
              setSummaryText(generateSummary(participants, currentRound));
          } else {
              setSummaryText("(Нет сохраненного итога)"); 
          }
      }

      // 4. STATS
      if (!isDirty) {
          if (viewRound === currentRound) {
              setLocalStatsText(generateStatsText(participants));
          } else if (snapshotLog && snapshotLog.details?.stats_snapshot) {
              setLocalStatsText(snapshotLog.details.stats_snapshot);
          } else {
              setLocalStatsText("(Нет сохраненных характеристик)");
          }
      }

      setIsDirty(false);
  }, [viewRound, logs, participants, currentRound]); 

  const handleTextChange = (setter: React.Dispatch<React.SetStateAction<string>>) => (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      setter(e.target.value);
      setIsDirty(true);
  };

  const parseAndSaveStats = () => {
      if (!onUpdateParticipant) return;

      const blocks = localStatsText.split(/\n\s*\n/);

      blocks.forEach(block => {
          const lines = block.split('\n').map(l => l.trim()).filter(l => l);
          if (lines.length === 0) return;

          const headerMatch = lines[0].match(/^(.+)\s\(\d+\s*ур\.\)$/i);
          const name = headerMatch ? headerMatch[1].trim() : lines[0].trim();

          const participant = participants.find(p => p.profile.name === name);
          if (participant) {
              const newStats = { ...participant.stats };

              lines.forEach(line => {
                  const lower = line.toLowerCase();
                  const matchVal = line.match(/:\s*(-?\d+)/);

                  if (matchVal) {
                      const val = parseInt(matchVal[1]);
                      if (!isNaN(val)) {
                          if (lower.startsWith('физ')) newStats.phys = val;
                          else if (lower.startsWith('маг')) newStats.magic = val;
                          else if (lower.startsWith('уник')) newStats.unique = val;
                      }
                  }
              });

              onUpdateParticipant(participant.instance_id, { stats: newStats });
          }
      });
  };

  const saveChanges = () => {
      const otherRoundLogs = logs.filter(l => l.round !== viewRound);
      const systemLogs = logs.filter(l => l.round === viewRound && l.type === 'system'); 

      const newEntry: LogEntry = {
          id: `edited-${viewRound}-${Date.now()}`,
          round: viewRound,
          timestamp: new Date().toISOString(),
          type: 'action',
          text_formatted: localLogText,
          summary: summaryText 
      };

      const newLogs = [...otherRoundLogs, ...systemLogs];
      if (localLogText.trim()) {
          newLogs.push(newEntry);
      }

      newLogs.sort((a, b) => {
           if (a.round !== b.round) return a.round - b.round;
           return 0; 
      });

      onUpdateLogs(newLogs);

      if (activeTab === 'stats') {
          parseAndSaveStats();
      }

      setIsDirty(false);
  };

  const canRollback = viewRound < currentRound && logs.some(l => l.round === viewRound && l.details?.participants_snapshot);

  const getLineColor = (line: string) => {
      const trim = line.trim();

      // System (Start/End) -> Vertical Purple
      if (trim.includes('НАЧАЛО РАУНДА') || trim.includes('ЗАВЕРШЕНИЕ')) {
          return 'bg-violet-500 shadow-[0_0_8px_#8b5cf6] h-3 w-1 rounded-full';
      } 

      // Form (Gold) -> Starts with > <
      else if (trim.startsWith('> <')) {
          return 'bg-amber-400 shadow-[0_0_5px_#fbbf24] h-3 w-1 rounded-full';
      }

      // Buff (Emerald) -> Starts with > (
      else if (trim.startsWith('> (')) {
          return 'bg-emerald-500 shadow-[0_0_5px_#10b981] h-3 w-1 rounded-full';
      } 

      // Combo (Bright Blue) -> Starts with > [
      else if (trim.startsWith('> [')) {
          return 'bg-blue-500 shadow-[0_0_5px_#3b82f6] h-3 w-1 rounded-full';
      } 

      // Logic (Dark Blue) -> Starts with > { or Condition
      else if (trim.startsWith('> {') || trim.startsWith('{') || trim.includes('Condition:') || trim.includes('Если')) {
          return 'bg-indigo-500 shadow-[0_0_5px_#6366f1] h-3 w-1 rounded-full';
      } 

      // Attack (Red) -> Default > 
      else if (trim.startsWith('>')) {
          return 'bg-red-600 shadow-[0_0_5px_#dc2626] h-3 w-1 rounded-full';
      }

      return 'bg-transparent';
  };

  return (
    <div className="h-full flex flex-col bg-panel rounded-lg shadow-xl border border-violet-900/30 overflow-hidden">

      {/* 1. TABS HEADER */}
      <div className="flex border-b border-violet-900/30 bg-[#020408]">
          <button 
            onClick={() => setActiveTab('stats')}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-all ${activeTab === 'stats' ? 'bg-violet-900/20 text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-white'}`}
          >
              <BarChart3 size={14} /> Характеристики
          </button>
          <button 
            onClick={() => setActiveTab('log')}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-all ${activeTab === 'log' ? 'bg-violet-900/20 text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-white'}`}
          >
              <ScrollText size={14} /> Лог
          </button>
          <button 
            onClick={() => setActiveTab('summary')}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-all ${activeTab === 'summary' ? 'bg-violet-900/20 text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-white'}`}
          >
              <ListEnd size={14} /> Итог
          </button>
      </div>

      {/* 2. ROUND CONTROLS */}
      <div className="bg-[#050b14] border-b border-violet-900/20 p-2 flex items-center justify-between text-xs">
          <div className="flex items-center gap-2">
              <button 
                onClick={() => setViewRound(Math.max(0, viewRound - 1))}
                disabled={viewRound <= 0}
                className="p-1 hover:bg-slate-800 rounded disabled:opacity-30 text-slate-400 hover:text-white"
              >
                  <ChevronLeft size={16} />
              </button>
              <span className="font-bold text-violet-400 uppercase font-rune tracking-widest">{viewRound === 0 ? "Подготовка" : `Раунд ${viewRound}`}</span>
              <button 
                onClick={() => setViewRound(Math.min(currentRound, viewRound + 1))}
                disabled={viewRound >= currentRound}
                className="p-1 hover:bg-slate-800 rounded disabled:opacity-30 text-slate-400 hover:text-white"
              >
                  <ChevronRight size={16} />
              </button>
          </div>
          <div className="flex items-center gap-2">
              {canRollback && onRollback && (
                  <button 
                    onClick={() => onRollback(viewRound)}
                    className="flex items-center gap-1 bg-red-900/20 hover:bg-red-900/40 text-red-400 border border-red-900/50 rounded px-2 py-1 text-[10px] uppercase font-bold transition-all mr-2"
                    title="Вернуться к состоянию на конец этого раунда"
                  >
                      <RotateCcw size={10} /> Переиграть сл.
                  </button>
              )}

              {isDirty && (
                  <button 
                    onClick={saveChanges}
                    className="flex items-center gap-1 text-emerald-400 hover:text-emerald-300 font-bold animate-pulse uppercase text-[10px] tracking-wider"
                  >
                      <Save size={12} /> Сохранить
                  </button>
              )}
          </div>
      </div>

      {/* 3. CONTENT AREA */}
      <div className="flex-1 bg-[#020408] relative overflow-hidden flex flex-col">

         {activeTab === 'stats' && (
             <div className="h-full flex flex-col">
                 <textarea 
                    className="flex-1 bg-[#020408] text-slate-300 p-4 outline-none resize-none font-mono text-xs leading-relaxed selection:bg-violet-900/50"
                    value={localStatsText}
                    onChange={handleTextChange(setLocalStatsText)}
                    spellCheck={false}
                    placeholder="Данные участников..."
                 />
             </div>
         )}

         {activeTab === 'log' && (
             <div className="h-full flex flex-col overflow-auto custom-scrollbar relative pl-2">
                 <div className="relative w-full min-h-full">
                     {/* Backdrop for Markers (Transparent Text) */}
                     <div 
                        className="absolute inset-0 p-4 font-mono text-xs leading-6 whitespace-pre-wrap break-words pointer-events-none text-transparent"
                        aria-hidden="true"
                     >
                        {localLogText.split('\n').map((line, i) => (
                            <div key={i} className="relative">
                                {/* The Marker - Positioned absolutely relative to the line */}
                                <div className={`absolute -left-3 top-1.5 transition-all duration-300 ${getLineColor(line)}`}></div>
                                {line || ' '} 
                            </div>
                        ))}
                     </div>

                     {/* Actual Editable Textarea */}
                     <textarea 
                        className="relative z-10 w-full h-full bg-transparent text-slate-300 p-4 font-mono text-xs leading-6 whitespace-pre-wrap break-words outline-none resize-none selection:bg-violet-900/50 placeholder-slate-700 overflow-hidden"
                        value={localLogText}
                        onChange={handleTextChange(setLocalLogText)}
                        spellCheck={false}
                        placeholder="Лог раунда пуст..."
                        // We set height auto to allow the container to scroll, assuming minimal height is satisfied by content
                        style={{ minHeight: '100%' }}
                     />
                 </div>
             </div>
         )}

         {activeTab === 'summary' && (
             <div className="h-full flex flex-col">
                 <div className="p-2 bg-violet-900/10 text-[10px] text-slate-500 uppercase tracking-widest border-b border-violet-900/20 flex justify-between items-center">
                     <span>Сводка (Раунд {viewRound})</span>
                     <button onClick={() => navigator.clipboard.writeText(summaryText)} title="Копировать" className="hover:text-white"><Clipboard size={12}/></button>
                 </div>
                 <textarea 
                    className="flex-1 bg-[#020408] text-slate-300 p-4 text-xs font-mono outline-none resize-none selection:bg-emerald-900/50"
                    value={summaryText}
                    onChange={handleTextChange(setSummaryText)}
                    placeholder={viewRound < currentRound && !summaryText ? "(Нет сохраненного итога)" : "Здесь будет сводка раунда..."}
                    spellCheck={false}
                 />
             </div>
         )}
      </div>
    </div>
  );
};

