import React, { useRef, useState } from 'react';
import { CharacterData, Faction, StatType, InjuryDefinition } from '../types';
import { NPC_VOLUMES } from '../constants';
import { StyledInput, StyledTextarea, StyledSelect, StatIcons, StatColors, StatBg, Button } from './Shared';
import { downloadCharacterFile } from '../utils/storage';
import { Coins, User, Download, Plus, Trash2, Skull, GitBranch, ShieldCheck, Upload, Loader2, Link2, Link2Off } from 'lucide-react';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer } from 'recharts';
import { DisplayMode } from '../App';
import { uploadAvatar } from '../utils/supabaseService';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';
import { useUI } from '../context/UIContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  onChange: (u: Partial<CharacterData>) => void;
  displayMode: DisplayMode;
  setDisplayMode: (m: DisplayMode) => void;
  characters: CharacterData[];
  onNavigate: (id: string) => void;
  onDelete?: (id: string) => void;
  injuryDefinitions?: InjuryDefinition[];
}

const SheetHeader: React.FC<Props> = ({ character, isEditMode, onChange, displayMode, setDisplayMode, characters, onNavigate, onDelete, injuryDefinitions = [] }) => {
  /* [DIALECT] */ const { t } = useDialect();
  const { showAlert, showConfirm } = useUI();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isUploading, setIsUploading] = useState(false);

  // New Structure: profile instead of identity
  const updateProfile = (field: keyof CharacterData['profile'], val: any) => {
    onChange({ profile: { ...character.profile, [field]: val } });
  };

  const updateMeta = (field: keyof CharacterData['meta'], val: any) => {
    onChange({ meta: { ...character.meta, [field]: val } });
  };

  const updateStats = (field: keyof CharacterData['stats'], val: any) => {
    onChange({ stats: { ...character.stats, [field]: val } });
  };

  const updateResources = (idx: number, field: string, val: any) => {
    const next = [...character.resources];
    next[idx] = { ...next[idx], [field]: val };
    onChange({ resources: next });
  };

  const addResource = () => {
    const next = [...character.resources, { label: "Ресурс", current: 0, max: 0 }];
    onChange({ resources: next });
  };

  const removeResource = (idx: number) => {
    showConfirm("Вы уверены, что хотите удалить этот ресурс?", () => {
      const next = character.resources.filter((_, i) => i !== idx);
      onChange({ resources: next });
    }, "Удаление ресурса");
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    try {
      const url = await uploadAvatar(file);
      updateMeta('avatar_url', url);
    } catch (error: any) {
      showAlert(error.message || "Ошибка загрузки файла", "Ошибка");
    } finally {
      setIsUploading(false);
      // Reset input so same file can be selected again if needed
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  // Calculate Trauma (Phys Penalty) - uses 'medcard'
  const getTraumaPenalty = () => {
    let penalty = 0;

    // Safety check for medcard/injuries existence
    const injuries = character.medcard?.injuries || [];

    const countsByTag: Record<string, number> = {};
    injuries.forEach(inj => {
      countsByTag[inj.template_id] = (countsByTag[inj.template_id] || 0) + (inj.count || 1);
    });

    Object.entries(countsByTag).forEach(([tag, totalCount]) => {
       const def = injuryDefinitions.find(d => d.tag === tag);
       if (def && def.type === 1) { // Type 1 is Physical
          const val = Math.abs(def.value);
          if (def.stack && def.stack > 1) {
             const appliedStacks = Math.floor(totalCount / def.stack);
             penalty += appliedStacks * val;
          } else {
             penalty += totalCount * val;
          }
       }
    });

    return penalty;
  };

  const trauma = getTraumaPenalty();
  const maxTrauma = 40; // Death threshold assumption
  const traumaPercent = Math.min(100, (trauma / maxTrauma) * 100);

  const chartData = [
    // [DIALECT] Translate chart labels
    { subject: t('stat_phys_short', 'ФИЗ'), A: character.stats.phys, fullMark: 30 },
    { subject: t('stat_mag_short', 'МАГ'), A: character.stats.magic, fullMark: 30 },
    { subject: t('stat_uni_short', 'УНИК'), A: character.stats.unique, fullMark: 30 },
  ];

  // Dynamic Styles based on Faction - Darker, more magical
  const getFactionColor = (f: Faction) => {
    switch (f) {
      case Faction.LIGHT: return "text-amber-300 border-amber-500/20 shadow-[0_0_15px_rgba(251,191,36,0.1)]";
      case Faction.DARK: return "text-violet-300 border-violet-500/20 shadow-[0_0_15px_rgba(139,92,246,0.1)]";
      case Faction.NPC: return "text-red-400 border-red-500/20 shadow-[0_0_15px_rgba(248,113,113,0.1)]";
      case Faction.GRAVEYARD: return "text-slate-400 border-slate-600/20";
      default: return "text-violet-300 border-violet-500/20";
    }
  };

  const factionColor = getFactionColor(character.profile.faction);

  // Companion Logic
  const COMPANION_VOLUME = "Спутники и Рабы";
  const master = character.meta.master_id ? characters.find(c => c.id === character.meta.master_id) : null;
  const isCompanion = character.profile.faction === Faction.NPC && character.profile.npc_volume === COMPANION_VOLUME;
  const isUnit = !!character.meta.master_id && !isCompanion;

  // [DIALECT] Helper for mapping
  const getVolumeLabel = (vol: string) => {
    if (vol.startsWith("Том 1")) return t('vol_1', vol);
    if (vol.startsWith("Том 2")) return t('vol_2', vol);
    if (vol.startsWith("Том 3")) return t('vol_3', vol);
    if (vol.startsWith("Том 4")) return t('vol_4', vol);
    if (vol.startsWith("Том 5")) return t('vol_5', vol);
    if (vol.startsWith("Том 6")) return t('vol_6', vol);
    if (vol === "Спутники и Рабы") return t('vol_servants', vol);
    if (vol === "Отрицательные NPC") return t('vol_neg', vol);
    if (vol === "Положительные NPC") return t('vol_pos', vol);
    return vol;
  };

  const getFactionLabel = (f: Faction) => {
      switch(f) {
          case Faction.LIGHT: return t('fac_light', Faction.LIGHT);
          case Faction.DARK: return t('fac_dark', Faction.DARK);
          case Faction.NPC: return t('fac_npc', Faction.NPC);
          case Faction.GRAVEYARD: return t('fac_graveyard', Faction.GRAVEYARD);
          default: return f;
      }
  };

  return (
    <div className="space-y-6 mb-6">

      {/* 1. Header Controls & Trauma Bar */}
      <div className="bg-[#050b14] border border-violet-900/30 p-3 sticky top-16 z-40 shadow-2xl rune-clip-r">
        <div className="flex flex-col md:flex-row gap-4 items-center justify-between">

          {/* Trauma Bar (The "Health" Bar) */}
          <div className="flex-1 w-full px-2">
            <div className="flex justify-between text-[10px] uppercase font-bold text-slate-500 mb-1 font-serif tracking-wider">
              {/* [DIALECT] */}
              <span>{t('mech_integrity', "Целостность Тела")}</span>
              <span className={trauma >= 40 ? "text-red-500 animate-pulse" : "text-slate-400"}>
                 -{trauma} / -{maxTrauma} {t('mech_injuries', 'Штраф')}
              </span>
            </div>
            <div className="h-2 w-full bg-[#020408] border border-slate-800 relative">
               {/* Markers */}
               <div className="absolute left-[25%] top-0 bottom-0 w-px bg-slate-800 z-10"></div>
               <div className="absolute left-[50%] top-0 bottom-0 w-px bg-slate-800 z-10"></div>
               <div className="absolute left-[75%] top-0 bottom-0 w-px bg-slate-800 z-10"></div>

               {/* Fill */}
               <div 
                 className={`h-full transition-all duration-500 ${trauma >= 35 ? 'bg-red-600 shadow-[0_0_10px_red]' : 'bg-red-900/80 shadow-[0_0_5px_red]'}`}
                 style={{ width: `${traumaPercent}%` }}
               ></div>
            </div>
          </div>

          {/* Quick Actions */}
          <div className="flex items-center gap-3">
             {/* Gold (Juhe) - Currencies now in profile */}
             <div className="flex items-center gap-2 text-amber-400 bg-amber-950/30 px-3 py-1 border border-amber-900/30 font-serif" title={t('meta_gold', "Джухе")}>
                <Coins size={14} />
                {isEditMode ? 
                  <input type="number" className="w-12 bg-transparent text-xs font-mono text-center focus:outline-none" value={character.profile.currencies.juhe || 0} onChange={e => updateProfile('currencies', {...character.profile.currencies, juhe: parseInt(e.target.value)})} /> 
                  : <span className="text-xs font-mono font-bold">{character.profile.currencies.juhe || 0}</span>
                }
             </div>

             {/* Silver (Jumi) */}
             <div className="flex items-center gap-2 text-slate-300 bg-slate-900/50 px-3 py-1 border border-slate-700 font-serif" title={t('meta_silver', "Джуми")}>
                <Coins size={14} />
                {isEditMode ? 
                  <input type="number" className="w-12 bg-transparent text-xs font-mono text-center focus:outline-none" value={character.profile.currencies.jumi || 0} onChange={e => updateProfile('currencies', {...character.profile.currencies, jumi: parseInt(e.target.value)})} /> 
                  : <span className="text-xs font-mono font-bold">{character.profile.currencies.jumi || 0}</span>
                }
             </div>

             <button onClick={() => downloadCharacterFile(character)} className="text-slate-500 hover:text-white transition-colors" title="Скачать JSON"><Download size={18} /></button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Identity & Stats */}
        <div className="lg:col-span-2 space-y-4">

           <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {/* Avatar Column */}
              <div className="col-span-1 flex flex-col gap-2">
                 {/* Rune-shaped Avatar */}
                 <div className={`aspect-square bg-[#050b14] border border-violet-900/20 overflow-hidden relative group rune-clip ${factionColor.split(' ')[1]}`}>
                    {character.meta.avatar_url ? (
                      <img src={character.meta.avatar_url} alt="Avatar" className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-slate-800"><User size={48}/></div>
                    )}

                    {/* Upload Overlay */}
                    {isEditMode && (
                      <div className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                         <button 
                           onClick={() => fileInputRef.current?.click()}
                           disabled={isUploading}
                           className="bg-violet-600 hover:bg-violet-500 text-white rounded-full p-3 shadow-lg flex items-center gap-2 font-bold text-xs"
                         >
                            {isUploading ? <Loader2 size={20} className="animate-spin" /> : <Upload size={20} />}
                         </button>
                      </div>
                    )}
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      className="hidden" 
                      accept="image/*" 
                      onChange={handleFileUpload} 
                    />
                 </div>

                 {/* Master/Unit Link */}
                 {character.meta.master_id && (
                   <button 
                     onClick={() => onNavigate(character.meta.master_id!)}
                     className="flex items-center justify-center gap-1 bg-violet-900/10 text-violet-400 hover:bg-violet-900/30 hover:text-violet-200 transition-all text-[10px] font-bold py-2 px-2 border border-violet-800/30 w-full rune-clip-r font-serif uppercase tracking-widest"
                   >
                     <GitBranch size={12} /> 
                     {master ? `СВЯЗАН: ${master.profile.name}` : "ЮНИТ (СВЯЗАН)"}
                   </button>
                 )}

                 {isEditMode && (
                   <div className="flex flex-col gap-1">
                      <input 
                        type="text" 
                        placeholder="URL аватарки" 
                        className="bg-[#020408] border border-slate-800 text-xs p-1 rounded-sm w-full text-slate-500 focus:text-slate-200 outline-none" 
                        value={character.meta.avatar_url}
                        onChange={e => updateMeta('avatar_url', e.target.value)}
                      />
                      <button 
                         onClick={() => fileInputRef.current?.click()}
                         className="flex items-center justify-center gap-2 bg-slate-900 hover:bg-slate-800 border border-slate-800 text-slate-400 hover:text-white text-[10px] py-1 rounded-sm w-full uppercase font-bold tracking-wider font-serif"
                      >
                         {isUploading ? <Loader2 size={12} className="animate-spin" /> : <Upload size={12} />}
                         {/* [DIALECT] */}
                         {isUploading ? t('meta_uploading', "Загрузка...") : t('meta_upload_avatar', "Загрузить (10MB)")}
                      </button>
                   </div>
                 )}

                 {/* Save Status / Death Cause Toggle */}
                 <div className="flex flex-col gap-2 mt-2">
                   {character.profile.faction !== Faction.GRAVEYARD ? (
                     <>
                        <button 
                           onClick={() => isEditMode && updateMeta('save_status', !character.meta.save_status)}
                           className={`flex items-center justify-center gap-2 py-2 rounded-sm border w-full text-xs font-bold font-serif uppercase tracking-wider transition-all ${
                               character.meta.save_status 
                               ? 'bg-emerald-900/10 text-emerald-500 border-emerald-900/30 hover:bg-emerald-900/20' 
                               : 'bg-red-950/20 text-red-500 border-red-900/30 hover:bg-red-900/20'
                           }`}
                        >
                           {character.meta.save_status ? <ShieldCheck size={14} /> : <Skull size={14} />}
                           {/* [DIALECT] */}
                           {character.meta.save_status ? t('meta_save_ok', "Есть сейв") : t('meta_save_lost', "Сейв потерян")}
                        </button>

                        {!character.meta.save_status && (
                          <StyledTextarea
                            isEditMode={isEditMode}
                            value={character.meta.save_status_reason || ""}
                            onChange={e => updateMeta('save_status_reason', e.target.value)}
                            placeholder="Укажите причину потери сейва..."
                            className="text-[10px] text-red-300 bg-red-950/10 border-red-900/20 min-h-[50px] italic text-center font-serif"
                          />
                        )}
                     </>
                   ) : (
                     // Graveyard Logic
                     <div className="flex flex-col gap-1">
                        <div className="flex items-center justify-center gap-2 py-2 rounded-sm border w-full text-xs font-bold font-serif uppercase tracking-widest bg-slate-900/50 border-slate-700 text-slate-400">
                           <Skull size={14} />
                           {/* [DIALECT] */}
                           {t('meta_death_cause', "Причина Смерти")}
                        </div>
                        <StyledTextarea
                           isEditMode={isEditMode}
                           value={character.meta.save_status_reason || ""}
                           onChange={e => updateMeta('save_status_reason', e.target.value)}
                           placeholder="Укажите причину смерти..."
                           className="text-[10px] text-slate-400 bg-slate-950/50 border-slate-800 min-h-[60px] italic text-center font-serif"
                        />
                     </div>
                   )}
                 </div>
              </div>

              {/* Stats & Info Column */}
              <div className="col-span-2 space-y-4">

                 {/* Name & Faction */}
                 <div className="bg-[#050b14] p-4 border border-violet-900/20 relative rune-clip-r">
                     <div className="flex flex-col gap-2">
                        <StyledInput 
                           /* [DIALECT] */
                           label={t('lbl_name', "Имя персонажа")}
                           isEditMode={isEditMode} 
                           value={character.profile.name} 
                           onChange={e => updateProfile('name', e.target.value)} 
                           className={`text-2xl font-black font-gothic uppercase tracking-tight ${factionColor.split(' ')[0]} drop-shadow-md bg-transparent border-b border-white/5 pb-1`} 
                        />
                        <div className="flex flex-wrap items-end gap-4">
                           <div className="flex-1 min-w-[140px]">
                              <StyledSelect 
                                /* [DIALECT] */
                                label={t('lbl_faction', "Фракция")}
                                isEditMode={isEditMode} 
                                value={character.profile.faction} 
                                onChange={e => updateProfile('faction', e.target.value)}
                                // [DIALECT] Translate Options
                                options={Object.values(Faction).map(f => ({ label: getFactionLabel(f), value: f }))} 
                                className="text-sm font-medium text-slate-400 font-serif tracking-wide"
                              />
                           </div>

                           {character.profile.faction === Faction.NPC && (
                              <div className="flex-1 min-w-[140px]">
                                 <StyledSelect 
                                   // [DIALECT]
                                   label={t('lbl_npc_vol', "Том NPC")}
                                   isEditMode={isEditMode} 
                                   value={character.profile.npc_volume || NPC_VOLUMES[0]} 
                                   onChange={e => updateProfile('npc_volume', e.target.value)}
                                   // [DIALECT] Translate Options
                                   options={NPC_VOLUMES.map(v => ({ label: getVolumeLabel(v), value: v }))} 
                                   className="text-sm font-medium text-red-400 font-serif tracking-wide"
                                 />
                              </div>
                           )}

                           {/* Master Selector Logic: Show if isCompanion OR if it's a Unit (has master) */}
                           {isEditMode && (isCompanion || isUnit || character.meta.master_id) && (
                              <div className="flex-1 min-w-[140px]">
                                 <span className="text-[9px] uppercase font-bold text-slate-600 tracking-widest font-serif block mb-1">Привязка (Хозяин)</span>
                                 <div className="flex gap-2">
                                    <select 
                                      className="bg-[#0b0d10] border border-violet-900/30 text-slate-300 text-xs rounded-sm px-2 py-1.5 focus:border-violet-500 w-full outline-none font-serif"
                                      value={character.meta.master_id || ""}
                                      onChange={e => updateMeta('master_id', e.target.value || undefined)}
                                    >
                                        <option value="">-- Нет / Свободен --</option>
                                        {characters
                                          .filter(c => c.id !== character.id && c.profile.faction !== Faction.NPC) 
                                          .map(c => (
                                          <option key={c.id} value={c.id}>{c.profile.name}</option>
                                        ))}
                                    </select>

                                    {/* Unlink / Banish Button */}
                                    {character.meta.master_id && (
                                       <button 
                                          onClick={() => {
                                             if (isCompanion) {
                                                updateMeta('master_id', undefined);
                                             } else if (onDelete) {
                                                // It's a unit, confirm deletion
                                                onDelete(character.id);
                                             }
                                          }}
                                          title={isCompanion ? "Разорвать связь" : "Изгнать (Удалить Юнита)"}
                                          className="bg-red-900/20 border border-red-500/30 text-red-400 hover:text-white hover:bg-red-900/50 p-1.5 rounded-sm transition-all"
                                       >
                                          {isCompanion ? <Link2Off size={14}/> : <Trash2 size={14}/>}
                                       </button>
                                    )}
                                 </div>
                              </div>
                           )}

                           <div className="flex items-center gap-2 pb-1">
                             <span className="text-[10px] uppercase font-bold text-slate-600 font-serif tracking-widest">
                                {/* [DIALECT] */}
                                {t('lbl_level', 'Уровень')}
                             </span>
                             {isEditMode ? (
                               <select 
                                 className="bg-[#0b0d10] border border-violet-900/30 text-xs rounded-sm p-1 text-slate-300 focus:outline-none focus:border-violet-600 font-mono" 
                                 value={character.profile.level} 
                                 onChange={e => updateProfile('level', parseInt(e.target.value))}
                               >
                                 {[1,2,3,4,5].map(l => (
                                     <option key={l} value={l} disabled={l === 5 && character.profile.faction !== Faction.NPC}>
                                         {l}
                                     </option>
                                 ))}
                               </select>
                             ) : (
                               <span className="text-violet-400 font-bold font-mono text-lg drop-shadow-glow">{character.profile.level}</span>
                             )}
                           </div>
                        </div>
                     </div>
                 </div>

                 <div className="flex gap-4 h-48 relative">
                    {/* Compact Chart - ABSOLUTE positioning to prevent flex width calculation issues */}
                    {/* Added background here for readability against image */}
                    <div className="flex-1 relative min-w-0 h-full bg-slate-950/70 backdrop-blur-sm rounded-xl border border-violet-900/20 overflow-hidden">
                       <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%' }}>
                           <ResponsiveContainer width="100%" height="100%">
                              <RadarChart cx="50%" cy="50%" outerRadius="65%" data={chartData}>
                                <PolarGrid stroke="#334155" strokeOpacity={0.5} />
                                <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748b', fontSize: 9, fontWeight: '900', fontFamily: 'Cinzel' }} />
                                <PolarRadiusAxis angle={30} domain={[0, 25]} tick={false} axisLine={false} />
                                <Radar
                                  name="Stats"
                                  dataKey="A"
                                  stroke="#8b5cf6"
                                  strokeWidth={2}
                                  fill="#8b5cf6"
                                  fillOpacity={0.3}
                                />
                              </RadarChart>
                            </ResponsiveContainer>
                       </div>
                    </div>

                    {/* Numeric Blocks */}
                    <div className="flex flex-col justify-between w-28 gap-1">
                        {[StatType.PHYS, StatType.MAGIC, StatType.UNIQUE].map(stat => (
                          <div key={stat} className={`relative px-2 py-1 rounded-sm border flex items-center justify-between gap-2 transition-all ${StatBg[stat]}`}>
                             <div className={`${StatColors[stat].split(' ')[0]}`}>{StatIcons[stat]}</div>
                             {isEditMode ? (
                               <input 
                                 type="number" 
                                 value={character.stats[stat]} 
                                 onChange={(e) => updateStats(stat, parseInt(e.target.value))}
                                 className="bg-transparent text-lg font-mono font-bold text-right w-full focus:outline-none text-slate-200"
                               />
                             ) : (
                               <span className="text-lg font-mono font-bold text-slate-200 drop-shadow-sm">{character.stats[stat]}</span>
                             )}
                          </div>
                        ))}
                    </div>
                 </div>
              </div>
           </div>

           {/* Bio (Lore Mode Only or Edit) */}
           {(displayMode === 'lore' || isEditMode) && (
             <div className="bg-[#050b14] border border-violet-900/20 p-4 relative shadow-inner">
               <StyledTextarea 
                 /* [DIALECT] */
                 label={t('lbl_bio', "Биография")}
                 isEditMode={isEditMode} 
                 value={character.profile.bio} 
                 onChange={e => updateProfile('bio', e.target.value)} 
                 className="min-h-[80px] text-slate-400 italic font-serif" 
               />
             </div>
           )}
        </div>

        {/* Resources */}
        <div className="space-y-3">
          {character.resources.map((res, idx) => (
            <div key={idx} className="bg-[#050b14] border border-slate-800 p-3 relative overflow-hidden group flex gap-2 items-center rune-clip-r">
               <div className="flex-1">
                 <div className="flex justify-between items-center mb-1 relative z-10">
                   {isEditMode ? (
                     <input className="bg-transparent font-bold text-xs text-slate-300 w-1/2 uppercase tracking-wide font-serif" value={res.label} onChange={e => updateResources(idx, 'label', e.target.value)} />
                   ) : (
                     <span className="font-bold text-xs text-slate-400 uppercase tracking-wide font-serif">
                        {/* [DIALECT] Simple manual mapping for standard resources if they match default names */}
                        {res.label === "HP" ? t('res_hp', "HP") : res.label === "MP" ? t('res_mp', "MP") : res.label === "Усталость" ? t('res_fatigue', "Усталость") : res.label}
                     </span>
                   )}
                   <div className="flex items-center gap-1 font-mono text-sm">
                      {isEditMode ? (
                         <>
                           <input type="number" className="bg-slate-900 w-10 text-center rounded-sm border border-slate-700 text-xs text-slate-200" value={res.current} onChange={e => updateResources(idx, 'current', parseInt(e.target.value))} />
                           <span className="text-slate-600">/</span>
                           <input type="number" className="bg-slate-900 w-10 text-center rounded-sm border border-slate-700 text-xs text-slate-200" value={res.max} onChange={e => updateResources(idx, 'max', parseInt(e.target.value))} />
                         </>
                      ) : (
                         <span className="text-violet-400 font-bold">
                           {res.current}
                           {res.max > 0 && <span className="text-slate-600 text-xs ml-0.5">/{res.max}</span>}
                         </span>
                      )}
                   </div>
                 </div>

                 {!isEditMode && res.max > 0 && (
                   <div className="w-full bg-[#020408] h-1.5 rounded-full overflow-hidden mt-2 relative z-10 border border-slate-800">
                     <div 
                        className="h-full bg-violet-600 transition-all duration-500 shadow-[0_0_5px_#7c3aed]" 
                        style={{ width: `${Math.min(100, (res.current / res.max) * 100)}%` }}
                     ></div>
                   </div>
                 )}
               </div>

               {isEditMode && (
                  <button onClick={() => removeResource(idx)} className="text-slate-600 hover:text-red-500 transition-colors p-1">
                    <Trash2 size={14} />
                  </button>
               )}
            </div>
          ))}

          {isEditMode && (
            <Button size="sm" variant="secondary" onClick={addResource} className="w-full border-dashed border-slate-700 text-slate-500 hover:text-white font-serif uppercase tracking-wider">
              {/* [DIALECT] */}
              <Plus size={14} /> {t('btn_add_res', 'Добавить')}
            </Button>
          )}
        </div>
      </div>
    </div>
  );
};

export default SheetHeader;

import { BattleParticipant, SequenceNode, JsonAbility, JsonItem, JsonBonus, InjuryRule } from '../types';
import { TRAUMA_DEFINITIONS } from '../constants';

interface CalculationResult {
  formattedString: string;
}

// --- CONFIGURATION ---

const DEFAULT_INJURY_RULES: InjuryRule[] = Object.entries(TRAUMA_DEFINITIONS).map(([tag, def]) => ({
    tag,
    label: def.label,
    value: def.value,
    stack: def.stack
}));

const normalizeTags = (tags: string[] = []) => tags.map(t => t.toLowerCase().trim());

const hasTagOverlap = (sourceTags: string[], targetTags: string[]): boolean => {
    if (!sourceTags || sourceTags.length === 0) return true; 
    return sourceTags.some(t => targetTags.includes(t));
};

const sumBonuses = (bonuses: JsonBonus[] = []): number => {
    return bonuses.reduce((acc, b) => acc + (Number(b.val) || 0), 0);
};

const calculateLiveStatPenalty = (
    participant: BattleParticipant, 
    statType: 'phys' | 'magic' | 'unique',
    rules: InjuryRule[]
): number => {
    if (!participant.medcard || !participant.medcard.injuries) return 0;

    let totalPenalty = 0;
    const suffix = `_${statType === 'unique' ? 'uniq' : statType}`; 

    const injuryCounts: Record<string, number> = {};
    participant.medcard.injuries.forEach(inj => {
        const tag = inj.template_id;
        if (tag.endsWith(suffix)) {
            injuryCounts[tag] = (injuryCounts[tag] || 0) + (inj.count || 1);
        }
    });

    Object.entries(injuryCounts).forEach(([tag, count]) => {
        const rule = rules.find(r => r.tag === tag);
        if (rule) {
            const penaltyValue = Number(rule.value);
            const stackSize = Number(rule.stack);

            if (stackSize > 0) {
                const stacksApplied = Math.floor(count / stackSize);
                totalPenalty += (stacksApplied * penaltyValue);
            } else {
                totalPenalty += (count * penaltyValue);
            }
        }
    });

    return totalPenalty;
};

export const getMatchingFactors = (
    participant: BattleParticipant,
    abilityTags: string[]
) => {
    const factors: { name: string, bonus: number, type: 'passive' | 'effect' | 'item', tags?: string[], desc?: string, mech?: string }[] = [];
    const normalizedAbilityTags = normalizeTags(abilityTags);

    // 1. Passives (Use FLAT list which already has inherited tags from Supabase load)
    if (participant.flat_passives) {
        participant.flat_passives.forEach(pas => {
            const isAlways = !pas.trigger || pas.trigger.toLowerCase() === 'always' || pas.trigger === 'Пассивно / Всегда';
            // We use pas.tags which now includes group tags
            if (isAlways && hasTagOverlap(normalizeTags(pas.tags), normalizedAbilityTags)) {
                factors.push({ 
                    name: pas.name, 
                    bonus: sumBonuses(pas.bonuses), 
                    type: 'passive', 
                    tags: pas.tags,
                    mech: pas.desc_mech 
                });
            }
        });
    }

    // 2. Active Effects
    if (participant.active_effects) {
        participant.active_effects.forEach(eff => {
            if (hasTagOverlap(normalizeTags(eff.tags), normalizedAbilityTags)) {
                // Try to find source ability for better description
                let mechanics = '';
                if (eff.original_ability_id) {
                    const source = participant.flat_abilities.find(a => a._id === eff.original_ability_id);
                    if (source) mechanics = source.desc_mech || '';
                }

                factors.push({ 
                    name: eff.name, 
                    bonus: sumBonuses(eff.bonuses), 
                    type: 'effect', 
                    tags: eff.tags,
                    desc: `Active effect. Duration: ${eff.duration_left} ${eff.unit}`,
                    mech: mechanics
                });
            }
        });
    }

    // 3. Wearables
    if (participant.equipment && participant.equipment.wearable) {
        participant.equipment.wearable.forEach(item => {
            if (item.is_equipped && hasTagOverlap(normalizeTags(item.tags), normalizedAbilityTags)) {
                factors.push({ 
                    name: item.name, 
                    bonus: sumBonuses(item.bonuses), 
                    type: 'item', 
                    tags: item.tags,
                    mech: item.desc_mech,
                    desc: item.desc_lore
                });
            }
        });
    }

    return factors;
};

const calculateTotalBonus = (
    participant: BattleParticipant, 
    ability: JsonAbility, 
    weapon: JsonItem | undefined,
    injuryRules: InjuryRule[],
    excludedModifiers: string[] = []
): number => {
    let total = 0;

    const usedStats = new Set<string>();
    if (ability.bonuses) {
        ability.bonuses.forEach(b => {
            const bonusVal = Number(b.val) || 0;
            if (b.stat) {
                const statKey = b.stat.toLowerCase();
                if (statKey.includes('phys') || statKey.includes('физ')) {
                    if (!usedStats.has('phys')) {
                        const base = Number(participant.stats.phys) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'phys', injuryRules));
                        usedStats.add('phys');
                    }
                } 
                if (statKey.includes('mag') || statKey.includes('маг')) {
                    if (!usedStats.has('magic')) {
                        const base = Number(participant.stats.magic) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'magic', injuryRules));
                        usedStats.add('magic');
                    }
                } 
                if (statKey.includes('uniq') || statKey.includes('уник')) {
                    if (!usedStats.has('unique')) {
                        const base = Number(participant.stats.unique) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'unique', injuryRules));
                        usedStats.add('unique');
                    }
                }
            }
            total += bonusVal;
        });
    }

    if (weapon) total += sumBonuses(weapon.bonuses);

    const externalFactors = getMatchingFactors(participant, ability.tags);
    externalFactors.forEach(f => {
        if (!excludedModifiers.includes(f.name)) {
            total += f.bonus;
        }
    });

    return total;
};


// --- TREE WALKER ---

const getDiceString = (level: number = 1): string => {
    if (level >= 5) return '3d100';
    if (level >= 3) return '2d100';
    return '1d100';
};

export const calculateSequenceTree = (
  nodes: SequenceNode[],
  participants: BattleParticipant[],
  injuryRules: InjuryRule[] = DEFAULT_INJURY_RULES 
): CalculationResult => {

  const getActionData = (charId: string, abilityId: string, weaponId?: string, excludedModifiers: string[] = []) => {
        const actor = participants.find(p => p.instance_id === charId || p.id === charId);
        if (!actor) return null;

        // Use flat_abilities which has inherited tags
        let ability = actor.flat_abilities?.find(a => a._id === abilityId);

        // Fallback search if id mismatch (rare now)
        if (!ability && actor.ability_groups) {
            for (const group of actor.ability_groups) {
                const found = group.abilities.find(a => a._id === abilityId || (a.id && a.id === abilityId) || a.name === abilityId);
                if (found) { ability = found; break; }
            }
        }

        if (!ability) return null;

        const weapon = actor.equipment.usable.find(w => w._id === weaponId || (w.id && w.id === weaponId) || w.name === weaponId);

        const bonusVal = calculateTotalBonus(actor, ability, weapon, injuryRules, excludedModifiers);
        const sign = bonusVal >= 0 ? '+' : '';
        const weaponStr = weapon && weapon.name ? ` [${weapon.name}]` : ''; // FIX: Ensure weapon.name exists
        const nameStr = `${ability.name}${weaponStr}`;
        const diceStr = getDiceString(actor.profile.level);

        const isForm = ability.tags.some(t => ['form', 'форма'].includes(t.toLowerCase()));
        const isBuff = ability.tags.some(t => ['buff', 'бафф'].includes(t.toLowerCase()));

        return { 
            name: nameStr, 
            actorName: actor.profile.name,
            bonus: `${sign}${bonusVal}`, 
            dice: diceStr, 
            isForm,
            isBuff,
            mechanics: ability.desc_mech
        };
  };

  const processNode = (node: SequenceNode): string => {
    // Return a newline + space + newline to ensure it survives trimming logic and creates a gap
    if (node.type === 'divider') return '\n \n';

    // Handle Logic Chain Container
    if (node.type === 'logic_chain') {
        const childrenStr = node.children.map(c => processNode(c)).join(' | ');
        return `\n{ ${childrenStr} }`;
    }

    if (node.type === 'condition') {
      const conditionText = node.data?.conditionText || '...';
      const childStrings = node.children.map(c => processNode(c)).filter(s => s && s.trim() !== '');
      let innerContent = childStrings.join(' - ');
      return `${conditionText}: ${innerContent}`;
    }

    if (node.type === 'combo') {
      const validChildren = node.children.filter(c => c.type === 'action');
      if (validChildren.length === 0) return '';

      const dataList = validChildren.map(c => 
          getActionData(c.data?.charId || '', c.data?.abilityId || '', c.data?.weaponId, c.data?.excludedModifiers)
      ).filter(Boolean) as any[];

      if (dataList.length === 0) return '';

      // If ANY action in combo is a normal attack, show bonuses. 
      // If all are utility (Buff/Form), behave like utility but in combo block?
      // Standard format: [Name: Ability + Name2: Ability2(Dice1/Dice2)]

      const namesPart = dataList.map(d => `${d.actorName}: ${d.name}`).join(' + ');

      // Calculate bonuses part, filtering out utility actions that don't need dice roll usually
      // But for combo, we might just list all. Let's list all for now to be safe.
      const bonusesPart = dataList.map(d => (d.isForm || d.isBuff) ? '-' : `${d.dice}${d.bonus}`).join('/');

      return `[${namesPart}(${bonusesPart})]`;
    }

    if (node.type === 'action') {
        const data = getActionData(node.data?.charId || '', node.data?.abilityId || '', node.data?.weaponId, node.data?.excludedModifiers);
        if (!data) return '[Unknown Action]';

        if (data.isForm) {
            // Form format: <Character: Name (Mechanics)>
            return `<${data.actorName}: ${data.name} (${data.mechanics || ''})>`;
        }

        if (data.isBuff) {
            // Buff format: (Character: Name (Mechanics))
            return `(${data.actorName}: ${data.name} (${data.mechanics || ''}))`;
        }

        // Attack format: Character: Name(Dice+Bonus)
        return `${data.actorName}: ${data.name}(${data.dice}${data.bonus})`;
    }

    return '';
  };

  const parts = nodes.map(n => processNode(n)).filter(Boolean);

  let finalString = '';

  parts.forEach((part, index) => {
      // Trim end only to allow leading newlines from divider to work
      const cleanPart = part.trimEnd();

      if (index === 0) {
          if (cleanPart.startsWith('\n')) {
              finalString += '> ' + cleanPart.trimStart(); 
          } else {
              finalString += '> ' + cleanPart;
          }
      } else {
          // If we have a newline from divider (or logic block), respect it
          if (finalString.endsWith('\n') || cleanPart.startsWith('\n')) {
              if (cleanPart.startsWith('\n')) {
                  finalString += '\n> ' + cleanPart.trimStart();
              } else {
                  finalString += '\n> ' + cleanPart; 
              }
          } else {
               finalString += ' - ' + cleanPart;
          }
      }
  });

  return { formattedString: finalString };
};

import React, { useState, useEffect } from 'react';
import { LogEntry, BattleParticipant } from '../types';
import { ChevronLeft, ChevronRight, Clipboard, Save, BarChart3, ScrollText, ListEnd, RotateCcw } from 'lucide-react';
import { generateSummary, generateStatsText } from '../engine/formatters';

interface Props {
  logs: LogEntry[];
  currentRound: number;
  participants: BattleParticipant[];
  onUpdateLogs: (logs: LogEntry[]) => void;
  onUpdateParticipant?: (id: string, updates: any) => void;
  onRollback?: (round: number) => void;
}

// Tabs
type Tab = 'stats' | 'log' | 'summary';

const BattleLog: React.FC<Props> = ({ logs, currentRound, participants, onUpdateLogs, onUpdateParticipant, onRollback }) => {
  const [activeTab, setActiveTab] = useState<Tab>('log'); 
  const [viewRound, setViewRound] = useState(currentRound);

  // Text Areas State
  const [summaryText, setSummaryText] = useState("");
  const [localLogText, setLocalLogText] = useState("");
  const [localStatsText, setLocalStatsText] = useState("");

  const [isDirty, setIsDirty] = useState(false);

  useEffect(() => {
      setViewRound(currentRound);
  }, [currentRound]);

  // Sync Data on Round Change or Mount
  useEffect(() => {
      // 1. LOG TEXT
      const roundEntries = logs.filter(l => l.round === viewRound && l.type !== 'system');
      const joinedText = roundEntries.map(l => l.text_formatted).join('\n');
      setLocalLogText(joinedText);

      // 2. FIND SNAPSHOT
      const snapshotLog = logs.find(l => l.round === viewRound && l.details?.participants_snapshot);

      // 3. SUMMARY
      const allEntriesForRound = logs.filter(l => l.round === viewRound);
      const entryWithSummary = allEntriesForRound.reverse().find(l => l.summary !== undefined && l.summary !== null && l.type !== 'system');

      if (entryWithSummary) {
          setSummaryText(entryWithSummary.summary || "");
      } else if (snapshotLog && snapshotLog.summary) {
          setSummaryText(snapshotLog.summary);
      } else {
          if (viewRound === currentRound) {
              setSummaryText(generateSummary(participants, currentRound));
          } else {
              setSummaryText("(Нет сохраненного итога)"); 
          }
      }

      // 4. STATS
      if (!isDirty) {
          if (viewRound === currentRound) {
              setLocalStatsText(generateStatsText(participants));
          } else if (snapshotLog && snapshotLog.details?.stats_snapshot) {
              setLocalStatsText(snapshotLog.details.stats_snapshot);
          } else {
              setLocalStatsText("(Нет сохраненных характеристик)");
          }
      }

      setIsDirty(false);
  }, [viewRound, logs, participants, currentRound]); 

  const handleTextChange = (setter: React.Dispatch<React.SetStateAction<string>>) => (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      setter(e.target.value);
      setIsDirty(true);
  };

  const parseAndSaveStats = () => {
      if (!onUpdateParticipant) return;

      const blocks = localStatsText.split(/\n\s*\n/);

      blocks.forEach(block => {
          const lines = block.split('\n').map(l => l.trim()).filter(l => l);
          if (lines.length === 0) return;

          const headerMatch = lines[0].match(/^(.+)\s\(\d+\s*ур\.\)$/i);
          const name = headerMatch ? headerMatch[1].trim() : lines[0].trim();

          const participant = participants.find(p => p.profile.name === name);
          if (participant) {
              const newStats = { ...participant.stats };

              lines.forEach(line => {
                  const lower = line.toLowerCase();
                  const matchVal = line.match(/:\s*(-?\d+)/);

                  if (matchVal) {
                      const val = parseInt(matchVal[1]);
                      if (!isNaN(val)) {
                          if (lower.startsWith('физ')) newStats.phys = val;
                          else if (lower.startsWith('маг')) newStats.magic = val;
                          else if (lower.startsWith('уник')) newStats.unique = val;
                      }
                  }
              });

              onUpdateParticipant(participant.instance_id, { stats: newStats });
          }
      });
  };

  const saveChanges = () => {
      const otherRoundLogs = logs.filter(l => l.round !== viewRound);
      const systemLogs = logs.filter(l => l.round === viewRound && l.type === 'system'); 

      const newEntry: LogEntry = {
          id: `edited-${viewRound}-${Date.now()}`,
          round: viewRound,
          timestamp: new Date().toISOString(),
          type: 'action',
          text_formatted: localLogText,
          summary: summaryText 
      };

      const newLogs = [...otherRoundLogs, ...systemLogs];
      if (localLogText.trim()) {
          newLogs.push(newEntry);
      }

      newLogs.sort((a, b) => {
           if (a.round !== b.round) return a.round - b.round;
           return 0; 
      });

      onUpdateLogs(newLogs);

      if (activeTab === 'stats') {
          parseAndSaveStats();
      }

      setIsDirty(false);
  };

  const canRollback = viewRound < currentRound && logs.some(l => l.round === viewRound && l.details?.participants_snapshot);

  const getLineColor = (line: string) => {
      const trim = line.trim();

      // System (Start/End) -> Vertical Purple
      if (trim.includes('НАЧАЛО РАУНДА') || trim.includes('ЗАВЕРШЕНИЕ')) {
          return 'bg-violet-500 shadow-[0_0_8px_#8b5cf6] h-3 w-1 rounded-full';
      } 

      // Form (Gold) -> Starts with > <
      else if (trim.startsWith('> <')) {
          return 'bg-amber-400 shadow-[0_0_5px_#fbbf24] h-3 w-1 rounded-full';
      }

      // Buff (Emerald) -> Starts with > (
      else if (trim.startsWith('> (')) {
          return 'bg-emerald-500 shadow-[0_0_5px_#10b981] h-3 w-1 rounded-full';
      } 

      // Combo (Bright Blue) -> Starts with > [
      else if (trim.startsWith('> [')) {
          return 'bg-blue-500 shadow-[0_0_5px_#3b82f6] h-3 w-1 rounded-full';
      } 

      // Logic (Dark Blue) -> Starts with > { or Condition
      else if (trim.startsWith('> {') || trim.startsWith('{') || trim.includes('Condition:') || trim.includes('Если')) {
          return 'bg-indigo-500 shadow-[0_0_5px_#6366f1] h-3 w-1 rounded-full';
      } 

      // Attack (Red) -> Default > 
      else if (trim.startsWith('>')) {
          return 'bg-red-600 shadow-[0_0_5px_#dc2626] h-3 w-1 rounded-full';
      }

      return 'bg-transparent';
  };

  return (
    <div className="h-full flex flex-col bg-panel rounded-lg shadow-xl border border-violet-900/30 overflow-hidden">

      {/* 1. TABS HEADER */}
      <div className="flex border-b border-violet-900/30 bg-[#020408]">
          <button 
            onClick={() => setActiveTab('stats')}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-all ${activeTab === 'stats' ? 'bg-violet-900/20 text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-white'}`}
          >
              <BarChart3 size={14} /> Характеристики
          </button>
          <button 
            onClick={() => setActiveTab('log')}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-all ${activeTab === 'log' ? 'bg-violet-900/20 text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-white'}`}
          >
              <ScrollText size={14} /> Лог
          </button>
          <button 
            onClick={() => setActiveTab('summary')}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-2 transition-all ${activeTab === 'summary' ? 'bg-violet-900/20 text-violet-300 border-b-2 border-violet-500' : 'text-slate-500 hover:text-white'}`}
          >
              <ListEnd size={14} /> Итог
          </button>
      </div>

      {/* 2. ROUND CONTROLS */}
      <div className="bg-[#050b14] border-b border-violet-900/20 p-2 flex items-center justify-between text-xs">
          <div className="flex items-center gap-2">
              <button 
                onClick={() => setViewRound(Math.max(0, viewRound - 1))}
                disabled={viewRound <= 0}
                className="p-1 hover:bg-slate-800 rounded disabled:opacity-30 text-slate-400 hover:text-white"
              >
                  <ChevronLeft size={16} />
              </button>
              <span className="font-bold text-violet-400 uppercase font-rune tracking-widest">{viewRound === 0 ? "Подготовка" : `Раунд ${viewRound}`}</span>
              <button 
                onClick={() => setViewRound(Math.min(currentRound, viewRound + 1))}
                disabled={viewRound >= currentRound}
                className="p-1 hover:bg-slate-800 rounded disabled:opacity-30 text-slate-400 hover:text-white"
              >
                  <ChevronRight size={16} />
              </button>
          </div>
          <div className="flex items-center gap-2">
              {canRollback && onRollback && (
                  <button 
                    onClick={() => onRollback(viewRound)}
                    className="flex items-center gap-1 bg-red-900/20 hover:bg-red-900/40 text-red-400 border border-red-900/50 rounded px-2 py-1 text-[10px] uppercase font-bold transition-all mr-2"
                    title="Вернуться к состоянию на конец этого раунда"
                  >
                      <RotateCcw size={10} /> Переиграть сл.
                  </button>
              )}

              {isDirty && (
                  <button 
                    onClick={saveChanges}
                    className="flex items-center gap-1 text-emerald-400 hover:text-emerald-300 font-bold animate-pulse uppercase text-[10px] tracking-wider"
                  >
                      <Save size={12} /> Сохранить
                  </button>
              )}
          </div>
      </div>

      {/* 3. CONTENT AREA */}
      <div className="flex-1 bg-[#020408] relative overflow-hidden flex flex-col">

