                                className="flex items-center gap-2 bg-slate-900 hover:bg-emerald-900/30 text-emerald-400 border border-emerald-900/50 hover:border-emerald-500/50 px-5 py-2 rounded-sm font-bold font-rune uppercase text-xs tracking-widest transition-all hover:shadow-glow"
