// [DIALECT] - This whole file is part of the dialect module
import React, { createContext, useContext, useState, useEffect } from 'react';
import { DIALECT_DICT } from './dictionary';

interface DialectContextType {
  isOldSlavonic: boolean;
  isDialectUnlocked: boolean;
  toggleDialect: () => void;
  handleSlashClick: () => void;
  handleLetterClick: (char: string) => void;
  isInputMode: boolean;
  inputBuffer: string;
  t: (key: string, defaultText: string) => string;
}

const DialectContext = createContext<DialectContextType | undefined>(undefined);

export const DialectProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isOldSlavonic, setIsOldSlavonic] = useState(false);
  const [isDialectUnlocked, setIsDialectUnlocked] = useState(false);

  // Easter Egg State
  const [slashClickCount, setSlashClickCount] = useState(0);
  const [isInputMode, setIsInputMode] = useState(false);
  const [inputBuffer, setInputBuffer] = useState("");

  // Changed secret code to match "Летопись // Душ"
  const SECRET_CODE = "лето//пис";
  const CLICKS_REQUIRED = 15;

  useEffect(() => {
    // Load persisted states
    const savedDialect = localStorage.getItem('isOldSlavonic') === 'true';
    const savedUnlock = localStorage.getItem('isDialectUnlocked') === 'true';

    setIsOldSlavonic(savedDialect);
    setIsDialectUnlocked(savedUnlock);
  }, []);

  const unlock = () => {
    setIsDialectUnlocked(true);
    localStorage.setItem('isDialectUnlocked', 'true');
    setIsInputMode(false);
    setInputBuffer("");
    console.log("Dialect Unlocked!");
  };

  const handleSlashClick = () => {
    if (isDialectUnlocked) return;

    if (!isInputMode) {
      const newCount = slashClickCount + 1;
      setSlashClickCount(newCount);
      if (newCount >= CLICKS_REQUIRED) {
        setIsInputMode(true);
        setInputBuffer(""); // Reset buffer when mode starts
      }
    } else {
      // If in input mode, slash acts as part of the code
      handleLetterClick("//");
    }
  };

  const handleLetterClick = (char: string) => {
    // Only process letters if we are in input mode and not yet unlocked
    if (!isInputMode || isDialectUnlocked) return;

    setInputBuffer(prev => {
      // Keep only last N chars relevant to code length + visual buffer
      const next = (prev + char.toLowerCase()).slice(-20);

      if (next.includes(SECRET_CODE)) {
         unlock();
      }
      return next;
    });
  };

  const toggleDialect = () => {
    setIsOldSlavonic(prev => {
      const next = !prev;
      localStorage.setItem('isOldSlavonic', String(next));
      return next;
    });
  };

  const t = (key: string, defaultText: string) => {
    if (!isOldSlavonic) return defaultText;
    return DIALECT_DICT[key] || defaultText;
  };

  return (
    <DialectContext.Provider value={{ 
      isOldSlavonic, 
      isDialectUnlocked, 
      toggleDialect, 
      handleSlashClick, 
      handleLetterClick, 
      isInputMode,
      inputBuffer,
      t 
    }}>
      {children}
    </DialectContext.Provider>
  );
};

export const useDialect = () => {
  const context = useContext(DialectContext);
  if (!context) {
    return { 
      isOldSlavonic: false, 
      isDialectUnlocked: false, 
      toggleDialect: () => {}, 
      handleSlashClick: () => {},
      handleLetterClick: () => {},
      isInputMode: false,
      inputBuffer: "",
      t: (_: string, d: string) => d 
    };
  }
  return context;
};

import React, { useState } from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { LayoutGrid, Users, Sword, Library, LogOut, Hexagon, ChevronLeft, ChevronRight, X, RefreshCw, AlertCircle } from 'lucide-react';
import { NavItem } from '../../types';
import { CacheService } from '../../utils/cache';

interface SidebarProps {
  isDesktopCollapsed: boolean;
  toggleDesktopSidebar: () => void;
  isMobileOpen: boolean;
  closeMobileSidebar: () => void;
}

const REFRESH_COOLDOWN = 60 * 60 * 1000; // 1 hour in ms
const LAST_REFRESH_KEY = 'juul_d_last_refresh';

export const Sidebar: React.FC<SidebarProps> = ({ 
  isDesktopCollapsed, 
  toggleDesktopSidebar,
  isMobileOpen,
  closeMobileSidebar
}) => {
  const { signOut, user, triggerAdminSequence, isAdmin } = useAuth();
  const navigate = useNavigate();
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [refreshError, setRefreshError] = useState<string | null>(null);

  const navItems: NavItem[] = [
    { label: 'Распутье', path: '/', icon: LayoutGrid },
    { label: 'Летопись', path: '/roster', icon: Users },
    { label: 'Симуляция', path: '/battle', icon: Sword },
    { label: 'Архивы', path: '/lore', icon: Library },
  ];

  const handleLogout = async () => {
    await signOut();
    navigate('/auth');
    if (window.innerWidth < 768) closeMobileSidebar();
  };

  const handleRefreshData = async () => {
      setRefreshError(null);

      if (!isAdmin) {
          const lastRefresh = localStorage.getItem(LAST_REFRESH_KEY);
          if (lastRefresh) {
              const timeSince = Date.now() - parseInt(lastRefresh, 10);
              if (timeSince < REFRESH_COOLDOWN) {
                  const minutesLeft = Math.ceil((REFRESH_COOLDOWN - timeSince) / 60000);
                  setRefreshError(`Ждите ${minutesLeft} мин.`);
                  setTimeout(() => setRefreshError(null), 3000);
                  return;
              }
          }
      }

      setIsRefreshing(true);
      // Clear all cache
      CacheService.clearAll();

      // Update timestamp
      localStorage.setItem(LAST_REFRESH_KEY, Date.now().toString());

      // Simulate a small delay for visual feedback, then reload page to re-fetch fresh data
      setTimeout(() => {
          setIsRefreshing(false);
          window.location.reload();
      }, 800);
  };

  const handleLinkClick = () => {
    if (window.innerWidth < 768) closeMobileSidebar();
  }

  return (
    <aside 
      className={`
        fixed inset-y-0 left-0 z-50
        bg-[#050b14]/95 backdrop-blur-xl border-r border-violet-500/20 
