          </button>

          {/* Logout */}
          <button 
            onClick={handleLogout}
            className={`
              flex items-center gap-4 px-3 py-2 rounded-lg text-slate-500 hover:text-red-400 hover:bg-red-900/10 border border-transparent hover:border-red-500/30 transition-all w-full
