                          </div>
                      </div>
                  ))}
                </div>
              </div>
            )}

            {/* 2. Books - INCREASED SIZE */}
            {visibleBooks.length > 0 && (
               <div>
                   <div className="flex items-center justify-between mb-4 border-b border-violet-500/20 pb-1">
                     <h4 className="text-xs font-bold uppercase tracking-widest text-violet-400/70">Фолианты</h4>

                     {/* Mini Filter */}
                     <div className="flex bg-slate-900 rounded p-0.5 border border-slate-700">
                        <button onClick={() => setFilterStatus('all')} className={`px-2 py-0.5 text-[10px] rounded ${filterStatus === 'all' ? 'bg-violet-600 text-white' : 'text-slate-500'}`}>Все</button>
                        <button onClick={() => setFilterStatus('active')} className={`px-2 py-0.5 text-[10px] rounded ${filterStatus === 'active' ? 'bg-violet-600 text-white' : 'text-slate-500'}`}>Акт</button>
