                            >
                                {/* Active Indicator */}
                                {book.active && (
                                    <div className="absolute top-2 right-2 z-20 bg-black/50 rounded-full p-1 border border-violet-500/50">
                                         <Zap size={14} className="text-violet-400 animate-pulse" fill="currentColor" />
                                    </div>
                                )}

                                {/* Admin Actions */}
                                {isAdmin && (
                                    <div className="absolute top-2 left-2 flex flex-col gap-1 z-20 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={(e) => { e.stopPropagation(); handleDeleteBook(book.id); }} className="p-1.5 bg-black/70 rounded text-slate-400 hover:text-red-400"><Trash2 size={12} /></button>
                                        <button onClick={(e) => { e.stopPropagation(); setFormBook(book); setIsBookModalOpen(true); }} className="p-1.5 bg-black/70 rounded text-slate-400 hover:text-violet-400"><Edit2 size={12} /></button>
                                    </div>
                                )}

                                {/* Book Icon */}
                                <div className="relative w-16 h-16 mb-4 transition-transform duration-500 group-hover:scale-110">
                                    <BookOpen className="w-full h-full text-slate-600 group-hover:text-violet-300 transition-colors drop-shadow-lg" strokeWidth={1} />
                                </div>

                                <h3 className="text-sm md:text-base font-fantasy font-bold text-slate-300 group-hover:text-white transition-colors line-clamp-2 leading-tight">
                                    {book.title}
                                </h3>

                                <div className="absolute bottom-0 left-0 right-0 h-1 bg-violet-600 scale-x-0 group-hover:scale-x-100 transition-transform duration-500 origin-left"></div>
                            </div>
                        ))}
                   </div>
               </div>
            )}

            {visibleBooks.length === 0 && visibleSubFolders.length === 0 && selectedCategoryId && (
                <div className="flex flex-col items-center justify-center h-64 opacity-30">
                    <Scroll size={48} className="mb-2" />
                    <span className="font-fantasy text-lg">Здесь пусто...</span>
                </div>
            )}
        </div>
      </div>

      {/* --- Modals --- */}
      <Modal isOpen={isBookModalOpen} onClose={() => setIsBookModalOpen(false)} title={formBook.id ? "Переписать Том" : "Вписать Новый Том"}>
        <form onSubmit={handleBookSubmit} className="space-y-4">
          <MagicalInput required placeholder="Название" 
             value={formBook.title || ''} onChange={e => setFormBook({...formBook, title: e.target.value})} />

          <div className="bg-slate-800/30 p-3 rounded border border-slate-700/50">
             <RuneCheckbox 
                label="Активная Способность" 
                checked={formBook.active || false} 
                onChange={v => setFormBook({...formBook, active: v})} 
             />
             {formBook.active && (
                 <MagicalTextArea rows={2} className="border-violet-500/30 mt-3 text-sm"
                    placeholder="Механика..." value={formBook.active_effects || ''} onChange={e => setFormBook({...formBook, active_effects: e.target.value})} />
             )}
          </div>

          <MagicalInput placeholder="Пассивные эффекты" 
             value={formBook.effects || ''} onChange={e => setFormBook({...formBook, effects: e.target.value})} />

          <MagicalTextArea required placeholder="Лор / Содержание" rows={8} 
             value={formBook.description || ''} onChange={e => setFormBook({...formBook, description: e.target.value})} />

          <button type="submit" className="w-full mt-4 group relative px-6 py-3 bg-slate-900 border-2 border-violet-500/50 shadow-[0_0_15px_rgba(139,92,246,0.2)] text-violet-100 font-fantasy tracking-[0.2em] uppercase hover:bg-violet-900/40 hover:border-violet-400 hover:shadow-[0_0_25px_rgba(139,92,246,0.6)] transition-all duration-300 overflow-hidden">
             <span className="relative z-10">{formBook.id ? "Обновить Хроники" : "Сохранить в Архив"}</span>
          </button>
        </form>
      </Modal>

      <Modal isOpen={isCategoryModalOpen} onClose={() => setIsCategoryModalOpen(false)} title="Новый Раздел">
         <form onSubmit={handleCategorySubmit} className="space-y-4">
             <div className="text-sm text-slate-400">Родитель: <span className="font-mono text-white">{currentCategory ? currentCategory.name : 'Корень Архива'}</span></div>
             <MagicalInput required autoFocus placeholder="Название раздела" 
                 value={newCatName} onChange={e => setNewCatName(e.target.value)} />
             <button type="submit" className="w-full mt-4 group relative px-6 py-3 bg-slate-900 border-2 border-emerald-500/50 shadow-[0_0_15px_rgba(16,185,129,0.2)] text-emerald-100 font-fantasy tracking-[0.2em] uppercase hover:bg-emerald-900/40 hover:border-emerald-400 hover:shadow-[0_0_25px_rgba(16,185,129,0.6)] transition-all duration-300 overflow-hidden">
                <span className="relative z-10">Создать</span>
             </button>
         </form>
      </Modal>

      <ConfirmationModal 
        isOpen={confirmState.isOpen}
        title={confirmState.title}
        message={confirmState.message}
        onClose={() => setConfirmState(prev => ({ ...prev, isOpen: false }))}
        onConfirm={confirmState.onConfirm}
        isDangerous
      />
    </div>
  );
};

