                            </div>

                            <div className="bg-slate-900/30 p-3 rounded border-l-2 border-emerald-500">
                                <div className="flex items-center gap-2 text-emerald-400 text-xs font-bold uppercase mb-1">
                                    <MapPin size={14} /> Месторождение
                                </div>
                                <p className="text-sm text-slate-300">
                                    {selectedItem.location || "Неизвестно"}
                                </p>
                            </div>

                            {selectedItem.processing && (
                                <div className="bg-slate-900/30 p-3 rounded border-l-2 border-amber-500">
                                    <div className="flex items-center gap-2 text-amber-400 text-xs font-bold uppercase mb-1">
                                        <Anvil size={14} /> Обработка
                                    </div>
                                    <p className="text-sm text-slate-300 italic">
                                        {selectedItem.processing}
                                    </p>
                                </div>
                            )}
                        </div>

                        {isAdmin && (
                            <div className="mt-4 pt-4 border-t border-slate-800 text-[10px] text-slate-500 font-mono">
                                ID: {selectedItem.id} | Hidden: {selectedItem.is_hidden ? 'YES' : 'NO'} | Rarity: {selectedItem.rarity}/10
                            </div>
                        )}
                    </div>
                )}
            </Modal>
        </div>
    );
};

// Helper for rarity gradient color
const getRarityColor = (r: number) => {
    if (r >= 9) return '#d946ef'; // Legendary (Fuchsia)
    if (r >= 7) return '#8b5cf6'; // Epic (Violet)
    if (r >= 5) return '#3b82f6'; // Rare (Blue)
    if (r >= 3) return '#10b981'; // Uncommon (Emerald)
    return '#64748b'; // Common (Slate)
}

