import React from 'react';
import { CharacterData, TrainingData } from '../types';
import { Card, SectionHeader, Button } from './Shared';
import { Sword, BookOpen, Coffee, CheckCircle, RotateCcw } from 'lucide-react';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  trainingConfig: TrainingData; // Global Limits
  onChange: (t: TrainingData) => void; // Update Character Training
  onGlobalChange?: (t: TrainingData) => void; // Update Global Limits (Admin only)
}

const TabTraining: React.FC<Props> = ({ character, isEditMode, trainingConfig, onChange, onGlobalChange }) => {
  /* [DIALECT] */ const { t } = useDialect();

  // Character's current progress. If undefined, default to 0.
  const charTraining = character.training || { battle: 0, social: 0, study: 0, is_done: false };

  // Helper to update specific field for character
  const updateCharTraining = (field: keyof TrainingData, val: any) => {
      onChange({ ...charTraining, [field]: val });
  };

  // Helper to update global config (Admin)
  const updateGlobal = (field: keyof TrainingData, val: any) => {
      if (onGlobalChange) onGlobalChange({ ...trainingConfig, [field]: val });
  };

  const categories = [
      { id: 'battle', label: 'Боевые (Спарринг)', icon: Sword, color: 'text-red-400', bg: 'bg-red-900/20', border: 'border-red-500/30' },
      { id: 'social', label: 'Небоевые (Социалка)', icon: Coffee, color: 'text-amber-400', bg: 'bg-amber-900/20', border: 'border-amber-500/30' },
      { id: 'study', label: 'Книги (Изучение)', icon: BookOpen, color: 'text-blue-400', bg: 'bg-blue-900/20', border: 'border-blue-500/30' },
  ];

  const totalActions = (charTraining.battle || 0) + (charTraining.social || 0) + (charTraining.study || 0);
  const globalTotal = (trainingConfig.battle || 0) + (trainingConfig.social || 0) + (trainingConfig.study || 0); // Or strict sum logic? Using config provided: "3/4/2/Total"

  return (
    <div className="space-y-6 animate-fade-in">

        {/* Header & Status */}
        <div className="flex flex-col md:flex-row gap-4 justify-between items-start md:items-center bg-slate-900/80 p-4 rounded-lg border border-violet-900/30">
            <div>
                <h3 className="text-lg font-fantasy text-slate-200">Дневной Лимит</h3>
                <p className="text-xs text-slate-500">Отслеживание активности за текущие сутки.</p>
            </div>

            <div className="flex items-center gap-4">
                <div className="text-right">
                    <div className="text-[10px] uppercase font-bold text-slate-500 tracking-widest">Всего действий</div>
                    <div className="font-mono text-xl font-bold text-violet-300">
                        {totalActions} <span className="text-slate-600 text-sm">/ {globalTotal > 0 ? globalTotal : '?'}</span>
                    </div>
                </div>

                {/* Done Toggle */}
                <button 
                    onClick={() => updateCharTraining('is_done', !charTraining.is_done)}
                    disabled={!isEditMode}
                    className={`flex items-center gap-2 px-4 py-2 rounded border transition-all ${charTraining.is_done ? 'bg-emerald-900/30 border-emerald-500 text-emerald-400' : 'bg-slate-800 border-slate-700 text-slate-500'} ${!isEditMode ? 'cursor-default' : 'hover:brightness-110'}`}
                >
                    {charTraining.is_done ? <CheckCircle size={20} /> : <RotateCcw size={20} />}
                    <span className="font-bold uppercase text-xs tracking-wider">{charTraining.is_done ? "Завершено" : "В процессе"}</span>
                </button>
            </div>
        </div>

        {/* Global Config Editor (Admin Only) */}
        {isEditMode && onGlobalChange && (
            <Card className="border-dashed border-violet-500/30 bg-violet-900/10">
                <SectionHeader title="[ГМ] Настройка Лимитов Суток" />
                <div className="grid grid-cols-3 gap-4">
                    {categories.map(cat => (
                        <div key={cat.id} className="flex flex-col gap-1">
                            <label className="text-[10px] uppercase font-bold text-slate-500">{cat.label}</label>
                            <input 
                                type="number" 
                                className="bg-slate-950 border border-violet-900/50 rounded p-2 text-center font-mono font-bold text-white focus:border-violet-500 outline-none"
                                value={trainingConfig[cat.id as keyof TrainingData] as number || 0}
                                onChange={(e) => updateGlobal(cat.id as keyof TrainingData, parseInt(e.target.value))}
                            />
                        </div>
                    ))}
                </div>
            </Card>
        )}

        {/* Character Progress */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {categories.map(cat => {
                const current = charTraining[cat.id as keyof TrainingData] as number || 0;
                const max = trainingConfig[cat.id as keyof TrainingData] as number || 0;
                const percentage = max > 0 ? Math.min(100, (current / max) * 100) : 0;

                return (
                    <Card key={cat.id} className={`relative overflow-hidden ${cat.bg} border-l-4 ${cat.border} border-y border-r border-slate-800`}>
                        <div className="flex justify-between items-start mb-4 relative z-10">
                            <div className="flex items-center gap-2">
                                <cat.icon className={cat.color} size={20} />
                                <span className={`font-bold font-serif ${cat.color}`}>{cat.label}</span>
                            </div>
                            <div className="font-mono text-2xl font-bold text-white opacity-80">
                                {current}
                                <span className="text-sm text-slate-500 ml-1">/ {max}</span>
                            </div>
                        </div>

                        {/* Progress Bar */}
                        <div className="h-2 w-full bg-black/30 rounded-full overflow-hidden mb-4 relative z-10">
                            <div 
                                className={`h-full transition-all duration-500 ${cat.bg.replace('/20', '')}`} 
                                style={{ width: `${percentage}%`, backgroundColor: 'currentColor' }}
                            ></div>
                        </div>

                        {/* Controls */}
                        {isEditMode && (
                            <div className="flex gap-2 relative z-10">
                                <button 
                                    onClick={() => updateCharTraining(cat.id as keyof TrainingData, Math.max(0, current - 1))}
                                    className="flex-1 bg-black/40 hover:bg-black/60 text-slate-400 py-1 rounded text-xs font-bold transition-colors"
                                >
                                    -1
                                </button>
                                <button 
                                    onClick={() => updateCharTraining(cat.id as keyof TrainingData, current + 1)}
                                    className="flex-1 bg-white/10 hover:bg-white/20 text-white py-1 rounded text-xs font-bold transition-colors"
                                >
                                    +1
                                </button>
                            </div>
                        )}

                        {/* Background Decor */}
                        <cat.icon className={`absolute -bottom-4 -right-4 w-24 h-24 opacity-5 ${cat.color}`} />
                    </Card>
                );
            })}
        </div>
    </div>
  );
};

