import React, { useState, useMemo } from 'react';
import { useAuth } from '../../../context/AuthContext';
import { Sword, BookOpen, Coffee, Sun, Moon, Ghost, ChevronLeft, Calendar } from 'lucide-react';
import { CharacterData, Faction } from '../types';

interface TrainingPageProps {
    characters: CharacterData[];
    onBack: () => void;
}

// Mock Data structure for Training Logs
// In real DB: Table 'training_logs' -> { char_id, day, type, value }
type TrainingLog = Record<string, { battle: number, social: number, study: number, is_done: boolean }>; // Key is charId

const MOCK_TRAINING_DB: Record<string, TrainingLog> = {
    '1': {}, // Day 1
    '2': {}  // Day 2
};

const LIMITS = {
    battle: 3,
    social: 4,
    study: 2
};

export const TrainingPage: React.FC<TrainingPageProps> = ({ characters, onBack }) => {
    const { isAdmin } = useAuth();
    const [currentDay, setCurrentDay] = useState<string>('1');
    const [activeFaction, setActiveFaction] = useState<Faction>(Faction.LIGHT);

    // Local state to simulate DB updates
    const [logs, setLogs] = useState<Record<string, TrainingLog>>(MOCK_TRAINING_DB);

    const filteredChars = useMemo(() => {
        return characters.filter(c => {
            // Faction Filter
            if (activeFaction === Faction.NPC) {
                // Show "Minions/Slaves" here
                return c.profile.faction === Faction.NPC && c.profile.npc_volume === "Спутники и Рабы";
            }
            return c.profile.faction === activeFaction;
        });
    }, [characters, activeFaction]);

    const updateValue = (charId: string, type: 'battle' | 'social' | 'study', delta: number) => {
        if (!isAdmin) return;

        setLogs(prev => {
            const dayLog = prev[currentDay] || {};
            const charLog = dayLog[charId] || { battle: 0, social: 0, study: 0, is_done: false };

            const nextVal = Math.max(0, (charLog[type] || 0) + delta);

            // Limit check (optional, but good for UI)
            if (nextVal > LIMITS[type]) return prev; 

            return {
                ...prev,
                [currentDay]: {
                    ...dayLog,
                    [charId]: { ...charLog, [type]: nextVal }
                }
            };
        });
    };

    const toggleDone = (charId: string) => {
        if (!isAdmin) return;
        setLogs(prev => {
            const dayLog = prev[currentDay] || {};
            const charLog = dayLog[charId] || { battle: 0, social: 0, study: 0, is_done: false };

            return {
                ...prev,
                [currentDay]: {
                    ...dayLog,
                    [charId]: { ...charLog, is_done: !charLog.is_done }
                }
            };
        });
    };

    // --- Helpers for Render ---
    const getLog = (charId: string) => {
        return logs[currentDay]?.[charId] || { battle: 0, social: 0, study: 0, is_done: false };
    };

    const getFactionColor = (f: Faction) => {
        switch(f) {
            case Faction.LIGHT: return 'text-amber-400 border-amber-500/30 bg-amber-900/10';
            case Faction.DARK: return 'text-violet-400 border-violet-500/30 bg-violet-900/10';
            case Faction.NPC: return 'text-red-400 border-red-500/30 bg-red-900/10';
            default: return 'text-slate-400';
        }
    };

    return (
        <div className="h-full flex flex-col bg-[#050b14] overflow-hidden relative">
            {/* // здесь задний фон (Placeholder) */}
            <div className="absolute inset-0 bg-slate-950 z-[-1]"></div> 

            {/* Header */}
            <div className="p-4 border-b border-violet-900/30 bg-slate-900/90 backdrop-blur flex items-center justify-between shrink-0">
                <div className="flex items-center gap-4">
                    <button onClick={onBack} className="p-2 hover:bg-white/5 rounded text-slate-400 hover:text-white transition-colors">
                        <ChevronLeft />
                    </button>
                    <h2 className="text-xl font-fantasy font-bold text-white tracking-widest uppercase flex items-center gap-2">
                        <Calendar className="text-violet-500" /> Журнал Тренировок
                    </h2>
                </div>

                <div className="flex items-center gap-2 bg-black/40 rounded p-1 border border-white/10">
                    <button 
                        onClick={() => setCurrentDay('1')}
                        className={`px-4 py-1.5 rounded text-xs font-bold uppercase transition-all ${currentDay === '1' ? 'bg-violet-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
                    >
                        День 1
                    </button>
                    <button 
                        onClick={() => setCurrentDay('2')}
                        className={`px-4 py-1.5 rounded text-xs font-bold uppercase transition-all ${currentDay === '2' ? 'bg-violet-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
                    >
                        День 2
                    </button>
                </div>
            </div>

            {/* Faction Tabs */}
            <div className="flex border-b border-white/5 bg-slate-900/50">
                {[Faction.LIGHT, Faction.DARK, Faction.NPC].map(f => (
                    <button
                        key={f}
                        onClick={() => setActiveFaction(f)}
                        className={`flex-1 py-3 text-xs font-bold uppercase tracking-widest flex items-center justify-center gap-2 transition-all ${activeFaction === f ? getFactionColor(f) + ' border-b-2' : 'text-slate-600 hover:bg-white/5'}`}
                    >
                        {f === Faction.LIGHT && <Sun size={14} />}
                        {f === Faction.DARK && <Moon size={14} />}
                        {f === Faction.NPC && <Ghost size={14} />}
                        {f === Faction.NPC ? "Спутники" : f}
                    </button>
                ))}
            </div>

            {/* Table Header */}
            <div className="grid grid-cols-12 gap-2 px-4 py-2 text-[10px] uppercase font-bold text-slate-500 tracking-wider border-b border-white/5 bg-black/20">
                <div className="col-span-3">Имя</div>
                <div className="col-span-2 text-center">Бой ({LIMITS.battle})</div>
                <div className="col-span-2 text-center">Соц ({LIMITS.social})</div>
                <div className="col-span-2 text-center">Книги ({LIMITS.study})</div>
                <div className="col-span-3 text-center">Статус</div>
            </div>

            {/* Rows */}
            <div className="flex-1 overflow-y-auto custom-scrollbar">
                {filteredChars.map(char => {
                    const data = getLog(char.id);
                    const total = data.battle + data.social + data.study;
                    const maxTotal = LIMITS.battle + LIMITS.social + LIMITS.study; // Rough visual max

                    return (
                        <div key={char.id} className="grid grid-cols-12 gap-2 px-4 py-3 border-b border-white/5 hover:bg-white/5 items-center transition-colors group">

                            {/* Name */}
                            <div className="col-span-3 flex items-center gap-3">
                                <div className="w-8 h-8 rounded bg-slate-800 overflow-hidden shrink-0 border border-slate-700">
                                    {char.meta.avatar_url && <img src={char.meta.avatar_url} className="w-full h-full object-cover" />}
                                </div>
                                <span className={`font-fantasy text-sm ${data.is_done ? 'text-slate-500 line-through' : 'text-slate-200'}`}>{char.profile.name}</span>
                            </div>

                            {/* Battle */}
                            <div className="col-span-2 flex justify-center items-center gap-2">
                                {isAdmin && <button onClick={() => updateValue(char.id, 'battle', -1)} className="w-6 h-6 rounded bg-slate-800 hover:bg-red-900/50 text-slate-400 hover:text-white">-</button>}
                                <span className={`font-mono font-bold w-4 text-center ${data.battle >= LIMITS.battle ? 'text-red-400' : 'text-slate-300'}`}>{data.battle}</span>
                                {isAdmin && <button onClick={() => updateValue(char.id, 'battle', 1)} className="w-6 h-6 rounded bg-slate-800 hover:bg-emerald-900/50 text-slate-400 hover:text-white">+</button>}
                            </div>

                            {/* Social */}
                            <div className="col-span-2 flex justify-center items-center gap-2">
                                {isAdmin && <button onClick={() => updateValue(char.id, 'social', -1)} className="w-6 h-6 rounded bg-slate-800 hover:bg-red-900/50 text-slate-400 hover:text-white">-</button>}
                                <span className={`font-mono font-bold w-4 text-center ${data.social >= LIMITS.social ? 'text-amber-400' : 'text-slate-300'}`}>{data.social}</span>
                                {isAdmin && <button onClick={() => updateValue(char.id, 'social', 1)} className="w-6 h-6 rounded bg-slate-800 hover:bg-emerald-900/50 text-slate-400 hover:text-white">+</button>}
                            </div>

                            {/* Study */}
                            <div className="col-span-2 flex justify-center items-center gap-2">
                                {isAdmin && <button onClick={() => updateValue(char.id, 'study', -1)} className="w-6 h-6 rounded bg-slate-800 hover:bg-red-900/50 text-slate-400 hover:text-white">-</button>}
                                <span className={`font-mono font-bold w-4 text-center ${data.study >= LIMITS.study ? 'text-blue-400' : 'text-slate-300'}`}>{data.study}</span>
                                {isAdmin && <button onClick={() => updateValue(char.id, 'study', 1)} className="w-6 h-6 rounded bg-slate-800 hover:bg-emerald-900/50 text-slate-400 hover:text-white">+</button>}
                            </div>

                            {/* Status */}
                            <div className="col-span-3 flex justify-center">
                                {isAdmin ? (
                                    <button 
                                        onClick={() => toggleDone(char.id)}
                                        className={`px-3 py-1 rounded text-[10px] font-bold uppercase tracking-wider border transition-all ${data.is_done ? 'bg-emerald-900/30 border-emerald-500 text-emerald-400' : 'bg-slate-800 border-slate-600 text-slate-400 hover:border-slate-400'}`}
                                    >
                                        {data.is_done ? 'Завершено' : 'В процессе'}
                                    </button>
                                ) : (
                                    <span className={`text-[10px] font-bold uppercase tracking-wider ${data.is_done ? 'text-emerald-500' : 'text-slate-500'}`}>
                                        {data.is_done ? 'Завершено' : '...'}
                                    </span>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

