            <div className="flex-1 overflow-y-auto custom-scrollbar">
                {isLoading && <div className="text-center py-10 text-slate-500">Загрузка данных...</div>}

                {!isLoading && filteredChars.map(char => {
                    const record = getCharTraining(char.id);
                    const limits = record.limits.split('/').map(Number);
                    const current = record.current[String(day)] || [0, 0, 0, 0, 0];
                    const status = getStatus(current, limits);
                    const isDone = status === "Хватит";

                    return (
                        <div key={char.id} className="grid grid-cols-12 gap-2 px-4 py-3 border-b border-white/5 hover:bg-white/5 items-center transition-colors group text-center text-xs">
                            <div className="col-span-2 text-left flex items-center gap-2 overflow-hidden">
                                {char.meta.avatar_url && <img src={char.meta.avatar_url} className="w-6 h-6 rounded-full border border-slate-700" />}
                                <span className={`truncate font-bold ${isDone ? 'text-slate-500 line-through' : 'text-slate-300'}`}>{char.profile.name}</span>
                            </div>

                            {/* Columns */}
                            {[0,1,2,3,4].map(idx => (
                                <div key={idx} className="col-span-1 odd:col-span-1 even:col-span-2 font-mono text-slate-400">
                                    <span className={current[idx] >= (limits[idx] || 0) ? 'text-green-400 font-bold' : ''}>
                                        {current[idx]}
                                    </span>
                                    <span className="opacity-50">/{limits[idx] || 0}</span>
                                </div>
                            ))}

                            <div className={`col-span-2 uppercase font-bold tracking-wide ${isDone ? 'text-red-500' : 'text-emerald-500'}`}>
                                {status}
                            </div>

                            <div className="col-span-1 flex justify-center">
                                {isAdmin && (
                                    <button 
                                        onClick={() => handleOpenEdit(char.id)}
                                        className="p-1.5 text-slate-500 hover:text-white hover:bg-slate-700 rounded transition-colors"
                                    >
                                        <Settings size={14} />
                                    </button>
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>

            {/* Edit Modal */}
            <Modal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} title="Редактирование Тренировок" size="md">
                <div className="space-y-6">
                    <div className="text-center font-bold text-lg text-violet-300 font-rune">
                        {filteredChars.find(c => c.id === editingCharId)?.profile.name} (День {day})
                    </div>

                    <div className="space-y-1">
                        <label className="text-xs text-slate-500 uppercase font-bold tracking-wider">Лимиты (Строка)</label>
                        <input 
                            className="w-full bg-[#020408] border border-violet-900/40 p-2 rounded text-white font-mono text-sm focus:border-violet-500 outline-none"
                            value={editLimits}
                            onChange={(e) => setEditLimits(e.target.value)}
                            placeholder="3/4/2/2/2"
                        />
                        <div className="text-[10px] text-slate-600">Формат: Бой/Соц/Книги/НастNPC/НастAlien</div>
                    </div>

                    <div className="space-y-3 bg-slate-900/50 p-4 rounded border border-slate-800">
                        {COLUMNS.map((label, idx) => (
                            <div key={idx} className="flex justify-between items-center">
                                <span className="text-sm text-slate-300 font-medium">{label}</span>
                                <div className="flex items-center gap-3">
                                    <button 
                                        onClick={() => {
                                            const next = [...editCurrentValues];
                                            next[idx] = Math.max(0, next[idx] - 1);
                                            setEditCurrentValues(next);
                                        }}
                                        className="w-6 h-6 bg-slate-800 rounded text-slate-400 hover:text-white"
                                    >-</button>
                                    <span className="w-6 text-center font-mono font-bold text-white">{editCurrentValues[idx]}</span>
