                  Продолжить Гостем
               </button>
           </div>
        </div>

        <div className="text-center mt-6">
           <p className="text-[10px] text-slate-600 font-mono">
              SYSTEM v.4.0.4 | RECRUITMENT ACTIVE
           </p>
        </div>
      </div>
    </div>
  );
};

import { createClient } from '@supabase/supabase-js';

// Access environment variables securely
// Vite exposes env variables on import.meta.env
const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY;

if (!supabaseUrl || !supabaseAnonKey) {
  console.error("Supabase URL or Key is missing! Check your .env file or GitHub Secrets.");
}

// Create the Supabase client
// Note: The 'anon' key is safe to expose in the browser IF Row Level Security (RLS) is enabled in your database.
export const supabase = createClient(
  supabaseUrl || '', 
  supabaseAnonKey || ''
);

