import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User } from '../types';
import { supabase } from '../lib/supabase';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  isAdmin: boolean;
  signIn: (email?: string, password?: string) => Promise<void>;
  signUp: (email: string, password: string) => Promise<void>; 
  signInAsGuest: () => Promise<void>;
  signOut: () => Promise<void>;
  triggerAdminSequence: () => void;
  checkAdminCode: (code: string) => boolean; 
  logoutAdmin: () => void; 
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children?: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null); 
  const [isAdmin, setIsAdmin] = useState(false);
  const [isLoading, setIsLoading] = useState(true); // Default to true to wait for session check

  // Secret Sequence State
  const [isListeningForCode, setIsListeningForCode] = useState(false);
  const [inputBuffer, setInputBuffer] = useState("");

  const SECRET_PASS = "admin123";

  // Check admin role from DB
  const checkProfileRole = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('role')
        .eq('id', userId)
        .single();

      if (error) {
        console.warn("[Auth] Failed to fetch profile role. This might be due to missing public.profiles table or RLS policy.", error.message);
        setIsAdmin(false);
        return;
      }

      if (data && data.role === 'admin') {
        setIsAdmin(true);
        console.log("[Auth] Admin privileges confirmed via profile.");
      } else {
        setIsAdmin(false);
        console.log(`[Auth] User role is '${data?.role || 'unknown'}'. Admin access denied.`);
      }
    } catch (e) {
      console.error("[Auth] Unexpected error checking profile role:", e);
      setIsAdmin(false);
    }
  };

  // --- Session Initialization Effect ---
  useEffect(() => {
    const initializeAuth = async () => {
        try {
            // 1. Check active Supabase session
            const { data: { session } } = await supabase.auth.getSession();

            if (session?.user) {
                const realUser: User = {
                    id: session.user.id,
                    email: session.user.email || '',
                    role: 'user'
                };
                setUser(realUser);
                // We check role asynchronously, but user is already logged in
                checkProfileRole(session.user.id);
            } else {
                // 2. Check for persisted Guest session
                const isGuest = localStorage.getItem('juul_d_is_guest');
                if (isGuest === 'true') {
                    setUser({
                        id: 'guest',
                        email: 'guest@void.net',
                        role: 'guest'
                    });
                }
            }
        } catch (error) {
            console.error("Auth initialization error:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initializeAuth();

    // 3. Subscribe to Auth Changes (Sign In, Sign Out, Refresh)
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_OUT') {
            setUser(null);
            setIsAdmin(false);
            localStorage.removeItem('juul_d_is_guest');
        } else if (session?.user && (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED')) {
             const realUser: User = {
                id: session.user.id,
                email: session.user.email || '',
                role: 'user'
            };
            setUser(realUser);
            localStorage.removeItem('juul_d_is_guest'); // Clear guest flag

            if (event === 'SIGNED_IN') {
                await checkProfileRole(session.user.id);
            }
        }
    });

    return () => {
        subscription.unsubscribe();
    };
  }, []);

  const triggerAdminSequence = () => {
    if (isAdmin) return;
    console.log("[System] Identity verification sequence initiated...");
    setIsListeningForCode(true);
    setInputBuffer("");

    setTimeout(() => {
      setIsListeningForCode(false);
      setInputBuffer("");
    }, 5000);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isListeningForCode) return;

      const newBuffer = inputBuffer + e.key;
      setInputBuffer(newBuffer);

      if (newBuffer.includes(SECRET_PASS)) {
        setIsAdmin(true);
        setIsListeningForCode(false);
        console.log("[System] Admin Access Granted via Override.");
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isListeningForCode, inputBuffer]);

  const signIn = async (email?: string, password?: string) => {
    setIsLoading(true);
    try {
        if (email && password) {
            // Attempt real Supabase Auth
            const { data, error } = await supabase.auth.signInWithPassword({ email, password });

            if (error) {
                console.error("Supabase Auth Error:", error.message);
                console.warn("Falling back to demo user due to auth failure. Check console for details.");
                // Fallback demo user - NOT Persisted automatically by Supabase logic above unless we mock it, 
                // but standard flow expects success. If fallback is used, it's ephemeral.
                const demoUser = {
                    id: '12345',
                    email: email,
                    role: 'user' as const
                };
                setUser(demoUser);
                setIsAdmin(false); 
            }
            // Successful data.user is handled by onAuthStateChange
        } else {
            // Legacy / Default mock (No credentials provided)
            setUser({
                id: '12345',
                email: 'traveller@vk.com',
                role: 'user'
            });
        }
    } catch (e) {
        console.error("Unexpected Sign-In Error:", e);
    } finally {
        setIsLoading(false);
    }
  };

  const signUp = async (email: string, password: string) => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase.auth.signUp({
        email,
        password,
      });

      if (error) {
        console.error("Supabase Registration Error:", error.message);
        throw error;
      }

      // onAuthStateChange will handle user state update if session is created
      if (!data.session && data.user) {
          console.log("Registration successful, verify email.");
          // Optionally set a temp state or message, but typically we wait for login
      }
    } catch (e) {
      console.error("Registration Exception:", e);
      throw e;
    } finally {
      setIsLoading(false);
    }
  };

  const signInAsGuest = async () => {
      setIsLoading(true);
      await new Promise(resolve => setTimeout(resolve, 800)); // Fake loading

      localStorage.setItem('juul_d_is_guest', 'true'); // Persist guest state

      setUser({
          id: 'guest',
          email: 'guest@void.net',
          role: 'guest'
      });
      setIsAdmin(false); 
      setIsLoading(false);
  };

  const signOut = async () => {
    setIsLoading(true);
    setIsAdmin(false);
    localStorage.removeItem('juul_d_is_guest');

    await supabase.auth.signOut();

    // Slight delay for UI smoothness
    await new Promise(resolve => setTimeout(resolve, 500));
    setUser(null);
    setIsLoading(false);
  };

  const checkAdminCode = (code: string) => {
    if (code === SECRET_PASS) {
      setIsAdmin(true);
      return true;
    }
    return false;
  };

  const logoutAdmin = () => {
    setIsAdmin(false);
  };

  return (
    <AuthContext.Provider value={{ 
      user, 
      isAuthenticated: !!user, 
      isLoading, 
      isAdmin, 
      signIn, 
      signUp,
      signInAsGuest,
      signOut,
      triggerAdminSequence,
      checkAdminCode,
      logoutAdmin
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

