import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User } from '../types';
import { supabase } from '../lib/supabase';
import bridge from '@vkontakte/vk-bridge';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  isAdmin: boolean;
  signIn: (email?: string, password?: string) => Promise<void>;
  signInWithProvider: (provider: 'google') => Promise<void>;
  signInWithVK: () => Promise<void>;
  signUp: (email: string, password: string) => Promise<void>; 
  signInAsGuest: () => Promise<void>;
  signOut: () => Promise<void>;
  logoutAdmin: () => void; 
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children?: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null); 
  const [isAdmin, setIsAdmin] = useState(false);
  const [isLoading, setIsLoading] = useState(true); // Default to true to wait for session check

  // Check admin role from DB
  const checkProfileRole = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('role')
        .eq('id', userId)
        .single();

      if (error) {
        console.warn("[Auth] Failed to fetch profile role.", error.message);
        setIsAdmin(false);
        return;
      }

      if (data && data.role === 'admin') {
        setIsAdmin(true);
      } else {
        setIsAdmin(false);
      }
    } catch (e) {
      console.error("[Auth] Unexpected error checking profile role:", e);
      setIsAdmin(false);
    }
  };

  // --- Session Initialization Effect ---
  useEffect(() => {
    const initializeAuth = async () => {
        try {
            // 1. Check active Supabase session
            const { data: { session } } = await supabase.auth.getSession();

            if (session?.user) {
                const realUser: User = {
                    id: session.user.id,
                    email: session.user.email || '',
                    role: 'user'
                };
                setUser(realUser);
                checkProfileRole(session.user.id);
            } else {
                // 2. Check for persisted Guest session
                const isGuest = localStorage.getItem('juul_d_is_guest');
                if (isGuest === 'true') {
                    setUser({
                        id: 'guest',
                        email: 'guest@void.net',
                        role: 'guest'
                    });
                }
            }
        } catch (error) {
            console.error("Auth initialization error:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initializeAuth();

    // 3. Subscribe to Auth Changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_OUT') {
            setUser(null);
            setIsAdmin(false);
            localStorage.removeItem('juul_d_is_guest');
        } else if (session?.user && (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED')) {
             const realUser: User = {
                id: session.user.id,
                email: session.user.email || '',
                role: 'user'
            };
            // Only update if different to prevent loops, though React handles this
            setUser(realUser);
            localStorage.removeItem('juul_d_is_guest');

            if (event === 'SIGNED_IN') {
                checkProfileRole(session.user.id);
            }
        }
    });

    return () => {
        subscription.unsubscribe();
    };
  }, []);

  const signIn = async (email?: string, password?: string) => {
    setIsLoading(true);
    try {
        if (email && password) {
            // Attempt real Supabase Auth
            const { data, error } = await supabase.auth.signInWithPassword({ email, password });

            if (error) {
                console.error("Supabase Auth Error:", error.message);
                throw error;
            }

            // Explicitly set user immediately to prevent race conditions with navigation
            if (data.session?.user) {
                const realUser: User = {
                    id: data.session.user.id,
                    email: data.session.user.email || '',
                    role: 'user'
                };
                setUser(realUser);
                await checkProfileRole(data.session.user.id);
            }
        } else {
            // Legacy / Default mock
            setUser({
                id: '12345',
                email: 'traveller@vk.com',
                role: 'user'
            });
        }
    } catch (e) {
        console.error("Sign-In Error:", e);
        throw e; // Rethrow so AuthPage can display error
    } finally {
        setIsLoading(false);
    }
  };

  const signInWithProvider = async (provider: 'google') => {
      setIsLoading(true);
      try {
          // Construct redirect URL to return to the app root (handling subpaths like /Juul-D/)
          let baseUrl = '/';
          try {
              // @ts-ignore
              if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env.BASE_URL) {
                  // @ts-ignore
                  baseUrl = import.meta.env.BASE_URL;
              }
          } catch (e) {
              // Ignore env read errors in sandboxes
          }

          const redirectUrl = window.location.origin + baseUrl;

          const { data, error } = await supabase.auth.signInWithOAuth({
              provider: provider,
              options: {
                  redirectTo: redirectUrl
              }
          });
          if (error) throw error;
      } catch (e) {
          console.error(`OAuth ${provider} Error:`, e);
          throw e;
      } finally {
          // Note: setIsLoading(false) is not called here because OAuth redirects away.
          // It will reset when the page reloads on callback.
      }
  };

  // Custom VK Handler for Mini Apps
  const signInWithVK = async () => {
      setIsLoading(true);
      try {
          // 1. Get VK User Data
          const vkUser = await bridge.send('VKWebAppGetUserInfo');
          if (!vkUser || !vkUser.id) throw new Error("Не удалось получить данные ВК");

          // 2. Generate Synthetic Credentials
          // NOTE: This isn't production-secure for high-stakes apps, but standard for 
          // client-side hobby apps without a backend proxy.
          const fakeEmail = `id${vkUser.id}@vk.juul-d.local`;
          const fakePassword = `vk_secret_${vkUser.id}_secure_salt_v1`;

          // 3. Try to Sign In
          const { data: signInData, error: signInError } = await supabase.auth.signInWithPassword({
              email: fakeEmail,
              password: fakePassword
          });

          // 4. If Sign In fails (User doesn't exist), Sign Up
          if (signInError) {
              const { data: signUpData, error: signUpError } = await supabase.auth.signUp({
                  email: fakeEmail,
                  password: fakePassword,
              });

              if (signUpError) throw signUpError;

              // 5. Update Profile with VK Name/Avatar (Wait for session trigger or force update)
              if (signUpData.user) {
                  // Small delay to ensure triggers ran if any, then upsert
                  await new Promise(r => setTimeout(r, 500));
                  await supabase.from('profiles').upsert({
                      id: signUpData.user.id,
                      full_name: `${vkUser.first_name} ${vkUser.last_name}`,
                      avatar_url: vkUser.photo_200 || vkUser.photo_100,
                      updated_at: new Date()
                  });
              }
          }
      } catch (e: any) {
          console.error("VK Auth Error:", e);
          throw e;
      } finally {
          setIsLoading(false);
      }
  };

  const signUp = async (email: string, password: string) => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase.auth.signUp({
        email,
        password,
      });

      if (error) {
        console.error("Supabase Registration Error:", error.message);
        throw error;
      }

      if (!data.session && data.user) {
          console.log("Registration successful, verify email.");
      }
    } catch (e) {
      console.error("Registration Exception:", e);
      throw e;
    } finally {
      setIsLoading(false);
    }
  };

  const signInAsGuest = async () => {
      setIsLoading(true);
      await new Promise(resolve => setTimeout(resolve, 800)); // Fake loading

      localStorage.setItem('juul_d_is_guest', 'true');

      setUser({
          id: 'guest',
          email: 'guest@void.net',
          role: 'guest'
      });
      setIsAdmin(false); 
      setIsLoading(false);
  };

  const signOut = async () => {
    setIsLoading(true);
    setIsAdmin(false);
    localStorage.removeItem('juul_d_is_guest');

    await supabase.auth.signOut();
    setUser(null);
    setIsLoading(false);
  };

  const logoutAdmin = () => {
    setIsAdmin(false);
  };

  return (
    <AuthContext.Provider value={{ 
      user, 
      isAuthenticated: !!user, 
      isLoading, 
      isAdmin, 
      signIn, 
      signInWithProvider,
      signInWithVK,
      signUp,
      signInAsGuest,
      signOut,
      logoutAdmin
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { Hexagon, LogIn, Key, Mail, User, UserPlus, ArrowRight } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { BackgroundAmbience } from '../components/layout/BackgroundAmbience';

type AuthMode = 'login' | 'register';

const VKIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="currentColor">
        <path d="M13.162 18.994c.609 0 1.016-.217 1.016-.599v-1.018c0-.483.463-.967 1.217-.967 1.35 0 3.078 2.453 4.415 2.584h2.19c1.45 0 .204-2.584-1.928-4.996 1.882-1.777 2.19-2.825 2.023-3.147h-2.357c-1.393 2.013-2.553 2.174-3.078 2.013v-4.188c0-1.127.306-1.611-.532-1.611h-2.903c-.274 0-.462.19-.462.37 0 .387.575.474.634 1.562v3.705c0 .403-.075.644-.37.644-.694 0-2.38-2.545-3.38-5.462H6.975c-.322 0-.398.145-.398.306 0 2.835 3.037 10.806 9.89 10.806h-3.305z"/>
    </svg>
);

const GoogleIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M21.35 11.1h-9.17v2.73h6.51c-.33 3.81-3.5 5.44-6.5 5.44C8.36 19.27 5 16.25 5 12c0-4.1 3.2-7.27 7.2-7.27 3.09 0 4.9 1.97 4.9 1.97L19 4.72S16.56 2 12.1 2C6.42 2 2.03 6.8 2.03 12c0 5.05 4.13 10 10.22 10 5.35 0 9.25-3.67 9.25-9.09 0-1.15-.15-1.81-.15-1.81z"/></svg>
);

export const AuthPage: React.FC = () => {
  const { signIn, signInWithProvider, signInWithVK, signUp, signInAsGuest, isLoading } = useAuth();
  const navigate = useNavigate();

  const [mode, setMode] = useState<AuthMode>('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);

    try {
      if (mode === 'login') {
        await signIn(email, password);
      } else {
        await signUp(email, password);
      }
      navigate('/');
    } catch (err: any) {
      console.error(err);
      setErrorMsg(err.message || "Ошибка авторизации");
    }
  };

  const handleVKClick = async () => {
      console.log("Starting VK Auth...");
      setErrorMsg(null);
      try {
          await signInWithVK();
          navigate('/');
      } catch (err: any) {
          console.error("VK Auth Failed:", err);
          setErrorMsg("Ошибка ВК: " + (err.message || "Не удалось войти"));
      }
  };

  const handleGoogleClick = async () => {
      console.log("Starting Google Auth...");
      setErrorMsg(null);
      try {
          await signInWithProvider('google');
          // Redirect happens automatically by Supabase
      } catch (err: any) {
          console.error("Google Auth Failed:", err);
          setErrorMsg(err.message || "Ошибка входа через Google");
      }
  };

  const handleGuestLogin = async () => {
    await signInAsGuest();
    navigate('/');
  };

  const toggleMode = () => {
    setMode(mode === 'login' ? 'register' : 'login');
    setErrorMsg(null);
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 relative overflow-hidden">
      {/* Ambience Background for Auth */}
      <BackgroundAmbience />

      <div className="relative z-10 w-full max-w-md">
        {/* Logo Area */}
        <div className="flex flex-col items-center mb-8 animate-fadeIn">
           <div className="relative mb-4">
              <div className="absolute inset-0 bg-violet-500 blur-xl opacity-20 rounded-full animate-pulse"></div>
              <Hexagon className="w-16 h-16 text-violet-500 fill-violet-900/20 stroke-[1.5px]" />
              <span className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 font-fantasy font-bold text-xl text-violet-200 tracking-tighter pt-1">JD</span>
           </div>
           <h1 className="font-fantasy text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-violet-200 to-fuchsia-200 tracking-[0.2em] text-center drop-shadow-sm">
             JUUL-D SYSTEM
           </h1>
           <p className="text-slate-500 text-xs uppercase tracking-widest mt-2">
             {mode === 'login' ? 'Идентификация Личности' : 'Регистрация Сущности'}
           </p>
        </div>

        {/* Card */}
        <div className="bg-[#050b14]/80 backdrop-blur-md border border-violet-500/20 p-8 rounded-lg shadow-2xl relative overflow-hidden group">
           <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-violet-500/50 to-transparent"></div>

           {errorMsg && (
             <div className="mb-4 p-3 bg-red-900/20 border border-red-500/30 rounded text-red-200 text-xs text-center font-bold">
               {errorMsg}
             </div>
           )}

           {/* OAuth Buttons - Explicitly type="button" */}
           <div className="grid grid-cols-2 gap-3 mb-6">
                <button 
                    type="button"
                    onClick={handleVKClick}
                    disabled={isLoading}
                    className="flex items-center justify-center gap-2 py-2.5 rounded bg-[#0077FF]/10 border border-[#0077FF]/30 text-[#0077FF] hover:bg-[#0077FF]/20 hover:text-white transition-all font-bold text-sm"
                >
                    <VKIcon /> VK ID
                </button>
                <button 
                    type="button"
                    onClick={handleGoogleClick}
                    disabled={isLoading}
                    className="flex items-center justify-center gap-2 py-2.5 rounded bg-white/5 border border-white/10 text-slate-300 hover:bg-white/10 hover:text-white transition-all font-bold text-sm"
                >
                    <GoogleIcon /> Google
                </button>
           </div>

           <div className="flex items-center gap-4 mb-6">
              <div className="h-px bg-slate-800 flex-1"></div>
              <span className="text-[10px] text-slate-600 uppercase font-bold">Или email</span>
              <div className="h-px bg-slate-800 flex-1"></div>
           </div>

           <form onSubmit={handleAuth} className="space-y-6">
              <div className="space-y-2">
                 <label className="text-xs text-slate-400 font-bold uppercase tracking-wider ml-1">Почта</label>
                 <div className="relative">
                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-600" size={16} />
                    <input 
                      type="email" 
