import React, { useState } from 'react';
import { NavLink, useHistory, useLocation } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { LayoutGrid, Users, Sword, Library, LogOut, Hexagon, ChevronLeft, ChevronRight, X, RefreshCw, AlertCircle } from 'lucide-react';
import { NavItem } from '../../types';
import { CacheService } from '../../utils/cache';

interface SidebarProps {
  isDesktopCollapsed: boolean;
  toggleDesktopSidebar: () => void;
  isMobileOpen: boolean;
  closeMobileSidebar: () => void;
}

const REFRESH_COOLDOWN = 60 * 60 * 1000; // 1 hour in ms
const LAST_REFRESH_KEY = 'juul_d_last_refresh';

export const Sidebar: React.FC<SidebarProps> = ({ 
  isDesktopCollapsed, 
  toggleDesktopSidebar,
  isMobileOpen,
  closeMobileSidebar
}) => {
  const { signOut, user, isAdmin } = useAuth();
  const history = useHistory();
  const location = useLocation();
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [refreshError, setRefreshError] = useState<string | null>(null);

  const navItems: NavItem[] = [
    { label: 'Распутье', path: '/', icon: LayoutGrid },
    { label: 'Летопись Душ', path: '/roster', icon: Users },
    { label: 'Построение Последовательности', path: '/battle', icon: Sword },
    { label: 'Информация о Мире', path: '/lore', icon: Library },
  ];

  const handleLogout = async () => {
    await signOut();
    history.push('/auth');
    if (window.innerWidth < 768) closeMobileSidebar();
  };

  const handleRefreshData = async () => {
      setRefreshError(null);

      if (!isAdmin) {
          const lastRefresh = localStorage.getItem(LAST_REFRESH_KEY);
          if (lastRefresh) {
              const timeSince = Date.now() - parseInt(lastRefresh, 10);
              if (timeSince < REFRESH_COOLDOWN) {
                  const minutesLeft = Math.ceil((REFRESH_COOLDOWN - timeSince) / 60000);
                  setRefreshError(`Ждите ${minutesLeft} мин.`);
                  setTimeout(() => setRefreshError(null), 3000);
                  return;
              }
          }
      }

      setIsRefreshing(true);
      // Clear all cache
      CacheService.clearAll();

      // Update timestamp
      localStorage.setItem(LAST_REFRESH_KEY, Date.now().toString());

      // Simulate a small delay for visual feedback, then reload page to re-fetch fresh data
      setTimeout(() => {
          setIsRefreshing(false);
          window.location.reload();
      }, 800);
  };

  const handleLinkClick = () => {
    if (window.innerWidth < 768) closeMobileSidebar();
  }

  // Helper to split label for styling
  const renderLabel = (label: string) => {
    const parts = label.split(' ');
    if (parts.length > 1) {
        const first = parts[0];
        const rest = parts.slice(1).join(' ');
        return (
            <div className="flex flex-col leading-none">
                <span>{first}</span>
                <span className="ml-4 text-xs opacity-90 pt-1">{rest}</span>
            </div>
        );
    }
    return <span>{label}</span>;
  };

  return (
    <aside 
      className={`
        fixed inset-y-0 left-0 z-50
        bg-[#050b14]/95 backdrop-blur-xl border-r border-violet-500/20 
        flex flex-col transition-[width,transform] duration-300 ease-in-out
        ${isMobileOpen ? 'translate-x-0' : '-translate-x-full'} 
        md:translate-x-0
        ${isDesktopCollapsed ? 'w-20' : 'w-64'}
        overflow-visible shadow-[0_0_50px_rgba(0,0,0,0.5)]
      `}
    >
      {/* Mobile Close Button */}
      <button 
        onClick={closeMobileSidebar}
        className="md:hidden absolute top-2 right-2 text-slate-400 hover:text-white p-2 z-[60] bg-black/50 rounded-full border border-white/10"
      >
        <X size={20} />
      </button>

      {/* Desktop Toggle Button */}
      <button 
        onClick={toggleDesktopSidebar}
        className="hidden md:flex absolute -right-3 top-24 bg-slate-900 border border-violet-500/50 text-violet-300 rounded-full p-1 shadow-[0_0_10px_rgba(139,92,246,0.3)] hover:text-white hover:scale-110 transition-all z-[60]"
      >
        {isDesktopCollapsed ? <ChevronRight size={14} /> : <ChevronLeft size={14} />}
      </button>

      {/* Header / Logo */}
      <div className="h-24 flex items-center justify-center border-b border-violet-500/20 overflow-hidden shrink-0 relative bg-gradient-to-b from-violet-900/10 to-transparent">

        <div 
          className="flex items-center gap-3 cursor-pointer select-none"
          title="Juul-D System"
        >
           <div className={`relative flex items-center justify-center group transition-all duration-300 ${isDesktopCollapsed ? 'scale-110' : ''}`}>
             <div className="absolute inset-0 bg-violet-500 blur-xl opacity-20 group-hover:opacity-40 transition-opacity"></div>
             <Hexagon className={`w-10 h-10 ${isAdmin ? 'text-emerald-500 fill-emerald-900/20' : 'text-violet-500 fill-violet-900/20'} stroke-[1.5px] group-hover:stroke-violet-300 transition-colors relative z-10`} />
             <span className={`absolute font-fantasy font-bold text-sm ${isAdmin ? 'text-emerald-200' : 'text-violet-200'} tracking-tighter pt-0.5 group-hover:text-white transition-colors z-20`}>JD</span>
           </div>

           <h1 
             className={`
               font-fantasy text-2xl font-bold text-transparent bg-clip-text bg-gradient-to-r ${isAdmin ? 'from-emerald-200 to-teal-200' : 'from-violet-200 to-fuchsia-200'} tracking-widest transition-all duration-300 origin-left drop-shadow-sm
               ${isDesktopCollapsed ? 'w-0 opacity-0 scale-0 hidden md:block' : 'w-auto opacity-100 scale-100'}
             `}
           >
             JUUL-D
           </h1>
        </div>
      </div>

      {/* Navigation */}
      <nav className="flex-1 py-6 flex flex-col gap-2 px-3 overflow-y-auto custom-scrollbar overflow-x-hidden">
        {navItems.map((item) => {
          const isActive = item.path === '/' 
            ? location.pathname === '/' 
            : location.pathname.startsWith(item.path);

          return (
            <NavLink
              key={item.path}
              to={item.path}
              onClick={handleLinkClick}
              className={`
                group flex items-center gap-4 px-3 py-3 rounded-lg transition-all duration-300 overflow-hidden relative border border-transparent
                ${isActive 
                  ? 'bg-violet-900/20 text-violet-200 border-violet-500/30 shadow-[0_0_15px_rgba(139,92,246,0.15)]' 
                  : 'text-slate-400 hover:bg-white/5 hover:text-violet-300 hover:border-white/10'
                }
                ${isDesktopCollapsed ? 'justify-center' : ''}
              `}
              title={isDesktopCollapsed ? item.label : ''}
            >
              <item.icon 
                className={`
                  min-w-[24px] w-6 h-6 transition-all duration-300 shrink-0
                  ${isActive ? 'drop-shadow-[0_0_8px_rgba(139,92,246,0.6)]' : ''}
                `} 
              />

              <div 
                className={`
                  font-fantasy tracking-wider text-sm transition-all duration-300 uppercase
                  ${isDesktopCollapsed ? 'opacity-0 w-0 md:hidden' : 'opacity-100 w-auto'}
                `}
              >
                {renderLabel(item.label)}
              </div>

              {isActive && <div className="absolute left-0 top-0 bottom-0 w-1 bg-violet-500 shadow-[0_0_10px_#8b5cf6]"></div>}
            </NavLink>
          );
        })}
      </nav>

      {/* Tools & User Footer */}
      <div className="p-4 border-t border-violet-500/20 shrink-0 bg-black/20">
        <div className="flex flex-col gap-3">

          {/* Refresh / Sync Button */}
          <button
            onClick={handleRefreshData}
            disabled={isRefreshing || !!refreshError}
            className={`
                flex items-center gap-4 px-3 py-2 rounded-lg text-slate-400 border border-transparent transition-all w-full group relative overflow-hidden
                ${refreshError 
                    ? 'border-red-500/30 bg-red-900/10 text-red-400 cursor-not-allowed' 
                    : 'hover:text-emerald-300 hover:bg-emerald-900/10 hover:border-emerald-500/30'}
                ${isDesktopCollapsed ? 'justify-center' : ''}
            `}
            title="Обновить базы данных"
          >
             {refreshError ? <AlertCircle className="w-5 h-5 min-w-[20px] shrink-0" /> : <RefreshCw className={`w-5 h-5 min-w-[20px] shrink-0 ${isRefreshing ? 'animate-spin text-emerald-400' : ''}`} />}
             <span className={`font-fantasy tracking-wider text-xs whitespace-nowrap transition-all duration-300 uppercase ${isDesktopCollapsed ? 'hidden' : 'block'}`}>
                 {isRefreshing ? 'Синхронизация...' : (refreshError || 'Обновить Базы')}
             </span>
          </button>

          {/* Logout */}
          <button 
            onClick={handleLogout}
            className={`
              flex items-center gap-4 px-3 py-2 rounded-lg text-slate-500 hover:text-red-400 hover:bg-red-900/10 border border-transparent hover:border-red-500/30 transition-all w-full
              ${isDesktopCollapsed ? 'justify-center' : ''}
            `}
            title="Выйти"
          >
            <LogOut className="w-5 h-5 min-w-[20px] shrink-0" />
            <span 
              className={`
                font-fantasy tracking-wider text-sm whitespace-nowrap transition-all duration-300 uppercase
                ${isDesktopCollapsed ? 'opacity-0 w-0 md:hidden' : 'opacity-100 w-auto'}
              `}
            >
              Выйти
            </span>
          </button>

          {/* Only show ID if Admin */}
          {user && isAdmin && !isDesktopCollapsed && (
            <div className="flex flex-col px-2 mt-1 animate-fadeIn opacity-50 hover:opacity-100 transition-opacity">
              <span className="text-[10px] truncate font-mono text-emerald-500">{user.email}</span>
            </div>
          )}
        </div>
      </div>
    </aside>
  );
};

import React, { useEffect } from 'react';
import { HashRouter, Switch, Route, Redirect } from 'react-router-dom';
import bridge from '@vkontakte/vk-bridge';
import { AuthProvider, useAuth } from './context/AuthContext';
import { Layout } from './components/layout/Layout';
import { Dashboard } from './pages/Dashboard';
import { AuthPage } from './pages/AuthPage';
import { Loader2 } from 'lucide-react';

// Import Modules
import RosterModule from './modules/roster/App';
import BattleModule from './modules/battle/App';
import LoreModule from './modules/lore/App';

const ProtectedRoute: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isAuthenticated, isLoading } = useAuth();

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#050b14] text-violet-500">
        <Loader2 className="animate-spin w-10 h-10" />
      </div>
    );
  }

  if (!isAuthenticated) {
    return <Redirect to="/auth" />;
  }
  return <Layout>{children}</Layout>;
};

const AppContent = () => {
  const { isAdmin } = useAuth();

  return (
    <HashRouter>
      <Switch>
        <Route path="/auth" component={AuthPage} />

        {/* Protected Routes Wrapper */}
        <Route path="/">
            <ProtectedRoute>
                <Switch>
                    <Route exact path="/" component={Dashboard} />
                    <Route path="/roster">
                        <RosterModule isAdmin={isAdmin} />
                    </Route>
                    <Route path="/battle">
                        <BattleModule isAdmin={isAdmin} />
                    </Route>
                    <Route path="/lore">
                        <LoreModule isAdmin={isAdmin} />
                    </Route>
                    {/* Fallback */}
                    <Redirect to="/" />
                </Switch>
            </ProtectedRoute>
        </Route>
      </Switch>
    </HashRouter>
  );
};

function App() {
  useEffect(() => {
    // <--- 2. Инициализация
    bridge.send("VKWebAppInit");
  }, []);

  return (
    <AuthProvider>
      <AppContent />
    </AuthProvider>
  );
}

export default App;

import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { Hexagon, LogIn, Key, Mail, User, UserPlus, ArrowRight } from 'lucide-react';
import { useHistory } from 'react-router-dom';
import { BackgroundAmbience } from '../components/layout/BackgroundAmbience';

type AuthMode = 'login' | 'register';

const VKIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="currentColor">
        <path d="M13.162 18.994c.609 0 1.016-.217 1.016-.599v-1.018c0-.483.463-.967 1.217-.967 1.35 0 3.078 2.453 4.415 2.584h2.19c1.45 0 .204-2.584-1.928-4.996 1.882-1.777 2.19-2.825 2.023-3.147h-2.357c-1.393 2.013-2.553 2.174-3.078 2.013v-4.188c0-1.127.306-1.611-.532-1.611h-2.903c-.274 0-.462.19-.462.37 0 .387.575.474.634 1.562v3.705c0 .403-.075.644-.37.644-.694 0-2.38-2.545-3.38-5.462H6.975c-.322 0-.398.145-.398.306 0 2.835 3.037 10.806 9.89 10.806h-3.305z"/>
    </svg>
);

const GoogleIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M21.35 11.1h-9.17v2.73h6.51c-.33 3.81-3.5 5.44-6.5 5.44C8.36 19.27 5 16.25 5 12c0-4.1 3.2-7.27 7.2-7.27 3.09 0 4.9 1.97 4.9 1.97L19 4.72S16.56 2 12.1 2C6.42 2 2.03 6.8 2.03 12c0 5.05 4.13 10 10.22 10 5.35 0 9.25-3.67 9.25-9.09 0-1.15-.15-1.81-.15-1.81z"/></svg>
);

export const AuthPage: React.FC = () => {
  const { signIn, signInWithProvider, signInWithVK, signUp, signInAsGuest, isLoading } = useAuth();
  const history = useHistory();

  const [mode, setMode] = useState<AuthMode>('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);

    try {
      if (mode === 'login') {
        await signIn(email, password);
      } else {
        await signUp(email, password);
      }
      history.push('/');
    } catch (err: any) {
      console.error(err);
      setErrorMsg(err.message || "Ошибка авторизации");
    }
  };

  const handleVKClick = async () => {
      console.log("Starting VK Auth...");
      setErrorMsg(null);
      try {
          await signInWithVK();
          history.push('/');
      } catch (err: any) {
          console.error("VK Auth Failed:", err);
          setErrorMsg("Ошибка ВК: " + (err.message || "Не удалось войти"));
      }
  };

  const handleGoogleClick = async () => {
      console.log("Starting Google Auth...");
      setErrorMsg(null);
      try {
          await signInWithProvider('google');
          // Redirect happens automatically by Supabase
      } catch (err: any) {
          console.error("Google Auth Failed:", err);
          setErrorMsg(err.message || "Ошибка входа через Google");
      }
  };

  const handleGuestLogin = async () => {
    await signInAsGuest();
    history.push('/');
  };

  const toggleMode = () => {
    setMode(mode === 'login' ? 'register' : 'login');
    setErrorMsg(null);
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 relative overflow-hidden">
      {/* Ambience Background for Auth */}
      <BackgroundAmbience />

      <div className="relative z-10 w-full max-w-md">
        {/* Logo Area */}
        <div className="flex flex-col items-center mb-8 animate-fadeIn">
           <div className="relative mb-4">
              <div className="absolute inset-0 bg-violet-500 blur-xl opacity-20 rounded-full animate-pulse"></div>
              <Hexagon className="w-16 h-16 text-violet-500 fill-violet-900/20 stroke-[1.5px]" />
              <span className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 font-fantasy font-bold text-xl text-violet-200 tracking-tighter pt-1">JD</span>
           </div>
           <h1 className="font-fantasy text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-violet-200 to-fuchsia-200 tracking-[0.2em] text-center drop-shadow-sm">
             JUUL-D SYSTEM
           </h1>
           <p className="text-slate-500 text-xs uppercase tracking-widest mt-2">
             {mode === 'login' ? 'Идентификация Личности' : 'Регистрация Сущности'}
           </p>
        </div>

        {/* Card */}
        <div className="bg-[#050b14]/80 backdrop-blur-md border border-violet-500/20 p-8 rounded-lg shadow-2xl relative overflow-hidden group">
           <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-violet-500/50 to-transparent"></div>

           {errorMsg && (
             <div className="mb-4 p-3 bg-red-900/20 border border-red-500/30 rounded text-red-200 text-xs text-center font-bold">
               {errorMsg}
             </div>
           )}

           {/* OAuth Buttons - Explicitly type="button" */}
           <div className="grid grid-cols-2 gap-3 mb-6">
                <button 
                    type="button"
                    onClick={handleVKClick}
                    disabled={isLoading}
                    className="flex items-center justify-center gap-2 py-2.5 rounded bg-[#0077FF]/10 border border-[#0077FF]/30 text-[#0077FF] hover:bg-[#0077FF]/20 hover:text-white transition-all font-bold text-sm"
                >
                    <VKIcon /> VK ID
                </button>
                <button 
                    type="button"
                    onClick={handleGoogleClick}
                    disabled={isLoading}
                    className="flex items-center justify-center gap-2 py-2.5 rounded bg-white/5 border border-white/10 text-slate-300 hover:bg-white/10 hover:text-white transition-all font-bold text-sm"
                >
                    <GoogleIcon /> Google
                </button>
           </div>

           <div className="flex items-center gap-4 mb-6">
              <div className="h-px bg-slate-800 flex-1"></div>
              <span className="text-[10px] text-slate-600 uppercase font-bold">Или email</span>
              <div className="h-px bg-slate-800 flex-1"></div>
           </div>

           <form onSubmit={handleAuth} className="space-y-6">
              <div className="space-y-2">
                 <label className="text-xs text-slate-400 font-bold uppercase tracking-wider ml-1">Почта</label>
                 <div className="relative">
                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-600" size={16} />
                    <input 
                      type="email" 
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      className="w-full bg-slate-900/50 border border-slate-700 rounded p-3 pl-10 text-slate-200 text-sm focus:border-violet-500 focus:shadow-[0_0_10px_rgba(139,92,246,0.2)] outline-none transition-all placeholder:text-slate-700"
                      placeholder="traveller@void.com"
                      required
                    />
                 </div>
              </div>

              <div className="space-y-2">
                 <label className="text-xs text-slate-400 font-bold uppercase tracking-wider ml-1">Пароль</label>
                 <div className="relative">
                    <Key className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-600" size={16} />
                    <input 
                      type="password" 
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="w-full bg-slate-900/50 border border-slate-700 rounded p-3 pl-10 text-slate-200 text-sm focus:border-violet-500 focus:shadow-[0_0_10px_rgba(139,92,246,0.2)] outline-none transition-all placeholder:text-slate-700"
                      placeholder="••••••••"
                      required
                      minLength={6}
                    />
                 </div>
              </div>

              <button 
                type="submit" 
                disabled={isLoading}
                className="w-full bg-violet-700 hover:bg-violet-600 text-white font-fantasy uppercase tracking-widest py-3 rounded shadow-[0_0_15px_rgba(139,92,246,0.3)] transition-all flex items-center justify-center gap-2 relative overflow-hidden group/btn"
              >
                 <span className="relative z-10 flex items-center gap-2">
                    {isLoading ? "Обработка..." : (mode === 'login' ? <>Войти <LogIn size={16} /></> : <>Создать <UserPlus size={16} /></>)}
                 </span>
                 <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-700"></div>
              </button>
           </form>

           {/* Toggle Mode */}
           <div className="mt-4 text-center">
             <button 
                type="button"
                onClick={toggleMode}
                className="text-xs text-slate-500 hover:text-violet-300 transition-colors flex items-center justify-center gap-1 mx-auto"
             >
                {mode === 'login' ? "Нет аккаунта? Зарегистрироваться" : "Уже есть аккаунт? Войти"}
                <ArrowRight size={12} />
             </button>
           </div>

           <div className="space-y-3 mt-6 border-t border-slate-800 pt-4">
               <button 
                 type="button"
                 onClick={handleGuestLogin}
                 className="w-full bg-emerald-900/10 hover:bg-emerald-900/20 border border-emerald-500/30 text-emerald-400 py-3 rounded flex items-center justify-center gap-2 font-bold text-sm transition-all hover:shadow-[0_0_15px_rgba(16,185,129,0.2)]"
               >
                  <User className="w-5 h-5" />
                  Продолжить Гостем
               </button>
           </div>
        </div>

        <div className="text-center mt-6">
           <p className="text-[10px] text-slate-600 font-mono">
              SYSTEM v.4.0.5 | RECRUITMENT ACTIVE
           </p>
        </div>
      </div>
    </div>
  );
};

