import React, { useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import bridge from '@vkontakte/vk-bridge';
import { AuthProvider, useAuth } from './context/AuthContext';
import { Layout } from './components/layout/Layout';
import { Dashboard } from './pages/Dashboard';
import { AuthPage } from './pages/AuthPage';
import { Loader2 } from 'lucide-react';

// Import Modules
import RosterModule from './modules/roster/App';
import BattleModule from './modules/battle/App';
import LoreModule from './modules/lore/App';

const ProtectedRoute: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isAuthenticated, isLoading } = useAuth();

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#050b14] text-violet-500">
        <Loader2 className="animate-spin w-10 h-10" />
      </div>
    );
  }

  if (!isAuthenticated) {
    return <Navigate to="/auth" replace />;
  }
  return <Layout>{children}</Layout>;
};

const AppContent = () => {
  const { isAdmin } = useAuth();

  return (
    <HashRouter>
      <Routes>
        <Route path="/auth" element={<AuthPage />} />

        {/* Protected Routes Wrapper */}
        <Route path="/" element={
            <ProtectedRoute>
                <Dashboard />
            </ProtectedRoute>
        } />

        <Route path="/roster" element={
            <ProtectedRoute>
                <RosterModule isAdmin={isAdmin} />
            </ProtectedRoute>
        } />

        <Route path="/battle" element={
            <ProtectedRoute>
                <BattleModule isAdmin={isAdmin} />
            </ProtectedRoute>
        } />

        <Route path="/lore" element={
            <ProtectedRoute>
                <LoreModule isAdmin={isAdmin} />
            </ProtectedRoute>
        } />

        {/* Fallback */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </HashRouter>
  );
};

function App() {
  useEffect(() => {
    // <--- 2. Инициализация
    bridge.send("VKWebAppInit");
  }, []);

  return (
    <AuthProvider>
      <AppContent />
    </AuthProvider>
  );
}

